WordHunterWoW_QuestEN[36140] = { title = "Pandaria 88-90", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[36141] = { title = "Icespine Stingers", description = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior.\n\nThe canyon north of us is full of icespine stingers.  Slaughter them and bring their stingers back to me.  They should work well as bait in these local waters.", objectives = "Prove your worth to Mokugg Lagerpounder by collecting 4 Icespine Stingers.", progress = "Have those stingers for me?", completion = "Not bad traveler, not bad at all." }
WordHunterWoW_QuestEN[36142] = { title = "Sharper Blades, Bigger Timber", description = "Incredible news, Commander {name}. Your ever-loyal servant (that's me) has managed to secure us timber lords. Now maybe you don't know what a timber lord is, so let explain: think of a blood-crazed, mass murderer who enjoys nothing more than killing. Now take that same enthusiasm for killing and apply it to killing trees! That's a timber lord.\n\nWhat this means is that we can now cut medium sized timber - but first we need to give these timber lords a test run.\n\nThere's a suitable tree nearby. Good luck!", objectives = "Harvest a Timber Sample from Timber and return it to Lumber Lord Oktron.", progress = "Did you harvest that timber sample yet?", completion = "You didn't believe me about those timber lords, did you? Well now you know.\n\nIt looks like this group will serve you well, sir. Medium sized trees across Draenor are now at your mercy. That means more timber per tree!" }
WordHunterWoW_QuestEN[36143] = { title = "LFGDungeons - Lich King - Dungeon Normal 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[36144] = { title = "LFG WLK 75-80", description = "", objectives = "You will receive:" }
