WordHunterWoW_QuestEN[36152] = { title = "Cataclysm 84-85", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[36157] = { title = "Spires of the Betrayer", description = "I have much to ask of you, <name>, but before we begin I must ensure that you develop yourself to your full potential. I can help.\n\nI'd like to create a link between us, an artifact that will enhance your power and allow me to track your progress. How do you feel about amulets? No? A ring? I've got it.\n\nMy contacts among the arakkoa outcasts tell of a band of pure solium. Right now it's in the talons of High Sage Viryx high atop Skyreach. Bring me that ring, <name> - you and I have much better uses for it.", objectives = "Collect a Pure Solium Band from High Sage Viryx in Skyreach.", progress = "The arakkoa we see today are a shade of their former glory. They hide atop their spires and glower at the land below, smug and superior. The truth is that they were driven to their lofty perches by the very enemies they look down on today.\n\nI wish the arakkoa were easier to deal with. Their manipulation of the sun's rays could've been an asset to us.", completion = "The ring! You've got it. Feel how it's still warm to the touch? The power of Draenor's sun is locked into the metal. This is perfect, <name>. It is exactly the base material we need to fashion into something amazing.\n\nWhile I prepare your treasure, let's talk about our next steps..." }
WordHunterWoW_QuestEN[36158] = { title = "Draenor's Secret Power", description = "Since we're going to be working so closely together, I'd like to upgrade that ring of yours. Ancient magics are the key: apexis crystals, the leftover remains of an earlier arakkoa civilization! They can be found among the most dangerous creatures around the world.\n\nCollect 4986 crystals for me.\n\nDon't look at me like that. I'm a mage. I did the math. I need exactly 4986 crystals. 4985 is inadequate. 4987 is of course absurd.\n\nFour thousand, nine hundred eighty-six. Go!", objectives = "Gather 4986 Apexis Crystals for Archmage Khadgar. Crystals can be found amongst creatures in the most dangerous parts of the world.", progress = "Do you have the crystals? I hope you kept an accurate count. If you counted wrong I simply can't be held responsible for the consequences.", completion = "Marvelous, marvelous! I will use these to upgrade your ring once we finish up a couple more tasks..." }
WordHunterWoW_QuestEN[36159] = { title = "Nagrand - Vignette Boss 004 - Graveltooth", description = "", objectives = "" }
WordHunterWoW_QuestEN[36160] = { title = "Garrison Campaign: Every Rose Has Its Thorn", description = "These feelings are too strong. I can no longer hide my love away.\n\nI need to tell Thorn the truth. I need to tell Thorn, I love her.\n\nShe mentioned her favorite flower is a rose.  I've been so heads down with my work... I don't even know where I could find a rose on Draenor.", objectives = "Find Baros a rose for Thorn.", progress = "We are under attack!", completion = "Commander! The Burning Blade attacked just a few moments ago, they are looking for the Heart of Gorgorek. \n\nThankfully, Lieutenant Thorn was here to protect us.\n\nWhat? You found a rose? Shh, hand it to me quickly. I'll hold onto this until the time to confess my love is right." }
WordHunterWoW_QuestEN[36161] = { title = "Where There Is Smoke...", description = "Burning Blade assassins have infiltrated the garrison. We must not let them take the Heart of Gorgorek, commander.", objectives = "Kill Rag'sla Thunkblade, Akatha Blazeburn, and Drek the Firecaller.", completion = "The assassin appeared out of nowhere.\n\nBaros took the blade that was meant for my heart. I ripped out the throat of our attacker... but I was too late.\n\nBaros gave me this flower before he passed.\n\n<Thorn holds up the rose. A tear rolls down her cheek.>" }
WordHunterWoW_QuestEN[36162] = { title = "A Stolen Heart", description = "Don't let Azuka take the heart, commander. Don't let her win.", objectives = "Kill Azuka Bladefury.", completion = "Today was not a good day." }
WordHunterWoW_QuestEN[36163] = { title = "Garrison Campaign: The Exarch's Call", description = "Ahhh, just the {race} I were hopin' ta see, my dear.\n\nYrel stopped by the garrison earlier lookin' fer ya. Such a lovely lass, that one! Asked me all about ma family back home when I be feelin' homesick. Bless her. Anyway, what were I goin' on about ag'in?\n\nOh! She asked if ye'd meet her at Elodor to the east.\n\nShe's been invited by the draenei council ta face the Exarch trials, whatever those may be.\n\nAnyway, ye'd better scooch!", objectives = "Speak to Yrel at Elodor in Shadowmoon Valley.", completion = "Thank you for coming, <name>." }
WordHunterWoW_QuestEN[36164] = { title = "The Trial of Courage", description = "An Exarch must be a pillar of strength, and no greater strength is there than the courage to face danger.\n\nFar to the northwest, among the snowy crags of Frostfire Ridge, lives a primal fury named Everburn.\n\nOnly when you face one of these creatures eye to eye, will you know the extent of your courage.", objectives = "Kill Everburn.", completion = "I see that you and Yrel have stared into the eyes of the most primal of the elementals, and not waivered from your path.\n\nIt pleases me to say that your courage is not lacking.\n\nWell done." }
WordHunterWoW_QuestEN[36165] = { title = "No Time to Waste", description = "We're in luck, commander. The antidote is relatively easy tae make.\n\nI've made a small amount with what I had on me. You should take it tae Kolrigg before it's too late. It'll keep him alive long enough for me tae make more.", objectives = "Administer the Spiresalve to Kolrigg Stoktron in Southport.", progress = "<Kolrigg grumbles incoherently.>", completion = "By Muradin's beard... what a headache..." }
WordHunterWoW_QuestEN[36166] = { title = "No Time to Waste", description = "Commander, we're in luck. The antidote recipe is fairly simple.\n\nI was able to make a small amount with what I had on me. You should take it to Lunzul before it's too late. It should keep her alive long enough for me to make more.", objectives = "Administer the Spiresalve to Lunzul in Axefall.", progress = "<Lunzul grumbles incoherently.>", completion = "By da spirits... me head be hurtin'..." }
WordHunterWoW_QuestEN[36167] = { title = "The Trial of Heart", description = "The Trial of Heart is a test of your willingness to persevere in the face of great adversity.\n\nFar to the west, there is a rangari outpost at Cerulean Lagoon.\n\nThey have sent a request for help. Some sort of infection is making everyone in the area sick. They desperately need aid.\n\nGo and seek out the rangari stationed there. Help them find the cause of this terrible ailment.", objectives = "Speak to Yrel at Cerulean Lagoon, then find out the cause of the poisonous mist.", completion = "News of your deeds precedes you. Rangari Saardar already sent word of your excellent work.\n\nThanks to the both of you, <name>." }
WordHunterWoW_QuestEN[36168] = { title = "The Trial of Faith", description = "No Exarch trial is complete without a holy pilgrimage to the sacred resting place of our fallen champions.\n\nOn the way, I ask that you take Vindicator Maraad's ashes and lay them to rest within the hallowed halls of Auchindoun.\n\nThere, the spirits of our fallen ancestors will test Yrel's greatest weakness.\n\nGood luck.", objectives = "Speak to Soulbinder Tuulani outside the entrance to Auchindoun, then pass the Trial of Faith.", completion = "It seems you have been successful in your journey.\n\nHow do I know this? If you had not passed the challenge of the ancestors, you would not have returned at all." }
WordHunterWoW_QuestEN[36169] = { title = "The Trial of Champions", description = "The first three trials you have passed with flying colors.\n\nFor the final trial, you shall face the Exarch Council.\n\nSpeak to me when you are ready to begin.", objectives = "Defeat the Exarch Council.", completion = "Well done, champion. Well done." }
WordHunterWoW_QuestEN[36170] = { title = "Treasure: Femur of Improbability", description = "", objectives = "" }
WordHunterWoW_QuestEN[36171] = { title = "Botani Invasion!", description = "The plants seem different today. Grass blades bend against the wind and catch on my boots. Twice this morning a tree branch struck my helmet as it fell.", objectives = "Repel the botani invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", progress = "We must hold the line!", completion = "We beat back nature, Commander. May I be excused? I'd like to get all this sap out of my armor." }
WordHunterWoW_QuestEN[36174] = { title = "Nagrand - Treasure 081 - Bounty of the Elements", description = "", objectives = "" }
WordHunterWoW_QuestEN[36176] = { title = "A Call for Huntsman", description = "<The note is barely legible, but it seems to be an advertisement for a local hunting competition out of Embaari Village.>\n\n\"Any and all competitors are welcome to test their skills in a friendly hunting challenge.\"", objectives = "Deliver the Dirty Note to Fanara in Embaari Village to join the competition.\n\nProvided item:", completion = "Another competitor for the competition? How wonderful! Garaal will be pleased!" }
WordHunterWoW_QuestEN[36177] = { title = "Friendly Competition", description = "So you wish to join the competition, {name}? Best of luck to you.\n\nBe the first to gather a sack full of hides and talons from local wildlife and return them to me before the other competitors!\n\nWinner earns the opportunity for an apprenticeship under craftsman Garaal.\n\nGood luck!", objectives = "Gather 4 Shadowmoon Hides and 3 Silverwing Talons and return to Fanara before the other competitors.", progress = "The satchel is full and ready for delivery.", completion = "Congratulations, <name>! You did it!\n\nThe other competitors are nowhere to be found!\n\nGaraal will be most pleased. With such an abundance of supplies to work with he and the other craftsmen will have no trouble staying busy.\n\nI'll start tanning these immediately. They'll be ready for delivery in just a moment." }
WordHunterWoW_QuestEN[36178] = { title = "Vignette: Mandrakor the Night Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[36179] = { title = "Unwanted Pests", description = "Those creatures out in the shallows keep busting the turrets as fast as we can get them operational.\n\nI'm supposed to go clear them out but my blaster is completely busted; the damn thing barely can light a candle like this!\n\nCould you do me a favor and go kill a few of those pests while I get my blaster fixed at the shop?\n\nJust let Gazwitz know you covered for me so I can get reimbursed for the repair.", objectives = "Kill 10 Spore Drifters or Fungal Hulks in Sporemist Shallows.", completion = "Lemmy's gun broke down again I take it?\n\nGood job covering for 'em out there. I could use more workers like you!" }
WordHunterWoW_QuestEN[36182] = { title = "Tree-i-cide", description = "Commander, the goblins have brought you a present. They call it the Tree Murderer 9000.\n\nWhat's it do? I reckon it murders trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot!\n\nThere's a large piece of timber ready to be murdered nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", objectives = "Harvest a Timber Sample from Large Timber and return it to Lumber Lord Oktron.", progress = "Did you harvest that timber sample yet?", completion = "This is fantastic! This sample indicates massive timber reserves in the large timber found across Draenor. And now with the Tree Murderer 9000 at your disposal you'll be able to chop those towering monstrosities down with ease." }
WordHunterWoW_QuestEN[36183] = { title = "Admiral Taylor", description = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself.\n\nWe never heard from him again, but we have our orders.\n\nPlease... please find him. He went towards the farm.", objectives = "Find Admiral Taylor at Admiral Taylor's Farm.", completion = "From one commander to another... thank you.\n\nWe've faced off on the field of battle so many times. Vashj'ir... the Jade Forest... Lion's Landing...\n\nI am glad I could end my journey with such a worthy adversary." }
WordHunterWoW_QuestEN[36184] = { title = "Mother Lode", description = "", objectives = "" }
WordHunterWoW_QuestEN[36185] = { title = "Fair Trade", description = "Alright. Here you go.\n\nBe sure to deliver them to Garaal quickly. He has a heavy interest in detail and fine craftsmanship. He'll surely appreciate your work.", objectives = "Garaal awaits your delivery.\n\nProvided item:", completion = "Greetings, <name>.\n\nFanara mentioned the competition was fierce this year.\n\nMy, my. These goods should keep me busy for an entire season!\n\nAs the victor of the competition one usually becomes my apprentice, however, your skills are surely in need of no apprenticeship.\n\nPerhaps a trade is in order.\n\nI'll keep your delivery and share the goods with our local craftsmen and in return, I'll share some of our knowledge with you." }
WordHunterWoW_QuestEN[36186] = { title = "Vignette: Greldrok the Cunning", description = "", objectives = "" }
WordHunterWoW_QuestEN[36188] = { title = "Moving On Up", description = "A generous decision, <name>.\n\nYou have demonstrated your skills as a hunter, delivered a piece worthy of your name and proven your dedication to your craft. Please, take this as a token of my gratitude.\n\nMay the light guide your hand and passion, your heart.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Garaal has offered to further your knowledge in leatherworking.A generous decision, <name>.\n\nYou have demonstrated your skills as a hunter, delivered a piece worthy of your name and proven your dedication to your craft. Please, take this as a token of my gratitude.\n\nMay the light guide your hand and passion, your heart.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[36189] = { title = "Easing into Lumberjacking", description = "Sir, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work.\n\nWhile I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree a lumberjack will come chop it down and give you the timber.\n\nLet's give our lumberjacks a test run. There's a tree nearby!", objectives = "Harvest a Timber Sample from Small Timber and return it to Justin Timberlord.", progress = "This garrison isn't going to build itself, commander! We need timber!", completion = "You're going to make a fine overseer, sir! Keep those lumberjacks in line!\n\nNow you know the basics of logging and finding timber. Time to put them to good use for the good of your garrison." }
WordHunterWoW_QuestEN[36192] = { title = "Turning Timber into Profit", description = "Now that you know how to put lumberjacks to work harvesting timber, we're going to create a work order for your mill.\n\nBut first we're going to need some timber to process!\n\nAll around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order.\n\nAnd as usual, let the lumberjacks do the hard work. Just keep 'em protected. Draenor's a dangerous place!", objectives = "Collect 10 pieces of Timber from around Draenor and then Place a Work Order at your Garrison's Lumber Mill.", progress = "We need lots and lots of timber, commander!", completion = "That's how it's done, commander!\n\nWe're now fully operational. Any time you have enough timber to place a work order, come on back to me and we'll get started.\n\nThis garrison ain't gonna build itself!" }
WordHunterWoW_QuestEN[36193] = { title = "An Act of Kindness", description = "I know that you and Vindicator Yrel are here on important matters, but I must ask you a favor.\n\nA squad of rangari left on patrol just before the poisonous mist set in.\n\nIf they were caught out in the swamp, they are surely in trouble.\n\nHarvest the Restorative Goldcaps growing among the reeds, and use them to restore any fallen rangari that you find.\n\nIf you find yourself in trouble, eat one to combat the poison.", objectives = "Use Restorative Goldcaps to revive fallen rangari.", progress = "Were you able to find the others?", completion = "Thank the Light! All of the rangari who were missing have returned accounted for. Thank you, hero." }
WordHunterWoW_QuestEN[36194] = { title = "Sharper Blades, Bigger Timber", description = "Incredible news, Commander {name}. Your ever-loyal servant has managed to secure us commandojacks. Now maybe you don't know what a commandojack is, so let me explain: they're like lumberjacks, only highly trained in the art of killing. Mostly they're out of work mercenaries and assassins.\n\nWhat this means is that we can now cut medium sized timber - but first we need to give these commandojacks a test run.\n\nThere's a suitable tree nearby. Good luck!", objectives = "Harvest a Timber Sample from Timber and return it to Justin Timberlord.", progress = "Did you harvest that timber sample yet?", completion = "We haven't even scratched the surface when it comes to overkill.\n\nIt looks like this group will serve you well, sir. Medium sized trees across Draenor are now at your mercy. That means more timber per tree!" }
WordHunterWoW_QuestEN[36195] = { title = "Tree-i-cide", description = "Commander, your engineers have brought you a present. They call it the Wood Annihilator XXI the Third, Jr.\n\nWhat's it do? I reckon it annihilates trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot!\n\nThere's a large piece of timber ready to be annihilated nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", objectives = "Harvest a Timber Sample from Large Timber and return it to Justin Timberlord.", progress = "Did you harvest that timber sample yet?", completion = "This is fantastic! This sample indicates massive timber reserves in the large timber found across Draenor. And now with the Wood Annihilator XXI the Third, Jr. at your disposal you'll be able to chop those towering monstrosities down with ease.\n\nGet off my back, I didn't name it." }
WordHunterWoW_QuestEN[36196] = { title = "Welcome to Ashran", description = "Greetings, and welcome to Ashran. \n\nReport to General Ushet Wolfbarger in Warspear for your orders.", objectives = "Speak to General Ushet Wolfbarger  in Warspear.", completion = "You've just now showed up? Well, better late than never." }
WordHunterWoW_QuestEN[36197] = { title = "Reporting For Duty", description = "Front and center, <name>! No time to waste, go speak with these fellows and they'll fill you in.", objectives = "Speak to Cymre Brightblade, Mare Wildrunner and Zurge.", completion = "Yea, that Zurge really is angry isn't he?" }
WordHunterWoW_QuestEN[36198] = { title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran.\n\nGo out and kill any you find and bring at least five Artifact Fragments to Fura the Mage in Warspear Outpost.", objectives = "Cymre Brightblade in Warspear Outpost wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 5 Artifact Fragments to Fura.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort." }
WordHunterWoW_QuestEN[36199] = { title = "Moonshell Claws", description = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior.\n\nThe beach southeast of us is full of moonshell crawlers.  Slaughter them and bring their claws back to me.  They should work well as bait in these local waters.", objectives = "Prove your worth to Madari by collecting 4 Moonshell Claws.", progress = "Have those claws for me?", completion = "Not bad traveler, not bad at all." }
WordHunterWoW_QuestEN[36201] = { title = "Proving Your Worth", description = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the moonshell claws you brought me. Use it to catch the shadow sturgeon in these coastal waters.", objectives = "Prove your worth to Madari by catching 5 Shadow Sturgeon using the supplied bait.", progress = "Catch those sturgeon?", completion = "I see you are both a fisherman and a warrior.  I will do what I can to help you." }
WordHunterWoW_QuestEN[36202] = { title = "Anglin' In Our Garrison", description = "You have proven your worth, traveler.  Now take this eventide fishing journal back to your garrison and study up.  You will be catching all you can eat in no time.", objectives = "Return to Ron Ashton with the Eventide Fishing Journal.", progress = "We can use that as bait?!", completion = "Look at all the bait ideas in this thing! Great job <name>!" }
WordHunterWoW_QuestEN[36203] = { title = "Treasure: Goren Egg", description = "", objectives = "" }
WordHunterWoW_QuestEN[36204] = { title = "Vignette: Gorger the Hungry", description = "", objectives = "" }
WordHunterWoW_QuestEN[36205] = { title = "The Fractured Hammer", description = "It is obvious that this elaborate smithing hammer has seen better days.\n\nNow fractured and dirty, it is merely a shadow of its former self.\n\nOne thing is certain, its previous owner was neither ogre nor Iron Horde.\n\nPerhaps someone at Stonefang Outpost would know who this belongs to.", objectives = "Search Stonefang Outpost for the hammer's previous owner.", progress = "What do you want, <race>?", completion = "My father's hammer, where did you find this!?" }
WordHunterWoW_QuestEN[36206] = { title = "The Dragon's Tale", description = "Chromie thinks she's picked up the trail. We suspect that Garrosh traveled through here when he first arrived on Draenor. But what about Kairoz? He must be close.\n\nChromie will illuminate the clues. Look for a series of temporal anomalies. Follow the trail east of here and pick your way up to the top of the mountains until we've located Kairozdormu... or his body. Good luck!", objectives = "Follow the trail of clues up the hillside until you discover Kairozdormu in the Time-Lost Glade.", completion = "That solves one riddle. The moment they arrived in Draenor, Garrosh killed his savior.\n\nHe left the job unfinished; The dragon's spirit is still restless.\n\nI hope you're ready for a fight." }
WordHunterWoW_QuestEN[36207] = { title = "Waruk the Frostforger", description = "Many say my father was a legendary blacksmith, Waruk the Frostforger they called him. They will tell you tales of his mighty weapons, crafted with nothing more than ice and steel. Waruk the Lieforger, I call him.\n\nHe promised he wouldn't be gone long, \"I must support our troops!\" he said.\n\nWhy did he have to go? Why did they let him get captured!?\n\nI have no more need for broken tools than I do broken promises. His grave is east of here, you can leave this with the rest of his unwanted belongings.", objectives = "Deliver Waruk's hammer to his grave site.", progress = "Greetings <race>, what brings you to this old orc's grave?", completion = "Where did you find this hammer!?" }
WordHunterWoW_QuestEN[36208] = { title = "The Crystal Shard", description = "I'm glad you arrived when you did.\n\nThe Laughing Skull orcs practice some strange spirit magic, but one of their traditions could be quite useful in our situation.\n\nWhile I make preparations, can you gather the reagents?\n\nFirst, we'll need crystals from the husks of goren corpses. You can find their bodies in the canyon.", objectives = "Collect 25 Goren Crystals from Longtooth Gorgers.", progress = "I have learned some of the Laughing Skull traditions. This is less strange than many.", completion = "Goren crystals are used by some as weapons. The acid left behind can be deadly though, even to the wielder." }
WordHunterWoW_QuestEN[36209] = { title = "What's Under There?", description = "It is done.\n\nWith this enchantment, not only can you roam amongst the goren freely, but you can move as they do.\n\nYour travels through the canyon are now made easier. You have safe access to places otherwise impossible to reach.\n\nPerhaps these tunnels will lead to more information that could be used against the Iron Horde.", objectives = "Use the goren disguise to explore locations in Gorgrond.", progress = "That goren disguise smells awful.", completion = "Your search brought rewards?" }
WordHunterWoW_QuestEN[36210] = { title = "Hard Shell", description = "I have already learned much from watching the Laughing Skull.\n\nTraveling through goren tunnels was thought to be impossible due to the acid they leave behind, but the orcs found a way around it.\n\nWe will need some of the shells of goren within the canyon.\n\nIf you see any of their tunnel craters ready to burst, approach them and goren will come pouring out. This way, you can kill many at once and find the shells more quickly.", objectives = "Collect 9 Goren Shells from Boneyard Gorgers.", progress = "Goren seem willing to eat anything in their path, alive or otherwise.", completion = "Ah, yes, these shells will work perfectly." }
WordHunterWoW_QuestEN[36211] = { title = "6.0 Tanaan - Boots Bootstrap", description = "", objectives = "" }
WordHunterWoW_QuestEN[36212] = { title = "6.0 Tanaan - Wrist Bootstrap", description = "", objectives = "" }
WordHunterWoW_QuestEN[36213] = { title = "6.0 Tanaan - Ring Bootstrap", description = "", objectives = "" }
WordHunterWoW_QuestEN[36214] = { title = "6.0 Tanaan - Hands Bootstrap", description = "", objectives = "" }
WordHunterWoW_QuestEN[36219] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nWho am I kidding, who wouldn't be interested in fame, fortune, and brawlin'? I'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you." }
WordHunterWoW_QuestEN[36220] = { title = "How Tough Are You?", description = "Mogor's holding a special match over at the Ring of Blood to crown the new Blood Champion and I think you have what it takes!\n\nNow, these ogres respect one thing and one thing only: badass...ness. They have a big fella at the front door making sure only the toughest gladiators enter the proving grounds.\n\nIf you're in, kill the grizzled gladiator Lug'dol at the tower just up the road and present his head to Kroggol the Wall. That oughta show 'em what you're made of.", objectives = "Kill Lug'dol and present his head to Kroggol the Wall outside the Gorian Proving Grounds.", progress = "Nobody gets in da proving grounds unless I say so.", completion = "If you kill Lug'dol, you definitely belong in da proving grounds.\n\nI don't even care that you tiny not ogre!" }
WordHunterWoW_QuestEN[36221] = { title = "Entry Fee", description = "You looking for da Ring of Blood? HAH! That good one. Not just anybody able to compete in da ring. You gotta pay the entry fee: fifty blood marks.\n\nHow do you get them? Oh, tiny one, you killing me!\n\n<Kroggol hands you a small stone caked in blood.>\n\nDat one is yours. You kill others in da proving grounds to get da rest. Take dem to Wodin da troll servant by Mogor when you done.\n\nDon't talk to Mogor, though. Mogor da boss.", objectives = "Gather 50 Blood Stones and bring them to Wodin the Troll Servant.", progress = "Don't be wastin' my time, <race>. What business do you be havin' with Mogor?", completion = "You? Fightin' ta be da Blood Champion? Hmm." }
WordHunterWoW_QuestEN[36222] = { title = "The Champion of Blood", description = "You have da blood stones required as proof of your worth. Hmm. Yes, you might be da champion Mogor be lookin' for.\n\nYou be one of only two to complete da blood stone trial. Da two of ya be fightin' for da glory of becoming Blood Champion.\n\nSpeak to Gurgthock and we be seein' if you be a champion... or just another stain on da arena floor.", objectives = "Speak to Gurgthock to participate in the Blood Champion fight.", progress = "Only da very best be havin' a chance at bein' da Blood Champion, mon.", completion = "You did it, mon! I never thought I'd be seein' such a fight!" }
WordHunterWoW_QuestEN[36223] = { title = "Leave Every Soldier Behind", description = "The ogron possess something of value to the Iron Horde. I am sure they're unaware, likely just bored and in need of something to torture.\n\nWe could simply leave them to their fate, but we should follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond's most fearsome creatures into weapons.\n\nTry to find Corporal Thukmar and his notes.", objectives = "Find Corporal Thukmar and recover his intel.", progress = "Again you've done well, friend.", completion = "We have the notes. Let us see what they reveal about our enemy's strategy." }
WordHunterWoW_QuestEN[36226] = { title = "Survey Ashran", description = "As a Farseer, I can peer into the far corners of Ashran while within Warspear. But you must go forth and see it for yourself, <name>.", objectives = "Farseer Mare Wildrunner in Warspear wants you to explore The Road of Glory, The Molten Quarry, Brute's Rise, The Amphitheater Of Annihilation and The Ashmaul Burial Grounds in Ashran.", completion = "You have the spirit of a true explorer, <name>." }
WordHunterWoW_QuestEN[36227] = { title = "The Road of Glory", description = "THE ALLIANCE! <Stomps feet> THEY NEED TO BE REMOVED FROM ASHRAN IMMEDIATELY! MARCH INTO THE ROAD OF GLORY AND SLAY AS MANY AS YOU CAN! \n\nNOW!", objectives = "Zurge in Warspear wants you to kill 5 members of the Alliance within the Road of Glory.", completion = "ONLY FIVE? UGH. TAKE THIS REWARD AND GET BACK OUT THERE." }
WordHunterWoW_QuestEN[36228] = { title = "Into The Wilderness", description = "YOU KNOW WHAT'S BETTER THAN KILLING ALLIANCE SCUM IN THE ROAD OF GLORY?\n\nKILLING THEM EVERYWHERE ELSE. <Laughs>\n\nGO INTO THE OUTSKIRTS OF ASHRAN AND SLAY ANY ALLIANCE MEMBER. BRING ME BACK SCRAPS OF THEIR DISGUSTING ARMOR AS PROOF. THE BLOODIER THE BETTER.", objectives = "Zurge in Warspear Outpost wants you to kill a member of the Alliance outside of the main road and recover a piece of their armor as proof.", progress = "SHOW ME THE ARMOR SCRAPS!", completion = "YES... YES! <Takes a deep whiff of the armor scrap> MMMM,  ITS FRESH!" }
WordHunterWoW_QuestEN[36229] = { title = "Nagrand - Vignette Boss - Mr. Pinchy Sr.", description = "", objectives = "" }
WordHunterWoW_QuestEN[36230] = { title = "The Restless Spirit", description = "This hammer was once used to craft magnificent weapons for my Frostwolf brothers and sisters.\n\nWhen I was taken prisoner by the Thunderlords, however, I refused to wield it. How could I craft weapons to be used against my own people?\n\nIt saddens me to see that it has been damaged and abused.\n\nI wished to one day pass it down to Kugra, but now, her anger prevents her from even visiting my grave.\n\nPlease {name}, can you help me repair my hammer and seek revenge on those that caused this?\n\nFor Kugra....", objectives = "Slay Kurgthuk the Merciless and use Waruk's hammer to salvage equipment from the Thunderlord orcs.", progress = "So, it is done?", completion = "<name>, thank you for avenging my death." }
WordHunterWoW_QuestEN[36236] = { title = "The Cryptic Tome of Tailoring", description = "The different sections of the tome describe tailoring techniques that seem strange compared to traditional methods.\n\nThe author's name does not appear anywhere in the tome. Maybe someone in your garrison knows more about the book's origins.", objectives = "Speak to Aerun in your garrison.", progress = "What have you there, child?", completion = "It seems that you have found a very special tailoring book.\n\nIt belongs to Ameeka, a tailor of great renown from Embaari Village." }
WordHunterWoW_QuestEN[36238] = { title = "Mending A Broken Heart", description = "{name}, thank you for avenging my death... but I have just one more favor to ask of you.\n\nIf you help me see this through, I will forever be in your debt.\n\nTake these items and meet me at the forge in Stonefang Outpost.\n\nI have imbued them with a portion of my essence, but we still need the aid of another to reforge the hammer.\n\nIt is time for me to reconcile with Kugra, so that we both may finally find peace....", objectives = "Meet Waruk at Stonefang Outpost.", progress = "My father... but, how did you....", completion = "This entire time... I have been so consumed with my own grief.\n\nI never once stopped to consider how much my father was suffering at the hands of our enemies.\n\nThank you so much, <class>, for helping him to return to me. Please, allow me to repair his hammer.\n\nIn exchange for everything you have done for us, I will teach you whatever you wish to know." }
WordHunterWoW_QuestEN[36239] = { title = "A Mysterious Satchel", description = "An empty satchel with an old, magical aura.\n\nIt appears quite dilapidated, with remnants of herbs and mushrooms along the inner lining. Perhaps exploring Umbrafen will offer a clue.", objectives = "Find the satchel's owner.\n\nProvided item:", completion = "Oh, my. One of my satchels! Where did you find this? I lost it weeks ago.\n\nI've been so busy training I forgot to collect herbs for Master Ardule. I need your help <name>, if you are willing, but I must warn you - the herbs can be quite dangerous!\n\nHand me the satchel and I'll restore the protective inscription to guard you from harmful toxins." }
WordHunterWoW_QuestEN[36240] = { title = "Slow and Steady", description = "Excellent!\n\nWhen you've collected enough herbs from the local wildlife, return to me and I'll craft them into an ink for Master Ardule.\n\nThe sporebats and giants should have what you're looking for.\n\nAnd remember, be careful!", objectives = "Gather the herbs and return to Sha'la.", progress = "Ah, these are just what I was looking for!", completion = "That was fast, <name>! And such a generous delivery!\n\nI've secured the ink in a vial for you, but please be careful." }
WordHunterWoW_QuestEN[36241] = { title = "The Power of Preservation", description = "The ink is very precious to our people. It has the ability to preserve ancient texts.\n\nMaster Ardule can explain further. He's just inside.", objectives = "Deliver the ink to Master Ardule.", completion = "My, <name>. Your delivery...\n\nI don't know how to thank you enough.\n\nThis is a substantial amount of ink. You've helped ensure our history for generations to come.\n\nPerhaps I can repay you with a taste of the very knowledge you've helped preserve?" }
WordHunterWoW_QuestEN[36242] = { title = "Where There Is Smoke...", description = "You garrison is under attack by the Burning Blade!\n\nKill the Burning Blade masters that are leading the assault and report back to Warmaster Zog.", objectives = "Kill Rag'sla Thunkblade, Akatha Blazeburn, and Drek the Firecaller.", completion = "I knew it was only a matter of time before Azuka would make her move." }
WordHunterWoW_QuestEN[36243] = { title = "Spires - Treasure 001 - Outcast's Basket", description = "", objectives = "" }
WordHunterWoW_QuestEN[36244] = { title = "Spires - Treasure 002 - Misplaced Scrolls", description = "", objectives = "" }
WordHunterWoW_QuestEN[36245] = { title = "Spires - Treasure 004 - Relics of the Outcasts", description = "", objectives = "" }
WordHunterWoW_QuestEN[36246] = { title = "Spires - Treasure 005 - Fractured Sunstone", description = "", objectives = "" }
WordHunterWoW_QuestEN[36247] = { title = "Spires - Treasure 007 - Lost Herb Satchel", description = "", objectives = "" }
WordHunterWoW_QuestEN[36248] = { title = "A Stolen Heart", description = "This invasion is clearly an attempt to seize the Heart of Gorgorek.\n\nWe need to fortify our guard before it's too late!", objectives = "Defeat Azuka Bladefury.", completion = "Azuka's reign of terror continues... we need a new plan." }
WordHunterWoW_QuestEN[36249] = { title = "Active Choice: Lumber Mill", description = "", objectives = "" }
WordHunterWoW_QuestEN[36250] = { title = "Active Choice: Lumber Mill", description = "", objectives = "" }
WordHunterWoW_QuestEN[36251] = { title = "Active Choice: Sparring Arena", description = "", objectives = "" }
WordHunterWoW_QuestEN[36252] = { title = "Active Choice: Sparring Arena", description = "", objectives = "" }
WordHunterWoW_QuestEN[36254] = { title = "Spires - Vignette Boss 002 - Tesska the Broken", description = "", objectives = "" }
WordHunterWoW_QuestEN[36255] = { title = "Enchanted Highmaul Bracer", description = "A powerful enchantment emanates from these ancient Highmaul bracers.\n\nMaybe Yu'rina the Mystic, your garrison enchanting quartermaster, can tell you more about the bracer.", objectives = "Take the bracer to Yu'rina the Mystic in your Garrison.\n\nProvided item:", completion = "Interesting, an Arakkoa recently visited the garrison looking for an armor piece with a powerful enchantment like this. His name was Delath.\n\nThe enchantment on this bracer is beyond my skill, but perhaps this Delath can give you the necessary insight to replicate it." }
WordHunterWoW_QuestEN[36256] = { title = "The Arakkoan Enchanter", description = "The arakkoa said it was going to investigate an anomaly in the Cracking Plains that might be related to another armor piece.", objectives = "Find Delath on the edge of the Cracking Plains to the north.", progress = "Greetings Enchanter. I can see you are acquainted with the art. \n\nGood, good. Perhaps you and I can help each other.", completion = "Do I also detect that you have in your possession an artifact of our land? \n\nCan I see it?\n\nOne of Oru'kai's bracers... Thank you!" }
WordHunterWoW_QuestEN[36257] = { title = "Failed Apprentice", description = "Oru'kai was the first ogre mage to master the art of enchanting. Upon his death, his items were scattered across Draenor. I have tracked his scepter to the field you see before us. \n\nAs you can see, the scepter's enchantment is making it difficult to retrieve. A would-be apprentice, Torag Stonefury, took one of Oru'kai's rings in to break the enchantment, but he failed and became trapped in ice. \n\nFree Torag, take the ring, and complete his task, and I will consider a reward.", objectives = "Find and release Torag from his icy prison.", completion = "Thank you. I thought I was going to be stuck here forever." }
WordHunterWoW_QuestEN[36260] = { title = "Oru'kai's Scepter", description = "If I had known being an enchanter was this dangerous, I would have stayed in Wor'gol. \n\nHere, take this ring. The bird man told me to use the ring on the scepter to nullify the enchantment.\n\nBring the scepter back to him and maybe he will teach you what he promised to teach me.", objectives = "Retrieve Oru'kai's scepter and return it to Delath.", progress = "Do you have it? Give it to me.", completion = "Yes... This is it, after so many years. Soon, I will have all of the Armaments of Oru'kai.\n\nReturn my ring as well and I will fulfill the promise I made to that squeamish orc. \n\nTake this book. If you have any skill, you can use it to decipher and learn Draenor's enchantments. \n\nOf course, you will need a proper workplace as well. Here are plans; hopefully you can follow them.\n\nNow, be gone, and steer clear of the other armaments, for they are mine." }
WordHunterWoW_QuestEN[36261] = { title = "Garrison Campaign: Missing Grunt", description = "With the Heart of Gorgorek residing inside the garrison walls, we need to stay vigilant. The Burning Blade are known for attacking swiftly, and without warning.\n\nI have a number of grunts patrolling the keep. Dul'zak, one of our newer recruits, should have reported back by now.", objectives = "Find Dul'zak." }
WordHunterWoW_QuestEN[36262] = { title = "Ameeka, Master Tailor", description = "Ameeka created this book to document and pass down our most cherished crafting techniques to our children. She must have dropped it while traveling. She will be relieved to see her book.\n\nFrom what I have heard from other villagers, she was last seen on the road to Elodor. Perhaps you can find her there.", objectives = "Speak to Ameeka in Elodor.", progress = "Hello, traveler! Is there something that I can help you with?", completion = "Is that my tailoring tome? It is! I'm so glad it is safe! How can I ever repay you?" }
WordHunterWoW_QuestEN[36263] = { title = "A Strengthened Bond", description = "This entire time... I have been so consumed with my own grief.\n\nI never once stopped to consider how much my father was suffering at the hands of our enemies.\n\nThank you so much <class> for helping him to return to me. Please, allow me to repair his hammer.\n\nIn exchange for everything you have done for us, I will teach you whatever you wish to know.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Give Axe-Shaper Kugra the Ghost-Touched Materials." }
WordHunterWoW_QuestEN[36265] = { title = "Spires - Vignette Boss 001 - Stonespite", description = "", objectives = "" }
WordHunterWoW_QuestEN[36266] = { title = "The Clothes on Their Backs", description = "Such kindness you have shown me, perhaps I can ask for one more?\n\nIn our village, we salvage and reuse old cloth to patch clothes and light armor. Sadly, most of my supply was taken or destroyed in the recent attacks.\n\nThe Shadowmoon cultists might think twice about stealing from us if you were to relieve them of their own resources.\n\nIf you can collect some ceremonial Shadowmoon robes for me, I will demonstrate some of my favorite tailoring techniques for you.", objectives = "Collect 10 Ceremonial Shadowmoon Robes.", progress = "Were you able to get the robes?", completion = "Again, you show me great kindness.\n\nNow, let us begin." }
WordHunterWoW_QuestEN[36267] = { title = "Spires - Vignette 005 - Durkath Steelmaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[36268] = { title = "Spires - Vignette Boss 007 - Kalos the Bloodbathed", description = "", objectives = "" }
WordHunterWoW_QuestEN[36269] = { title = "Hexcloth", description = "I shall now impart to you the finer points of creating hexcloth.\n\nThe process is quite simple. It involves immersing carefully woven fur into the ichor drawn from Gorgrond Flytraps.\n\nNormally, you would need to harvest it yourself, but I actually managed to liberate some from the Shadowmoon during their last raid.\n\nYou are welcome to use it.", objectives = "Use Ameeka's Flytrap Ichor to create a Swatch of Hexweave.", progress = "Were you successful, friend?", completion = "This is perfect! The cloth and magic are perfectly balanced and stable.\n\nI am happy to say that you have learned the basics of my tailoring methods. I respect your skill and your eagerness to learn new techniques.\n\nLet me give you some other patterns and materials that I hope you find useful during your journey." }
WordHunterWoW_QuestEN[36271] = { title = "Breaking into the Trap Game", description = "When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here.\n\nWe can get a load of leather from the elekk, or furs from the talbuk, right here in Shadowmoon.\n\nTake this iron trap and use it on a wounded adult talbuk or elekk, then bring the trap on back here and we'll start a work order.", objectives = "Use the Iron Trap to capture an Elekk or Talbuk in Shadowmoon Valley and then place a Work Order at your Barn.", progress = "Have you tried your hand at trapping yet?", completion = "Great job, commander! We'll have your leather or fur ready in no time.\n\nNow that you know how to use the trap, it will be available for your use at any time. We can only handle so many beasts in the barn at one time, though, so make sure you've got room before you start trapping!" }
WordHunterWoW_QuestEN[36272] = { title = "Feeding An Army", description = "We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one!\n\nMind giving 'er a run, commander? The Improved Iron Trap will let you capture some of the meatiest wildlife, like the big boars and riverbeasts out in Gorgrond. We'll be able to turn them into some tasty steaks.", objectives = "Use the Improved Iron Trap to capture a Boar or Riverbeast in Gorgrond and then place a Work Order at your Barn.", progress = "Did ya try the trap out yet?", completion = "Great work, commander! We'll get to grillin' up those steaks right away. I can already smell them!" }
WordHunterWoW_QuestEN[36273] = { title = "Whacking Weeds", description = "Something needs to be done about the podling menace in Spiteleaf Thicket!\n\nAlongside Hemet Nesingwary, I've hunted some of the largest and most terrifying beasts around. Never in my life have I encountered a creature as vile, depraved, nefarious or degenerate as a podling!\n\nThe vicious little monsters spread themselves like weeds and if something isn't done, they'll spread across the entire continent!\n\nMake your way into Spiteleaf Thicket and slay as many podlings as you can find!", objectives = "Slay 20 Spiteleaf podlings.", completion = "Great work, <name>.\n\nI'm surprised we made it out of Spiteleaf Thicket alive! I can still hear the sound of their maniacal laughter as they swarmed us...." }
WordHunterWoW_QuestEN[36274] = { title = "Bigger Trap, Better Rewards", description = "Good news, commander! With the materials we've gathered here in Draenor, we've been able to construct a trap strong enough to immobilize even the mightiest beast!\n\nWhy don't you head on out to Nagrand and give it a try? Word has it that the western plains are home to some of the most magnificent beasts this side of Crystal Lake.\n\nI'm going to warn you, though, these beasts are tough. You may want to bring some friends along.", objectives = "Use the Deadly Iron Trap to capture an Ironhide Bull, Direfang Alpha, or Wetland Trampler.", progress = "Well? How'd it go?", completion = "That must have been quite a fight, commander!\n\nThe materials we obtain from beasts of this magnitude will last us for quite a while." }
WordHunterWoW_QuestEN[36275] = { title = "The Search For Research", description = "My research notes are missing!\n\nThey must have gone missing during the podling attack on the research station. All of my work will be lost if they are not found!\n\nCome to think of it, I'm also missing my expedition supply bag, as well as my anti-fungal boots....\n\nHow can I do biological research without my equipment?!\n\nNo... this will not do at all.\n\nPlease, go and search the Zangar Shore for my missing belongings so that I may continue my fungal research!", objectives = "Return the Research Journal, Expedition Supplies, and Anti-fungal Boots to Dr. Hadley Ricard.", progress = "Have you retrieved my missing belongings?", completion = "Ah! I see you have my research with you... and what's this? You also have my supply bag and the anti-fungal boots!\n\nSpectacular! I now have the tools I need to continue my research into the Zangar fungal strain...." }
WordHunterWoW_QuestEN[36276] = { title = "Spires - Vignette Boss 008 - Spawn of Sethe", description = "", objectives = "" }
WordHunterWoW_QuestEN[36277] = { title = "Warlords Max Level Dungeon Bonus Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[36278] = { title = "Spires - Vignette Boss 009 - Talonbreaker", description = "", objectives = "" }
WordHunterWoW_QuestEN[36279] = { title = "Spires - Vignette 010 - Poisonmaster Bortusk", description = "", objectives = "" }
WordHunterWoW_QuestEN[36280] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nYou're the one that brought a new meaning to pain at the Ring of Trials not too long ago, right? This is the next step in your climb to fame! You've gotta get down here.\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you." }
WordHunterWoW_QuestEN[36281] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nIf you think the Stonemaul arena was a thrill, this is way, way bigger than that. It's going to be HUGE, I'm calling it now.\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you." }
WordHunterWoW_QuestEN[36282] = { title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. You're the talk of the arena, friend! I mean, the Ring of Trials? Stonemaul? You're killing it out there!\n\nI've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you." }
WordHunterWoW_QuestEN[36283] = { title = "Spires - Vignette Boss 011 - Blightglow", description = "", objectives = "" }
WordHunterWoW_QuestEN[36284] = { title = "A Fascinating Fungus", description = "The Zangar Shore is home to many peculiar strains of fungi, some of which are similar to those of our native Azeroth. However, one strain in particular is most fascinating!\n\nI call it \"Zangarium Draenormycota,\" due to its prevelance in Draenor's fungal ecosystem. This unique strain of fungus is highly adaptable and can be found on many of the living organisms throughout Zangar Shore.\n\nWhy does it exist? What properties does it hold?\n\nTo answer these questions, I will need additional spore samples.", objectives = "Collect 12 Fungal Spores.", progress = "Have you collected the spore samples for my research?", completion = "You have the spore samples for my research! Excellent!\n\nThe Zangar Shore is a dangerous place... what with the risk of fungal mutation and all.\n\nOh... I didn't mention that part before? I was sure I did!\n\nNo matter! You look hardy enough, I'm sure your genes are impervious to foreign fungal strains that your body has never before encountered!" }
WordHunterWoW_QuestEN[36285] = { title = "Dirgemire", description = "In order to fully understand the nature and properties of the Zangarium Draenormycota, I need to examine the strain within a complex fungal structure. The fungal brain of a spore giant would do nicely.\n\nNot just any spore giant will serve though, it needs to be big... mean... primordial... the perfect specimen!\n\nIn a cavern deep below the surface is an ancient spore giant the locals fearfully refer to as Dirgemire. Slay the monster, but be sure to carefully preserve the fungal brain for our research!", objectives = "Retrieve the Fungal Brain from Dirgemire.", progress = "Without a fungal brain to examine, the mysteries of the Zangar ecosystem will remain unsolved!", completion = "I see you've retrieved Dirgemire's fungal brain!\n\nNot only is the fungal structure perfectly intact, as a specimen it is exquisite! I will need only a moment to begin the examination..." }
WordHunterWoW_QuestEN[36286] = { title = "Transponder 047-B", description = "The back of the transponder is etched in scribbled writing.\n\n<URGENT: If found, please return to Goggles near Eledor. It is of the utmost importance!>\n\n", objectives = "Return the transponder to Goggles.\n\nProvided item:", completion = "Oh my! What do we have here, commander?\n\n<Inspecting the transponder.>\n\nA little damaged, slightly bent and burnt to a crisp, but this is my lucky day!\n\nWe've been testing a new device and this transponder carries invaluable information! I'll have Bixx extract the coordinates for mapping.\n\nJust a few more parts and I should be able to teleport anything across this entire valley! And I do mean anything!\n\nThat'll surely help our reinforcements stand against the Iron Horde!" }
WordHunterWoW_QuestEN[36287] = { title = "Snatch 'n' Grab", description = "We were able to map all of the data from the transponder you recovered! Now our location analyzer is complete!\n\nWe're just missing a few final pieces, then the real testing begins.\n\nOne of my pilots mentioned seeing a beached Iron Horde ship over by the shore. If you can salvage some parts we may just be able to get this thing up and running!", objectives = "Search the beach for salvageable parts.", progress = "Don't worry. We're just borrowing these from the Iron Horde!", completion = "Those supplies were just what I needed! I think I'm finally figuring out how to work with all these Draenor parts. I'd be happy to show you, commander. I should be able to fix it in a jiffy.\n\nOh... and remember, deep breaths!" }
WordHunterWoW_QuestEN[36288] = { title = "Spires - Vignette Boss 012 - Oskiira", description = "", objectives = "" }
WordHunterWoW_QuestEN[36289] = { title = "Out of the Shadows", description = "Congratulations again, Blood Champion. You be fightin' like nobody I ever seen.\n\nWhile you were in da ring, one ayour bruddas came by and asked for you ta return ta your base. He called himself Bodrick Grey.", objectives = "Speak to Bodrick Grey at your Garrison.", completion = "We'll need to keep an eye on this Azuka Bladefury character. Sounds dangerous." }
WordHunterWoW_QuestEN[36290] = { title = "Out of the Shadows", description = "Congratulations, Blood Champion. You be fightin' like nobody I ever seen.\n\nWhile you were in da ring, one a your bruddas came by and asked for you ta return ta your base. He called himself a shadow hunter.", objectives = "Speak to Rokhan in your Garrison.", completion = "We best be keepin' an eye on dis Azuka Bladefury. She be bad news." }
WordHunterWoW_QuestEN[36291] = { title = "Spires - Vignette Boss 014 - Betsi Boombasket", description = "", objectives = "" }
WordHunterWoW_QuestEN[36292] = { title = "Investigating the Invasion", description = "I'm going to lead a small squad behind enemy lines.\n\nMeet me by Dreadmaul, {class}. From there we can decide our next course of action.", objectives = "Meet Thrall behind enemy lines.", completion = "Glad you made it, <name>. It's time to start pushing back on this Iron Horde invasion." }
WordHunterWoW_QuestEN[36293] = { title = "It's Gotta Work!", description = "My apprentice Nubble was able to use your salvaged parts to put the finishing touches on the new location analyzer.\n\nHead on over to try out my newest invention!", objectives = "Visit Nubble." }
WordHunterWoW_QuestEN[36294] = { title = "Phylarch the Evergreen A", description = "", objectives = "" }
WordHunterWoW_QuestEN[36295] = { title = "Phylarch the Evergreen B", description = "", objectives = "" }
WordHunterWoW_QuestEN[36296] = { title = "Phylarch the Evergreen", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", completion = "For tens of thousands of years we Botani have clashed against the mightiest forces of this world, but none have had your unbridled ferocity and resilience.\n\nI... I concede to your battle prowess. I will aid you in your campaign for dominance of my world.\n\nIf you will accept me." }
WordHunterWoW_QuestEN[36297] = { title = "Spires - Vignette Boss 016 - Festerbloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[36298] = { title = "Spires - Vignette Boss 017 - Sunderthorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[36301] = { title = "Trega's Tailoring Kit", description = "The bag is filled with patterns and unfamiliar tailoring tools. You find the name \"Trega\" embroidered on the inside of the bag.\n\nYou seem to recall seeing her in Wor'gol. With any luck, she's still there.", objectives = "Find Trega in Wor'gol.", progress = "That's my sewing kit! I never thought I would see this again.", completion = "I was chased by ogres and had to leave my bag behind. It looks like almost everything is here, except for... oh, no!" }
WordHunterWoW_QuestEN[36303] = { title = "Spires - Vignette Boss 019 - Eyeless", description = "", objectives = "" }
WordHunterWoW_QuestEN[36304] = { title = "Spires - Vignette Boss 022 - Gochar", description = "", objectives = "" }
WordHunterWoW_QuestEN[36305] = { title = "Spires - Vignette Boss 023 - Gobblefin", description = "", objectives = "" }
WordHunterWoW_QuestEN[36306] = { title = "Spires - Vignette Boss 024 - Jiasska the Sporegorger", description = "", objectives = "" }
WordHunterWoW_QuestEN[36307] = { title = "Investigating the Invasion", description = "I'm going to lead a small squad behind enemy lines.\n\nMeet me by Dreadmaul, {class}. From there we can decide our next course of action.", objectives = "Meet Maraad behind enemy lines.", completion = "Glad you made it, <name>. It's time to start pushing back on this Iron Horde invasion." }
WordHunterWoW_QuestEN[36308] = { title = "Enchanted Highmaul Bracer", description = "A powerful enchantment emanates from these ancient Highmaul bracers.\n\nMaybe Eileese Shadowsong, your garrison enchanting quartermaster, can tell you more about the bracer.", objectives = "Take the bracer to Eileese Shadowsong in your Garrison.\n\nProvided item:", completion = "Interesting, an Arakkoa recently visited the garrison looking for an armor piece with a powerful enchantment like this. His name was Delath.\n\nThe enchantment on this bracer is beyond my skill, but perhaps this Delath can give you the necessary insight to replicate it." }
WordHunterWoW_QuestEN[36309] = { title = "The Strength of Iron", description = "A stitched patch along the side of the satchel clearly identifies its owner.\n\nYou remember hearing stories of a great blacksmith just north of Embaari.", objectives = "Deliver the satchel to Haephest.\n\nProvided item:", completion = "This... this is my satchel... but how?\n\nDid you see a boy - a young boy near this? You must tell me where you found it!\n\nI tried to fight them, but the looters... they were too strong! They almost killed me!\n\nPlease, please....\n\nI'd give anything to have my only son back! I cannot fail him...." }
WordHunterWoW_QuestEN[36310] = { title = "The Arakkoan Enchanter", description = "The arakkoa said it was going to investigate an anomaly along the Forgotten Shore that might be related to another armor piece.", objectives = "Find Delath on the Forgotten Shore to the south.", progress = "Greetings Enchanter. I can see you are acquainted with the art. \n\nGood, good. Perhaps you and I can help each other.", completion = "Do I also detect that you have in your possession an artifact of our land? \n\nCan I see it?\n\nOne of Oru'kai's bracers... Thank you!" }
WordHunterWoW_QuestEN[36311] = { title = "Father and Son", description = "Please find my boy!\n\nBefore the looters came we were on the hill just northeast of here.\n\nThere weren't many of them, but I'm a blacksmith, not a fighter!\n\nHave I let my only son down?", objectives = "Find Haephest's son.", completion = "My boy!\n\n<A tear falls down his cheek, clearing a path down to the skin where soot once rested.>\n\nYou... no words can explain how grateful I am.\n\nI can only repay what I have to offer, which isn't much in terms of valued goods. Most of my work goes straight to our soldiers.  I do, however, carry the wisdom of my people and my craft.\n\nIt would be an honor if you allowed me to share some of this wisdom with you.\n\nMay the light guide you, <name>." }
WordHunterWoW_QuestEN[36312] = { title = "Spires - Vignette Boss 025 - Sun Sage Valarik", description = "", objectives = "" }
WordHunterWoW_QuestEN[36313] = { title = "Failed Apprentice", description = "Oru'kai was the first ogre mage to master the art of enchanting on Draenor. Upon his death, his items were scattered across Draenor. I have tracked his staff to the shore you see before us. \n\nAs you can see, the staff's enchantment is making it difficult to retrieve. A would-be apprentice, Deema, took one of Oru'kai's rings in to break the enchantment, but she failed and became trapped as well. \n\nFind and free Deema, take the ring, complete her task, and I will consider a reward.", objectives = "Find and release Deema from her time prison.", completion = "Thank you. I thought I was going to be stuck here forever." }
WordHunterWoW_QuestEN[36314] = { title = "The Intricate Pendant", description = "The crimson gem used in this pendant is unlike any you've seen before, and the filigree wrapped around it is masterfully crafted.\n\nThere's likely to be much you can learn from the person who made this. Perhaps someone at your garrison will recognize the work.", objectives = "Ask around your garrison to see if anyone recognizes the pendant.", progress = "Why hello <name>, what do we have here?", completion = "Please, allow me to take a closer look." }
WordHunterWoW_QuestEN[36315] = { title = "Oru'kai's Staff", description = "If I had known being an enchanter was this dangerous, I would have stayed in Shattrath. \n\nHere, take this ring. The arakkoa told me to use the ring on the staff to nullify the enchantment.\n\nBring the scepter back to him and maybe he will teach you what he promised to teach me.", objectives = "Retrieve Oru'kai's staff and return it to Delath.", progress = "The staff! Give it to me!", completion = "Yes... This is it, after so many years. Soon, I will have all of the Armaments of Oru'kai.\n\nReturn my ring as well and I will fulfill the promise I made to that squeamish draenei. \n\nTake this book. If you have any skill, you can use it to decipher and learn Draenor's enchantments. \n\nOf course, you will need a proper workplace as well. Here are plans; hopefully you can follow them.\n\nNow, be gone, and steer clear of the other armaments, for they are mine." }
WordHunterWoW_QuestEN[36316] = { title = "Victory is Within Reach", description = "We have dealt a crippling blow to the Adherents, but our fight is not yet finished.\n\nGather your allies and prepare for the final siege on Skyreach!\n\n\"Shadows gather when the raven swallows the day.\n\nBurning sky is extinguished as black wings fold gently about the heavens.\n\nRest, my children, rest. For even the sun must sleep.\"\n\nThis was Rukhmar's lullaby, sung by her to the first arakkoa. My, how we've lost our way.", objectives = "Slay Ranjit, Araknath, Rukhran and High Sage Viryx in the Skyreach dungeon.", progress = "Let us finish what we have started.", completion = "Perhaps there is now hope for a brighter future. I can only hope some of those in Skyreach have been awakened." }
