WordHunterWoW_QuestEN[36358] = { title = "A Father and His Son", description = "We must hurry before more orcs arrive! My father works just down this path!\n\nWe'll be safe at his shop.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Return Duna and the toolset to Haephest." }
