WordHunterWoW_QuestEN[36404] = { title = "Clearing the Garden", description = "This clearing is the perfect spot to grow herbs for our Garrison, there is just one little problem.  All these dang raccoons!\n\nI need you to clear them out and we can get this garden growing.", objectives = "Kill 8 Lunarfall Raccoons.", progress = "Did you get 'em?", completion = "Great work, <name>! We will get started planting the garden right away." }
WordHunterWoW_QuestEN[36405] = { title = "Spires - Treasure 051 - Offering to the Raven Mother 02", description = "", objectives = "" }
