WordHunterWoW_QuestEN[36408] = { title = "A Power Lost", description = "<The fragment gleams in the light as its aura's final pulse fades.>\n\nThe power within the fragment appears to be drained.\n\nYou recall hearing travelers speak of a local in Embaari Village who specializes in imbuing gems with magic.", objectives = "Find someone in Embaari Village well-versed in gemology and magic.\n\nProvided item:", completion = "What have you got here...\n\nOnly a keen eye would be able to spot the potential of this drained crystal. You may not be familiar with draenei crystals yet, but your familiarity with gems certainly shows.\n\nTell you what... if you would assist me in the troubles we're having with our local defense crystals I'd gladly share some of my own expertise in jewelcrafting with you." }
WordHunterWoW_QuestEN[36409] = { title = "Restoration", description = "As mentioned, our larger defense crystals have been drained of power, creating gaps in our defenses. The crystal you brought me is only a reminder of the severity of this situation. It's Shadowmoon magic to blame, I'm sure of it.\n\nOne of our rangari scouts spotted an orc fleeing north, past Palemoon Village, and into the valley beyond. Go, find this orc, and see if you can't retrieve whatever vessel he's storing the power inside of. If we get it back, I'm sure I can restore the crystals.", objectives = "Retrieve the sample for Artificer Baleera.", progress = "The crystal's power pulses as it is carried.", completion = "You've found it! This crystal is overflowing with energy. This is definitely what we were looking for.\n\nI fear even thinking about what kind of ritual this orc was planning to undergo with the power from this crystal.\n\nYou've done a great thing for us, <class>. As promised, I would like to show you my appreciation by teaching you how to work with some of our native gems and crystals. I trust you will put the knowledge to good use." }
WordHunterWoW_QuestEN[36410] = { title = "Spires - Treasure 054 - Offering to the Raven Mother 05", description = "", objectives = "" }
WordHunterWoW_QuestEN[36411] = { title = "Spires - Treasure 014 - A Lost Ring", description = "", objectives = "" }
WordHunterWoW_QuestEN[36412] = { title = "Shadowmoon Invasion!", description = "Scouts report that the Shadowmoon clan is buzzing like a kicked hornets' nest. Time again to earn our pay, Commander?", objectives = "Repel the Shadowmoon clan invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", progress = "We must hold the line!", completion = "You were a blaze amongst our foes, Commander. It looks like we'll see another dawn in Draenor." }
WordHunterWoW_QuestEN[36413] = { title = "A Power Restored", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[36414] = { title = "Shadowmoon Invasion!", description = "Scouts say the Shadowmoon clan looms close, ready with their necromancy. If I die and rise again, Commander, finish me quickly. I don't want to be a ghoul.", objectives = "Repel the Shadowmoon clan invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", progress = "We must hold the line!", completion = "Nothing like a little righteous bloodshed, to shake the chill from these old bones." }
WordHunterWoW_QuestEN[36415] = { title = "Spires - Treasure 020 - Reagent Pouch", description = "", objectives = "" }
WordHunterWoW_QuestEN[36416] = { title = "Spires - Treasure 049 - Misplaced Scroll", description = "", objectives = "" }
WordHunterWoW_QuestEN[36417] = { title = "From Their Cold Dead Hands", description = "Those ogres took all of my hexweave!\n\nI kept it hidden at the bottom of my bag. How could they possibly know of its importance?\n\nIf they discover even a portion of hexweave's properties, it means trouble for us all.\n\n{name}, this is a Frostwolf problem. It requires a Frostwolf solution.\n\nWill you help me?", objectives = "Collect 10 Damaged Hexweave from Bladespire Ogres.", progress = "Well, is it done?", completion = "This looks to be all of the cloth, but it appears that they tried to rip and pull the magic out by physical force. I think I see teeth marks..." }
WordHunterWoW_QuestEN[36418] = { title = "Spires - Treasure 013 - Dark Grimoire", description = "", objectives = "" }
WordHunterWoW_QuestEN[36419] = { title = "Dyed in the Fur", description = "I can't believe they tried to physically rip the magic out of the material!\n\nIt seems we were never in danger of my secrets falling into the wrong hands after all. Better safe than dead...\n\nIn return for your help, I will share with you my methods of fusing magic to cloth.\n\nFlytrap Ichor is very rare in this region, but I do have a bit in reserve. Take this woven fur and dip it in the ichor here. You will see for yourself what all of the fuss is about.", objectives = "Use Trega's Flytrap Ichor to create a Swatch of Hexweave.", progress = "Has the cloth been enchanted?", completion = "There, you're on the path to becoming a true Hexweave tailor.\n\nDo not share the secrets I've shown you here with anyone." }
WordHunterWoW_QuestEN[36420] = { title = "Spires - Treasure 011 - Garrison Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[36421] = { title = "Spires - Treasure 024 - Sun-Touched Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[36422] = { title = "Spires - Treasure 029 - Sun-Touched Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[36423] = { title = "Pets Versus Pests", description = "I've been trying to get this place ready for your pets, but we've uncovered some rude pests while building the garrison.  I tried to take care of them myself, but they are too tough for my meager team.\n\nThere's an angry carrot in the garden, an enormous rat eating our food rations, and an ornery water creature harassing the fishermen.  If you can take care of them, I'll be free to finish up my work on your menagerie.", objectives = "Defeat the three pests in your garrison.", progress = "Any luck?", completion = "Thank you, <name>.  Let's see if your pets like their new space!" }
WordHunterWoW_QuestEN[36424] = { title = "Spires - Treasure 059 - Sun-Touched Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[36425] = { title = "Egg Punt", description = "<A sweaty, pulsing egg - no doubt flush with ravager larvae.\n\nA swift kick should take care of these.>", objectives = "Kick 10 Ravager Eggs in Camp Thornscar." }
WordHunterWoW_QuestEN[36426] = { title = "Dueling Orbs", description = "", objectives = "" }
WordHunterWoW_QuestEN[36427] = { title = "The Rise and Fall of Barov Industries: Alexi Barov", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", objectives = "Accept the Blood Oath of Blademaster Na'Shra.[PHYLARCH ACQUISITION TEXT GOES HERE]", completion = "\"The brothers united once more,\" he said.\n\n\"A world full of untold riches to plunder,\" he said.\n\n\"Wealth beyond imaging,\" he said!\n\nAnd then he proceeded to drop a log on top of me.\n\n\"There can only be one CEO of Barov Industries,\" he said.\n\nAt least we can agree on that..." }
WordHunterWoW_QuestEN[36428] = { title = "Curing With Force", description = "The infection is getting stronger so I made some adjustments and I'm pretty sure I have the right formula now.\n\nIt should now work but it needs to have less competition with the infected blood for it to have any effect.\n\nThis means you will need to weaken them before you apply the serum for it to function properly.\n\nThe infection is getting more advanced and will soon be untreatable so we have this one shot to save as many as we can.", objectives = "Cure 6 Infected Goblins.", progress = "Any progress to report with that cure?", completion = "Yea! Great work, <name>!\n\nI've already heard from the survivors and they're glad for this second chance at life.\n\nYou made a real difference today!" }
WordHunterWoW_QuestEN[36429] = { title = "The Rise and Fall of Barov Industries: Weldon Barov", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", objectives = "Accept the Blood Oath of Blademaster Na'Shra.[PHYLARCH ACQUISITION TEXT GOES HERE]", completion = "\"The brothers united once more,\" he said.\n\n\"A world full of untold riches to plunder,\" he said.\n\n\"Wealth beyond imaging,\" he said!\n\nAnd then he proceeded to drop a log on top of me.\n\n\"There can only be one CEO of Barov Industries,\" he said.\n\nAt least we can agree on that..." }
WordHunterWoW_QuestEN[36430] = { title = "Tracking: Mill Treasure 18", description = "", objectives = "" }
WordHunterWoW_QuestEN[36431] = { title = "Vignette: Soul-twister Torek", description = "", objectives = "" }
WordHunterWoW_QuestEN[36432] = { title = "Seeking the Scout", description = "We are still trying to locate all of our scouts out in the field. One of these, Altauur, enjoys handling the more dangerous missions.\n\nHe has not checked in and I feel we should check to make sure he has not taken on more than he can handle.", objectives = "Find Altauur at Dionor's Demise in Gorgrond.", completion = "D'kaan worried about me? He is more worried I will be chased back to the camp with one of those giant beasts in tow. Still I could use your help here..." }
WordHunterWoW_QuestEN[36433] = { title = "Spires - Treasure 008 - Smuggled Apexis Artifacts", description = "", objectives = "" }
WordHunterWoW_QuestEN[36434] = { title = "Penny From Heaven", description = "<Durotan looks at you curiously.>\n\nThose from your world are not much for subtlety, are they?\n\nGo on ahead and greet our new companion. We will join you as soon as we can make ready.", objectives = "Speak to Penny Clobberbottom at Beastwatch.", completion = "Ahh, there y'are!\n\nPenny Clobberbottom reportin' for duty, commander." }
WordHunterWoW_QuestEN[36435] = { title = "Unintelligible Intelligence", description = "The notes are unreadable, but based on previous experience, the text appears to be very similar to standard Orcish.\n\nIt is possible that the notes could contain strategic information. Perhaps it would be of great value to the Frostwolf Orcs.\n\nSomeone in Wor'gol might be able to help interpret the text.", objectives = "Look around Wor'gol for someone who can help translate the notes.", progress = "<Raleigh looks up from the scrolls.>\n\nCommander <name>, what brings you to Wor'gol?!", completion = "We have been studying these orcish texts feverishly since our arrival here. Allow me a moment to translate this for you.\n\nHmmm... The notes appear to contain a list of names." }
WordHunterWoW_QuestEN[36436] = { title = "Plant Pruning", description = "There may be more to this aberrant growth than it seems, but we will need to clear the way a bit before we can get to the bottom of this, yes?\n\nI suggest clearing out some of the angrier defenders to be on the safe side.", objectives = "Kill 12 defenders at Dionor's Demise.", progress = "How goes the pruning <class>?", completion = "I have slain quite a few as well but they continue to spring up here.\n\nWe will need another solution..." }
WordHunterWoW_QuestEN[36437] = { title = "Ambassador to the Ancient", description = "It appears that a genesaur was killed here not long ago and this growth has sprung up.  It is stirring up the local monsters and I fear for our outpost.\n\nThere is a strange ancient that wallows in grief here and is not hostile. Perhaps you could \"harvest\" its story?", objectives = "Talk to Birchus at Dionor's Demise in Gorgrond.", completion = "So the normal ebb and flow of battle has been disrupted by the saberon. I do not think it wise to leave things as such.\n\nWe should see about infiltrating the saberon and setting things right." }
WordHunterWoW_QuestEN[36438] = { title = "Beatface vs. Boulder", description = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this.\n\nOne of their entrances is covered with a large boulder. Too large for you or I, but perhaps an ogre with a large enough hammer could break it. I think you know who I am talking about...", objectives = "Break the boulder barrier using Beatface the gladiator.", completion = "You have strong friends <name>. We must make haste before the plants realize the way is open." }
WordHunterWoW_QuestEN[36439] = { title = "Shredder vs. Saberon", description = "The saberon took their treasure up the rise and barricaded themselves in after Birchus attacked. It will be difficult to get in but I hear you have resources to handle this.\n\nOne of their entrances is covered with tough vegetation. I believe you have a mechanical solution to this problem in the form of a shredder. I think you know what to do...", objectives = "Break the vine barrier using your shredder.", completion = "Your machine is brutish but effective, well done <name>. We must make haste before the plants realize the way is open." }
WordHunterWoW_QuestEN[36440] = { title = "Saberon Population Reduction", description = "We are closer to our goals but a host of sharp toothed saberon bar our way.\n\nIf we are to get anywhere up here, some of the more aggressive ones will need to be put down I think.", objectives = "Slay 10 saberon at Steamscar Rise.", completion = "Many are finding bolt-holes to weather your storm, friend. That should keep them out of our way." }
WordHunterWoW_QuestEN[36441] = { title = "Reclaiming Property", description = "You are attracted by a low green glow to the container.  Inside there is a glowing bundle of herbs that was most likely stolen from the overgrowth below.\n\nIt would be best to collect all of these so the saberon don't continue their dabbling in plant magic and irritating the nearby magnaron.", objectives = "Find 8 Herb Bundles in saberon stashes at Steamscar Rise.", progress = "The saberon should definitely NOT have any of the herbs you have found!", completion = "A good catch discovering those herbs <name>. We cannot allow them to continue using these. Who knows what it might set off." }
WordHunterWoW_QuestEN[36442] = { title = "Taking the Death Bloom", description = "Your work has born fruit. Inside the nearby cave a powerful saberon shaman is learning to channel the genesaur magic using the Death Bloom we seek. The solution is before us: kill the shaman, take the Death Bloom, return it to Birchus. That should improve the safety of our outpost.", objectives = "Take the Death Bloom from Smokemaster Snarl in Steamscar Rise.", progress = "Do you have something for me little beast?", completion = "You have... you have brought me the bloom. At last my purpose can be fulfilled!" }
WordHunterWoW_QuestEN[36443] = { title = "Laying Dionor to Rest", description = "You have given me a tremendous gift with this bloom. I can finally send Dionor back to the Overgrowth for good and end this nightmare. All that remains is the ritual... stay and behold something you will never see again in your lifetime...", objectives = "Watch Birchus's ritual.", completion = "At last it is done.  Dionor has left and his spawn shall follow him in due time.\n\nI grow weary of this conflict and the desire to return to the Overgrowth has left me.\n\nPerhaps I will travel beyond these lands and see what other surprises you little beasts have to share..." }
WordHunterWoW_QuestEN[36444] = { title = "Spires - Treasure 006 - Iron Horde Explosives", description = "", objectives = "" }
WordHunterWoW_QuestEN[36445] = { title = "Spires - Treasure 015 - Iron Horde Spear", description = "", objectives = "" }
WordHunterWoW_QuestEN[36446] = { title = "Spires - Treasure 016 - Outcast's Pouch", description = "", objectives = "" }
WordHunterWoW_QuestEN[36447] = { title = "Spires - Treasure 020 - Outcast's Basket", description = "", objectives = "" }
WordHunterWoW_QuestEN[36448] = { title = "Reduction in Force", description = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had.\n\nAnd now he thinks he's going to plumb this land for all that it's worth and cut me out?!\n\nNo, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me.\n\nMy peasant friend, you must do me this service. Find my brother, Alexi, and serve him a notice of termination!\n\nYou will likely find him out in the wilds, near small timber.", objectives = "Collect the Head of Alexi Barov.", progress = "Did you deliver the... notice of termination?", completion = "<Weldon holds Alexi's head up to his face and begins speaking.>\n\nYou no-good, backstabbing son-of-a-goat! Your greed is only surpassed by my own!\n\nAs for you my peasant friend, you have served me well. Here are your just rewards!" }
WordHunterWoW_QuestEN[36449] = { title = "Reduction in Force", description = "I was a fool to trust him after the fiasco over the Barov family fortune! What I should have done is killed him the first chance I had.\n\nAnd now he thinks he's going to plumb this land for all that it's worth and cut me out?!\n\nNo, dear brother, not this time! There can only be one CEO of Barov Industries and it will be me.\n\nMy peasant friend, you must do me this service. Find my brother, Weldon, and serve him a notice of termination!\n\nYou will likely find him out in the wilds, near small timber.", objectives = "Collect the Head of Weldon Barov.", progress = "Has my brother been served the notice of termination yet?", completion = "<Alexi holds Weldon's head up to his face and begins speaking.>\n\nYou no-good, backstabbing son-of-a-goat! Your greed is only surpassed by my own!\n\nAs for you my peasant friend, you have served me well. Here are your just rewards!" }
