WordHunterWoW_QuestEN[36452] = { title = "Spawn Tracking & Spell Visuals: Do They Work?", description = "Here's some text.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the What's It to see a Spell Visual play through the magic of Spawn Tracking tech." }
