WordHunterWoW_QuestEN[36456] = { title = "Spires - Treasure 045 - Shredder Parts", description = "", objectives = "" }
WordHunterWoW_QuestEN[36457] = { title = "Bypassing Security", description = "Oh, my goodness!\n\nThis is a list of captives, it appears they may be awaiting transfer... or possibly even execution.\n\nThere is one name on this list that I do recognize: my master!\n\nI have been awaiting his return, but now it appears that he may have fallen into enemy hands.\n\nThis is a disaster! Please, {name}, we must rescue him.\n\nAccording to the notes, he has been taken to Grom'gar, located far east of here.\n\nOne moment... I think I may have just the thing to help you break in undetected...", objectives = "Infiltrate Grom'gar using Raleigh's Prestige Card.", completion = "You know the trick to fooling a bunch of Orcs? Every once in a while you've got to be holding all the cards!" }
WordHunterWoW_QuestEN[36458] = { title = "Spires - Treasure 055 - Abandoned Mining Pick", description = "", objectives = "" }
WordHunterWoW_QuestEN[36459] = { title = "Spires - Treasure 056 - Dislodged Saw Blade", description = "", objectives = "" }
WordHunterWoW_QuestEN[36460] = { title = "Just Another Stick in the Wall", description = "So, get this.\n\nAs I was flyin' in, I took the opportunity to scope out what might be a defensible position.\n\nJust on the other side o' these boulders is an ideal clearing to hole up in. I even brought a set of blueprints to get us all settled in!\n\nThat's not too presumptuous, is it?\n\nAnyway, whenever you're ready just hit this plunger!", objectives = "Use Penny's Plunger to blow up the Rock Wall.", completion = "Perhaps this little creature will earn her keep after all." }
WordHunterWoW_QuestEN[36461] = { title = "Locating the Lapidarist", description = "Are you sure I can't take this off your hands? I'll give you a fair price!\n\nAlright, alright... if you insist on finding the owner, you might want to try visiting Wor'gol.\n\nRumor has it, there is a master craftsman, skilled in manipulating precious metals and stones.\n\nBut, if you change your mind, you know where to find me....You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Search for the owner of the pendant in Wor'gol." }
WordHunterWoW_QuestEN[36462] = { title = "Spires - Treasure 012 - Admiral Taylor's Coffer", description = "", objectives = "" }
WordHunterWoW_QuestEN[36463] = { title = "Spires - Treasure 012 - Taylor's Coffer Key", description = "", objectives = "" }
