WordHunterWoW_QuestEN[36468] = { title = "Tracking Quest: Treasure Map", description = "", objectives = "" }
WordHunterWoW_QuestEN[36469] = { title = "Pets Versus Pests", description = "I been tryin' ta get dis place ready for your pets, but we uncovered some rude pests while buildin' da garrison.  I tried takin' care o' dem myself, but they be too tough for my little friends.\n\nBeat da angry carrot in da garden, da rat eatin' our food, and da ornery water creature harassing da fishermen.  If you can do it, I be free to finish up da work on your menagerie.", objectives = "Defeat the three pests in your garrison.", progress = "How'd you fare, <name>?", completion = "Nice job, brudda.  I hope your pets be likin' dere new home." }
WordHunterWoW_QuestEN[36470] = { title = "Spires - Vignette Boss 006 - Rotcap", description = "", objectives = "" }
WordHunterWoW_QuestEN[36471] = { title = "A New Darkmoon Challenger!", description = "Look at me, now look at my horse, now look back at me, are I not the most impressive battler of pets that you have ever seen?\n\nLook now at my compatriot over there. Is he on a horse? Of course not! Is his hat made of fireworks? Not in a million years! Everything about me is more impressive, from my coat color to my last name, which I made myself.\n\nDare you step up to the might of Christoph Willikens Dennis Ragnaros VonFeasel the First?\n\nI can see you trembling!", objectives = "Defeat Christoph VonFeasel in a pet battle.", progress = "Ready, eh? Put up your cat's tiny dukes!", completion = "Next time I won't go so easy on you!" }
WordHunterWoW_QuestEN[36472] = { title = "Spires - Vignette Boss 028 - Wasp Ancient", description = "", objectives = "" }
WordHunterWoW_QuestEN[36473] = { title = "Affliction Ridge", description = "", objectives = "" }
WordHunterWoW_QuestEN[36474] = { title = "The Razorbloom", description = "The Laughing Skull shaman Kaz ran off while we were coming here.\n\nShe claimed to be looking for more of her people in the jungles to the south.\n\nDraka insisted on following her to safeguard us against betrayal.\n\nCommander, if Kaz is telling the truth, then she and Draka are going to need all the help they can get.\n\nWill you join them? They could not have gotten far.\n\nThis could prove to be the perfect test for your new shredder and lumber mill resources.", objectives = "Find Draka and Kaz at the Razorbloom.", completion = "My husband sent you, didn't he?\n\nNormally I would laugh at that, but seeing these horrors, Kaz and I could use all the help we can get." }
WordHunterWoW_QuestEN[36475] = { title = "Stealing the Declaration", description = "Commander, you and Raleigh did a great job finding me, but I'm exactly where I need to be.\n\nWe've been working tirelessly since we got here, trying to crack these Draenic texts.\n\nI really thought I was gonna get the scrolls, but they nabbed me at the last possible second!\n\nPlease, you've gotta help me out... up the hill to the east, you'll find the Master Siegesmith's tent.\n\nIf you can grab the documents out of his chest, possibly this key too, I'll finally have enough to translate their languages.", objectives = "Loot the contents of Master Siegesmith Uratok's Strongbox.", progress = "A book of poems? I'll let you hang onto that one for now....", completion = "<name>, this is it, THIS IS IT! Just give me a moment while I look through these.\n\nHmm... I think there are a few things here that you may find very useful. Here, take these plans with you.\n\nDon't worry about me, commander. I'm just gonna take another look around before I sneak out of here." }
WordHunterWoW_QuestEN[36476] = { title = "South Gronn Canyon", description = "", objectives = "" }
WordHunterWoW_QuestEN[36477] = { title = "Broken Promises", description = "A heavily-scratched ring, faintly stained with blood.\n\nSomeone at the Darkmoon Faire might be able to provide more information about this item.", objectives = "Find someone at the Darkmoon Faire that might be interested in the ring.\n\nProvided item:", completion = "Ah, I see that you've found my lovelies. Beautiful, aren't they? It's a shame that the process drives them so... insane.\n\nThe ring is yours to keep, of course. Can you hear them whisper? Marvelous." }
WordHunterWoW_QuestEN[36478] = { title = "Spires - Vignette 020 - Shadowbark", description = "", objectives = "" }
WordHunterWoW_QuestEN[36479] = { title = "Spires - Vignette 021 - Nightmaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[36480] = { title = "Valley of Destruction", description = "", objectives = "" }
WordHunterWoW_QuestEN[36481] = { title = "Firebird's Challenge", description = "You're ready to fly high and give the Firebird's challenge a shot? That's great!\n\nSimply collect 15 rings to win! Speak to me when you're ready for takeoff!", objectives = "Collect 15 rings while flying.", progress = "How was the flight?", completion = "Wow, great flying out there, ace! Here's your prize!" }
WordHunterWoW_QuestEN[36482] = { title = "A Green Ogron?", description = "Kaz always told me green ogron are bad.\n\nThe botani here have a green ogron and it is mean.\n\nIt was strong enough to take out my dad's entire hunting party.\n\nAre you strong enough to kill it?", objectives = "Kill the Infested Ogron.", completion = "Yay! Burn the bad guy! Burn him a lot!" }
WordHunterWoW_QuestEN[36483] = { title = "Battle Pet Roundup", description = "Looks like we've got some visitors in the battle pen today, and they're looking for a fight.  Why don't you show 'em how a master of pet battles handles himself?", objectives = "Defeat the pets in the battle area.", progress = "Those pets looked tough.  How'd you do?", completion = "I knew you could do it, kid." }
WordHunterWoW_QuestEN[36488] = { title = "Thieving Dwarves", description = "Cutter is on the trail of the artifact the dwarves stole. He has the nose of a wolf when it comes to hunting in the jungle.\n\nFollow the canyons south until you find him.\n\nIt would seem the wolf queen and I are going to do more damage here before we leave.\n\nWe will follow as quickly as we can.", objectives = "Find Cutter at Bastion Rise.", completion = "Wow. Those... \"dwarves\"... sure do know how to make both botani AND goren mad." }
WordHunterWoW_QuestEN[36489] = { title = "Assault on the Pit", description = "The Iron Horde are stockpiling their weapons and ammunition outside of the Foundry. Their campaign throughout Draenor has left their caches vulnerable. Get in there and cause as much chaos as you can, and while you're at it use some of that ammunition against them if they're just going to leave it lying around!", objectives = "Destroy Iron Horde weapons cache and take out as many of them as you can." }
WordHunterWoW_QuestEN[36490] = { title = "Assault on Pillars of Fate", description = "", objectives = "" }
WordHunterWoW_QuestEN[36491] = { title = "Assault on Pillars of Fate", description = "", objectives = "" }
WordHunterWoW_QuestEN[36492] = { title = "Garrison Pet Battle", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[36493] = { title = "Tracking Quest: Can Open Othaar's Door", description = "", objectives = "" }
WordHunterWoW_QuestEN[36494] = { title = "News from Talador", description = "Rokhan sends word that you are needed at Frostwall. The Iron Horde have landed on the shores of Talador.", objectives = "Speak to Rokhan at your garrison in Frostfire Ridge.", completion = "Welcome back, mon." }
WordHunterWoW_QuestEN[36495] = { title = "News from Talador", description = "Bodrick Grey sends word from your garrison that they have spotted a fleet of Iron Horde at the shores of Talador.\n\nWe must not allow them to destroy Shattrath.", objectives = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", completion = "Welcome back, <name>." }
WordHunterWoW_QuestEN[36496] = { title = "The Lumber Mill", description = "The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart.\n\nSeems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly.\n\nI think we could use that for yer outpost. Hey, wood is wood, right?\n\nI'll meet ya there.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Glirin outside Tangleheart.The Rangari have been here for a tick, and they hear tell from the Laughing Skull o' a place called Tangleheart.\n\nSeems some really bad ancients come from there, and botani use a kind o' sap to grow them quickly.\n\nI think we could use that for yer outpost. Hey, wood is wood, right?\n\nI'll meet ya there.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[36498] = { title = "Iron Horde Invasion", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in Blasted Lands.\n\nUse the portal at the Wizard's Sanctum in Stormwind to head directly to the front line.\n\nThis new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped.\n\nFor the glory and honor of the Alliance!", objectives = "Speak with Vindicator Maraad at the Shattered Beachhead in Blasted Lands.", completion = "The situation here is dire, <name>. We have much to discuss." }
WordHunterWoW_QuestEN[36499] = { title = "Iron Horde Invasion", description = "All able bodied members of the Horde are hereby ordered to report to Thrall in Blasted Lands.\n\nUse the portal at the Cleft of Shadow in Orgrimmar to head directly to the front line.\n\nThis new threat is known only as the Iron Horde. They have taken over the Dark Portal and must be stopped\n\nDestiny calls!", objectives = "Speak with Thrall at the Shattered Landing in Blasted Lands.", completion = "The situation here is dire, <name>. We have much to discuss." }
WordHunterWoW_QuestEN[36500] = { title = "The Razorbloom", description = "", objectives = "" }
WordHunterWoW_QuestEN[36501] = { title = "Iron Horde Invasion", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in the Blasted Lands.\n\nYou can reach the docks outside Northwatch Hold by taking a boat from Booty Bay to Ratchet and traveling south along the coast.\n\nFor the glory and honor of the Alliance!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "xxxxBy order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vindicator Maraad at the Shattered Beachhead in the Blasted Lands.\n\nYou can reach the docks outside Northwatch Hold by taking a boat from Booty Bay to Ratchet and traveling south along the coast.\n\nFor the glory and honor of the Alliance!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[36502] = { title = "Trophy of Glory: Biolante", description = "Defeating Biolante has yielded you a trophy worthy of showing off at your outpost. \n\nReturn this to Maraad to increase your glory!", objectives = "Take the trophy to Maraad at Highpass in Gorgrond.\n\nProvided item:", completion = "I've seen plant life mimic the vicious hydra before, but to improve on the design? Only in Gorgrond... excellent work <name>." }
WordHunterWoW_QuestEN[36503] = { title = "Trophy of Glory: Biolante", description = "Defeating Biolante has yielded you a trophy worthy of acclaim.\n\nTake this to Durotan at Beastwatch.", objectives = "Take the trophy to Durotan at Beastwatch in Gorgrond.\n\nProvided item:", completion = "In this land even the plants turn into vicious monsters. Biolante was one of the worst, still as a plant until you were too close.\n\nA fitting end to such a beast..." }
WordHunterWoW_QuestEN[36504] = { title = "Evermorn Springs", description = "", objectives = "" }
WordHunterWoW_QuestEN[36505] = { title = "A Warrior's Shroud", description = "Although this cloak has seen better days, the workmanship is still quite impressive. Any normal cloak would have most certainly fallen apart by now.\n\nPerhaps one of the Frostwolf orcs within Wor'gol would be willing to help you repair it.", objectives = "Locate a Frostwolf leatherworker in Wor'gol that can help you.", progress = "Greetings, <race>. do you require any repairs?", completion = "This is a fine cloak! Sadly, we no longer have the resources to make them like this." }
WordHunterWoW_QuestEN[36506] = { title = "Treasure: Orc Super Caster Loot", description = "", objectives = "" }
WordHunterWoW_QuestEN[36507] = { title = "Treasure: Orc Skeleton", description = "", objectives = "" }
WordHunterWoW_QuestEN[36508] = { title = "Is This One of Yours?", description = "I found this one skulking nearby. She claims to be an ally of yours.\n\nIs this true? Or does she cook slowly over my fire?", objectives = "Talk to Rexxar and vouch for Rangari Erdanii.", completion = "Thank you for vouching for me, commander." }
WordHunterWoW_QuestEN[36509] = { title = "Treasure: Hydra Treasure Pile", description = "", objectives = "" }
WordHunterWoW_QuestEN[36510] = { title = "Fire Ammonite", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Frostfire Ridge for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Ron Ashton wants you to collect 10 Fire Ammonite Eggs from Frostfire Ridge.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[36511] = { title = "Jawless Skulker", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Gorgrond for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Ron Ashton wants you to collect 10 Jawless Skulker Eggs from Gorgrond.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[36512] = { title = "Together We Are Strong", description = "", objectives = "Auchindoun would have fallen to the demons if it weren't for you. Even the blood elves would not have been enough. I don't know how I could possibly ever repay you.\n\n<Tuulani's face lights up.>\n\nThat's it! We're kindred spirits, <name>. I can feel it! How about I stick around with you?\n\nI'll still have to attend to my duties at Auchindoun, but I can handle it. What do you say, <name>? It'll be great!" }
WordHunterWoW_QuestEN[36513] = { title = "Fat Sleeper", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Nagrand for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Ron Ashton wants you to collect 10 Fat Sleeper Eggs from Nagrand.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[36514] = { title = "Blind Lake Sturgeon", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Shadowmoon Valley for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Ron Ashton wants you to collect 10 Blind Lake Sturgeon Eggs from Shadowmoon Valley.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[36515] = { title = "Blackwater Whiptail", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Talador for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Ron Ashton wants you to collect 10 Blackwater Whiptail Eggs from Talador.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[36516] = { title = "Cut 'Em Out!", description = "After all that you've done for us, I would love to help you. Regrettably, I don't have the materials I would need to repair this perfectly.\n\nUse my knife to gather a few hides from the clefthoof that roam near the spire and find some sootweed pitch to properly cure them.\n\nUnfortunately, those miserable ogres have taken up residence in the only place that I know of sootweed to grow. You may be in for a fight {name}.\n\nReturn to me if you can obtain these and I will gladly help you repair your cloak.", objectives = "Obtain the materials needed to repair the cloak.", progress = "Were you able to obtain the materials, <name>?", completion = "You are covered in soot from head to toe, <name>!\n\nAs promised, I will help you repair your cloak. I have a few other items here which you might find useful as well.\n\nCome back and see me any time!" }
WordHunterWoW_QuestEN[36517] = { title = "Abyssal Gulper Eel", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Spires of Arak for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", objectives = "Ron Ashton wants you to collect 10 Abyssal Gulper Eel Eggs from Spires of Arak.", progress = "Anything biting?", completion = "These will do nicely, <name>!  Thank you!" }
WordHunterWoW_QuestEN[36518] = { title = "The True Path", description = "", objectives = "Wow... I've never seen anyone fight like that. That was... impressive.\n\nI'm in no shape to join Lady Liadrin and the others at Auchindoun now. You have an entire fortress on this world, though. Could I go there and rest awhile? Maybe repair my armor?\n\nI'll stick around and join your forces as a token of my gratitude. Liadrin won't mind... we're all on the same team, right?" }
WordHunterWoW_QuestEN[36519] = { title = "The True Path", description = "", objectives = "I have never seen anyone fight like that, \n.\n\nI am regrettably in no condition now to join the Auchenai in defending Auchindoun. I have heard stories of your fortress in Shadowmoon Valley. Could I go there and repair my armor?\n\nPerhaps... I could stay there a while longer than that? I feel there is much you could teach me." }
WordHunterWoW_QuestEN[36520] = { title = "Tailthrasher Basin", description = "", objectives = "" }
WordHunterWoW_QuestEN[36521] = { title = "Treasure: Rylak Egg", description = "", objectives = "" }
WordHunterWoW_QuestEN[36522] = { title = "Solidarity in Death", description = "", objectives = "I may have fallen, but I will not be forgotten.\n\nI implore you to allow me to stay here and serve in your army. Bralok took my life, but my spirit stands strong before you.\n\nI need to stop the Iron Horde, <name>, and I know you are the only one that can help me do that." }
WordHunterWoW_QuestEN[36523] = { title = "A Green Ogron?", description = "Them botani got themselves a green ogron. A green ogron!\n\nI mean I may not know much about plant people but that canno' be a good thing.\n\nThink ya can take it in a fight?", objectives = "Kill the Infested Ogron.", completion = "Is it still twitchin'? I think I saw it still twitchin'." }
