WordHunterWoW_QuestEN[36567] = { title = "Bigger is Better", description = "Ya know boss, I think I know how we can take this place to the next level. Bigger walls. More buildings. Some space to stretch your arms after a long day of adventuring.\n\nDon't get me wrong, it's going to take a lot of resources, but what else are these things for?\n\nWe can plot it out on the drafting table whenever you're ready. It's going to be GLORIOUS.", objectives = "Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2.", progress = "What ya waitin' for boss? Let's take this thing to the next level!", completion = "Now THAT'S what I'm talkin' about! Look at this place!\n\nWe've even got a pool out back. Little cold, sure, but ya can't always have a tropical paradise." }
WordHunterWoW_QuestEN[36568] = { title = "Vignette: Malgosh Shadowkeeper", description = "", objectives = "" }
WordHunterWoW_QuestEN[36569] = { title = "Unruly Visitors", description = "Looks like we've got some visitors in the battle pen today, and they're looking for a fight.  Why don't you show 'em how a master of pet battles handles <himself/herself>?", objectives = "Defeat the pets in your Garrison menagerie's battle area.Looks like we've got some visitors in the battle pen today, and they're looking for a fight. Why don't you show 'em how a master of pet battles handles <himself/herself>?" }
