WordHunterWoW_QuestEN[36571] = { title = "Iyun Weald", description = "", objectives = "" }
WordHunterWoW_QuestEN[36572] = { title = "Tangleheart Return", description = "Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here.\n\nThe Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark.\n\nI'm headin' there now.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Penny Clobberbottom outside Tangleheart.Hey there, peach. We've got the lumber mill good and ready, but we gotta find a way of choppin' wood fast out here.\n\nThe Laughing Skull talked about Tangleheart, where the botani grow things quick as a quark.\n\nI'm headin' there now.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[36573] = { title = "Strike While the Iron is Hot", description = "With the Heart of the Mangaron, we wield a powerful weapon against the Iron Horde.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Grinslicer when you are ready.", objectives = "Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde.", progress = "The mysteries of this land sometimes bear fruit.", completion = "<name>, we have dealt a great blow to the forces of the Iron Horde." }
WordHunterWoW_QuestEN[36574] = { title = "Strike While the Iron is Hot", description = "With the Will of the Genesaur, we wield a powerful weapon.\n\nOur scouts have discovered an Iron Horde base, and I believe it is time to seize an opportunity.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Grinslicer when you are ready.", objectives = "Speak to Grinslicer to fly to the Iron Approach and attack the Iron Horde.", progress = "The mysteries of this land sometimes bear fruit.", completion = "<name>, we have dealt a great blow to the forces of the Iron Horde." }
WordHunterWoW_QuestEN[36575] = { title = "Strike While the Iron is Hot", description = "With the Will of the Genesaur, we wield a powerful weapon.\n\nOur scouts have discovered an Iron Horde base, and I believe this is the time to seize an opportunity.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Rangari Rajess when you are ready.", objectives = "Speak to Rangari Rajess to fly to the Iron Approach and attack the Iron Horde.", progress = "We must eradicate the Iron Horde.", completion = "We have dealt a great blow to the Iron Horde, commander. We will defeat them yet." }
WordHunterWoW_QuestEN[36576] = { title = "Strike While the Iron is Hot", description = "With the Heart of the Magnaron, we wield a powerful weapon against the Iron Horde.\n\nThey amass far to the north at the Iron Approach. This will not be easy, but we must seize the opportunity to deal a blow to the Iron Horde while we possess the artifact.\n\nWe are prepared to depart at your command. Speak with Rangari Rajess when you are ready.", objectives = "Speak to Rangari Rajess to fly to the Iron Approach and attack the Iron Horde.", progress = "We must eradicate the Iron Horde.", completion = "We have dealt a great blow to the Iron Horde, commander. We will defeat them yet." }
