WordHunterWoW_QuestEN[36588] = { title = "Tracking - See Closed Chest", description = "", objectives = "" }
WordHunterWoW_QuestEN[36589] = { title = "Heavy Arms", description = "The burned out shell of some sort of weapon of mass destruction. It might be worth asking around your garrison to see if anyone can help get it working again.", objectives = "Look around the garrison for help with the repairs.", progress = "Yo, boss. Whatchya got for me?", completion = "I think we could get into some serious trouble with this beauty!" }
WordHunterWoW_QuestEN[36590] = { title = "The Howling Crag", description = "", objectives = "" }
WordHunterWoW_QuestEN[36592] = { title = "Bigger is Better", description = "Commander, I've been working on schematics that you might be interested in.\n\nWhat do you think about pushing out the walls and making room to get some additional structures in here? Our forces have been growing, and things are getting a little cramped, and I'd really like us to put some of those additional blueprints to use.\n\nIf you could, take a look at the plans on the table here. As soon as I have your go ahead, I'll get everyone to work immediately.", objectives = "Use the Architect Table to select your Town Hall and upgrade your garrison to Tier 2.", progress = "What do you think? Time for an upgrade?", completion = "MUCH better!  A lot less bumping into walls to be sure.\n\nThere should be room to get in another building or two now. We can get the additional construction going whenever you're ready - just point me at anything you're interested in on the table here." }
WordHunterWoW_QuestEN[36593] = { title = "Breakers Invasion! UNUSED", description = "Quakes have been shaking the garrison for the last hour, and a few of our scouts aren't reporting in.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Repel the Breaker invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)" }
WordHunterWoW_QuestEN[36594] = { title = "\"Spare\" Parts", description = "I've never seen anything like this before! No problem though, boss man. If it can be used to blow things up, I can get it working again.\n\nWe are definitely going to need some parts--some sort of ammunition wouldn't hurt either.\n\nSounds like those Iron Horde guys over yonder are no stranger to things that go boom.\n\nTake these tools with you and let's see if we can't commandeer us some spare parts!", objectives = "Recover 20 Black Iron Shells and 50 Siege Cannon Parts.", progress = "Got the stuff yet boss?", completion = "What did you think of my rapid disassembly tech? Pretty effective, yeah?" }
WordHunterWoW_QuestEN[36595] = { title = "He Drew Aggro...culture", description = "What you saw was the wake of the genesaur, Iyu. It was chasing this mechanical monstrosity and the person who drove it.\n\nI believe the pilot of this vessel is still alive and trapped within the ruins of the camp.\n\nIf you wish them to be recovered, I recommend doing so now.", objectives = "Find the pilot of the Dark Iron tank.", completion = "Ah perfect. I'll get this up an' runnin' in no time." }
WordHunterWoW_QuestEN[36596] = { title = "Treasure: Iron Horde Weapon Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[36597] = { title = "Vignette: Berthora", description = "", objectives = "" }
WordHunterWoW_QuestEN[36600] = { title = "Vignette: Riptar", description = "", objectives = "" }
WordHunterWoW_QuestEN[36601] = { title = "News from Nagrand", description = "One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand.\n\nWhatever it was, it can't have gone well for them. That's Warsong territory.", objectives = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", completion = "Commander. Good to have you back.\n\nWe've got some movement in Nagrand. Let me fill you in on the details." }
WordHunterWoW_QuestEN[36602] = { title = "News from Nagrand", description = "One of your soldiers stopped by asking for you while you were out. Something about a caravan heading out to Nagrand.\n\nWhatever it was, it can't have gone well for them. That's Warsong territory.", objectives = "Speak to Rokhan at your garrison in Frostfire Ridge.", completion = "Boss-mon. Good to have ya back.\n \nWe been seein' some movement in Nagrand. Let me give ya the details." }
WordHunterWoW_QuestEN[36603] = { title = "Brimstone Springs", description = "", objectives = "" }
WordHunterWoW_QuestEN[36604] = { title = "Treasure: Dark Iron Emergency Pack", description = "", objectives = "" }
WordHunterWoW_QuestEN[36605] = { title = "Treasure: Dark Iron Remains", description = "", objectives = "" }
WordHunterWoW_QuestEN[36606] = { title = "News from Nagrand", description = "Welcome back, sir.\n\nOne of Bodrick's men delivered a message about a caravan being dispatched for Nagrand. He's awaiting your approval on a new outpost.\n\nI've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help sir.", objectives = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", completion = "Commander. Good to have you back.\n\nWe've got some movement in Nagrand. Let me fill you in on the details." }
WordHunterWoW_QuestEN[36607] = { title = "News from Nagrand", description = "Welcome back, sir.\n\nOne of our shadow hunters delivered a message about a caravan being dispatched for Nagrand. Rokhan's awaiting your approval on a new outpost.\n\nI've been hearing whispers around camp about Nagrand. They say it's Warsong territory. They might need your help sir.", objectives = "Speak to Rokhan at your garrison in Frostfire Ridge.", completion = "Boss-mon. Good to have ya back.\n \nWe been seein' some movement in Nagrand. Let me give ya the details." }
WordHunterWoW_QuestEN[36608] = { title = "Finding Nat Pagle", description = "Now that you have proof, we might just have a shot at convincing Nat Pagle to join us out here.\n\nLast I heard, he was in fishing with the local Angler's faction out in Pandaria.  Somewhere off the coast of  Krasarang Wilds.  Head out there, show him your catch and see if you can get him to come back with you!", objectives = "Travel to the Angler's Wharf in Krasarang Wilds and talk to Nat Pagle.", progress = "You came all this way for me? Well, I am pretty important.", completion = "You came from Draenor? How does that even work?!" }
WordHunterWoW_QuestEN[36609] = { title = "The Great Angler Returns", description = "What's this species, a molten catfish you say? I have never even heard of a fish like this, much less seen one in person!\n\nI have to find more fish like this, it's what I live for! And if the fishing is as good as you say it is, there is just no way I can pass this opportunity up.  Take this page from my journal as proof that you found me and I will meet you back at your Garrison.", objectives = "Return to Rak'jin with Nat's journal page as proof that you found him.", progress = "You found Nat? The real Nat Pagle?!", completion = "We should really catch some big one's when Nat's gets here!" }
WordHunterWoW_QuestEN[36610] = { title = "Treasure: Gorge Spear", description = "", objectives = "" }
WordHunterWoW_QuestEN[36611] = { title = "A True Draenor Angler", description = "If you want me to help you permanently, you have to show me a few of these big Draenor catches first.  Head out into the wild and bring me back the biggest fish you can find from all the surrounding areas.\n\nI made this custom lure for you to use, please take care of it, it's never let me down!", objectives = "Catch a Lunker in each of the  Draenor zones and bring them back to Nat Pagle.", progress = "What did you catch?", completion = "These fish are exquisite, <name>. Great job!" }
WordHunterWoW_QuestEN[36612] = { title = "Luring Nat", description = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here.\n\nIf we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor.  Head out to the lava lakes here in Frostfire and see what you can do.  All that time you spend honing your skill here in Draenor should pay off now.", objectives = "Catch a Molten Catfish in Frostfire Ridge and bring it back to Rak'jin.", progress = "Any luck near those lava pools?", completion = "This will do nicely... A fish like this would be hard for anyone to deny, especially Nat!" }
WordHunterWoW_QuestEN[36614] = { title = "My Very Own Fortress", description = "Boss! Guess what?! I finally got that new larger draft paper in that I ordered when we first came here. And ya know what larger draft paper means?\n\nIt means I can draw a bigger fortress!\n\nAnd if I can draw it, I can certainly make it! Making's the easy part, as long as you've got a few thousand stones and logs lying around.\n\nSo whada'ya say, boss? Shall we get building?", objectives = "Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.", completion = "I think I could just fall over and die happy right now. It's a dream come true!\n\nI already ordered some even larger draft paper, boss. Don't you worry..." }
WordHunterWoW_QuestEN[36615] = { title = "My Very Own Castle", description = "Commander! Some good news. I finally got that new larger draft paper in that I ordered when we first came here. And do you know what larger draft paper means?\n\nIt means I can draw a bigger castle!\n\nAnd if I can draw it, we can certainly make it! Making it is the easy part, assuming you have a few thousand stones and logs lying around.\n\nSo what do you say, sir? Shall we get building?", objectives = "Gather 2000 Garrison Resources and then use the Architect Table to select your Town Hall and upgrade your garrison to Tier 3.", completion = "I... I think I like it. A little more blue paint, maybe some taller towers, but you can really call it home, you know?\n\nI already ordered some even larger draft paper, sir. Don't you worry..." }
WordHunterWoW_QuestEN[36616] = { title = "An Angler on Our Team", description = "You truly are a master fisherman!\n\nI would be delighted to join you here on Draenor and help you catch as many lunkers as you can. But first, let's grab a drink.", objectives = "Talk to Nat Pagle and ask him to join our cause.", completion = "You truly are a master fisherman!\n\nI would be delighted to join you here on Draenor and help you catch as many lunkers as you can. But first, let's grab a drink." }
WordHunterWoW_QuestEN[36617] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[36618] = { title = "Treasure: Iron Supply Chest", description = "", objectives = "" }
WordHunterWoW_QuestEN[36619] = { title = "Lumber Mill", description = "", objectives = "" }
WordHunterWoW_QuestEN[36620] = { title = "Strategic Choices", description = "Good to see you, commander.\n\nMy network has been keeping eyes on enemy movements. There are a couple threats I'd like to get you up to date on.\n\nDo you have a moment to look at our options?", objectives = "Choose between your strategic options." }
WordHunterWoW_QuestEN[36621] = { title = "Treasure: Gnome Canister", description = "", objectives = "" }
WordHunterWoW_QuestEN[36623] = { title = "Ogre Invasion!", description = "Commander, our scouts say that ogre bands march through the snow. If they want more battle after the beating we already delivered, then I'm eager to oblige them.", objectives = "Repel the ogre invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", progress = "We must hold the line!", completion = "It's good sport, fighting foes larger than yourself. You're happy with your grunts' conduct, Commander?" }
WordHunterWoW_QuestEN[36624] = { title = "Ashran Appearance", description = "Our base on Ashran is almost complete, commander.\n\nIt would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area.\n\nI can arrange a flight if you are interested.", objectives = "Speak with Private Tristan at Stormshield in Ashran.", completion = "Just a second, pal. Can't you see I'm busy here?\n\nCommander! I didn't think you were actually going to show... I mean... welcome, commander." }
WordHunterWoW_QuestEN[36625] = { title = "Treasure: Discarded Pack", description = "", objectives = "" }
WordHunterWoW_QuestEN[36626] = { title = "Host Howell", description = "Lieutenant Howell said you might be showing up.\n\nIt's such an honor to meet you in person. The lieutenant is at the inn, I'll escort you over there.", objectives = "Speak with Lieutenant Howell.", completion = "Commander <name>, I'm so glad you could make it. It's a true honor, sir." }
WordHunterWoW_QuestEN[36627] = { title = "Big Frostfire Gun", description = "One of my finest works, {name}! Momma would be so proud of me right now... if she was still in one piece.\n\nWe gotta test this bad boy out though before I'm comfortable letting you run around with it all willy-nilly.\n\nI heard there were some clefthooves out back causing a ruckus.", objectives = "Subdue 6 Clefthooves.", progress = "Did you manage to subdue those rowdy clefthooves?", completion = "Hmmm... sounds like it still needs a bit more punch. Let me get back to work on it, boss, I'll see what I can do!\n\nGood news is, we know a lot more about the Iron Horde tech now. I made a copy of my notes for ya." }
WordHunterWoW_QuestEN[36628] = { title = "Treasure: Hammer of Glory", description = "", objectives = "" }
WordHunterWoW_QuestEN[36629] = { title = "Inspiring Ashran", description = "I hope you will find our facilities to be up to your high standards.\n\nThis inn is run by Jaesia Rosecheer, in my opinion this is the best place to hearth in Draenor.\n\nWe have new recruits coming through the portal daily. In fact our latest recruit, Knewbie McGreen just came through the portal today.\n\nIf you are looking to trade for weapons or armor, Vindicator Nuurem will be happy to help.", objectives = "Speak with Jaesia Rosecheer, Vindicator Nuurem, and Knewbie McGreen.", progress = "How did your walk go?", completion = "Thank you again for taking the time to visit, commander. You have no idea how much it means to us." }
WordHunterWoW_QuestEN[36630] = { title = "A Surly Dwarf", description = "Before you go there is someone you might want to talk with.\n\nHe's opinionated, a bit gruff, and very overbearing, but he's the best damn warrior I've met in ages.\n\nHe belongs on the front lines with you, commander. And trust me, he knows it.", objectives = "Speak with Delvar Ironfist.", completion = "Look, I don't have time for any... Oh, it's you!" }
WordHunterWoW_QuestEN[36631] = { title = "Treasure: Sasha's Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[36632] = { title = "The Secrets of Gorgrond", description = "Commander, I was dispatched to intercept you.\n\nYrel and Maraad have landed at Wildwood Wash, the rangari base of operations for the area.\n\nYour presence is requested immediately. \n\nWe keep a small feywing presence just east of here. If you speak with the flight master they should be able to provide you safe passage to the Wash.", objectives = "Seek Yrel at the Wildwood Wash in Gorgrond. Speak with your Garrison Gryphon Master or the Flight Master at Bastion Rise to fly there.", completion = "Welcome to Gorgrond, Commander. We only just arrived ourselves." }
WordHunterWoW_QuestEN[36633] = { title = "Delvar Ironfist", description = "", objectives = "Well it's about time ye showed up. I'm done slumming around with these new recruits.\n\nMe blade is sharp, me armor is spit shined and I combed me beard this mornin'.\n\nI've been ready for battle since me grandpa Gygax first put an axe in me wee lil hand.\n\nSo whad'ya say, commander?" }
WordHunterWoW_QuestEN[36634] = { title = "Treasure: Sniper's Crossbow", description = "", objectives = "" }
WordHunterWoW_QuestEN[36635] = { title = "Your First Work Order", description = "Now that you have a profession building, we can start producing work orders for you. When you have the ingredients we need, please come to me to start the first batch.You will receive:", objectives = "Hand the assistant the reagents to start your first work order from a profession building." }
WordHunterWoW_QuestEN[36636] = { title = "Blueprint Read", description = "", objectives = "" }
WordHunterWoW_QuestEN[36640] = { title = "Followers Obtained", description = "", objectives = "" }
WordHunterWoW_QuestEN[36641] = { title = "Your First Alchemy Work Order", description = "Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Alchemy work order at the Alchemy Lab.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[36642] = { title = "Your First Leatherworking Work Order", description = "Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Leatherworking work order at the Tannery.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[36643] = { title = "Your First Tailoring Work Order", description = "Now that the tailoring emporium is complete, we can start producing hexweave cloth for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Tailoring work order at the Tailoring Emporium.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[36644] = { title = "Your First Jewelcrafting Work Order", description = "Now that the gem boutique is complete, we can start producing taladite crystals for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Jewelcrafting work order at the Gem Boutique.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[36645] = { title = "Your First Enchanting Work Order", description = "Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Enchanting work order at the Enchanter's Study.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[36646] = { title = "Your First Engineering Work Order", description = "Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Engineering work order at the Engineering Works.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[36647] = { title = "Your First Inscription Work Order", description = "Now that the scribe's quarters are complete, we can start producing war paints for you. When you have the ingredients, please speak with my assistant to start the first work order.", objectives = "Start and collect your first Inscription work order at the Scribe's Quarters.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer." }
WordHunterWoW_QuestEN[36648] = { title = "Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nBodrick Grey has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", objectives = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36649] = { title = "Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the traitor Exarch, Socrethar.\n\nMembers of the Sha'tari Defense have been requesting aid against the Shadow Council forces in the eastern portions of the city.", objectives = "Assault the Sargerei forces at Shattrath City in Talador.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36650] = { title = "Ogre Invasion!", description = "Scouts report that ogre packs march through Shadowmoon Valley. We've left our impression with them, eh Commander?", objectives = "Repel the ogre invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", progress = "We must hold the line!", completion = "Nothing teaches a bully better than a bloody nose! Good fight, Commander. It's an honor to stand with you." }
WordHunterWoW_QuestEN[36651] = { title = "Treasure: SHarvest Crystal", description = "", objectives = "" }
WordHunterWoW_QuestEN[36653] = { title = "Botani Invasion!", description = "There's a weight in the air. Reminds me of battles in Stranglethorn Valley. Jungle warfare is good for axe-play.", objectives = "Repel the botani invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", progress = "We must hold the line!", completion = "Is this what a peon feels like? Chopping down trees and pruning unruly hedges all day? And I thought their job was a bore. Hah!" }
WordHunterWoW_QuestEN[36654] = { title = "Treasure: Lost Dwarf", description = "", objectives = "" }
WordHunterWoW_QuestEN[36655] = { title = "Iron Horde Invasion!", description = "There's smoke on the horizon... The Iron Horde is coming.", objectives = "Speak with Sergeant Crowler.", progress = "Repel the Iron Horde invasion.\n\n(Speak with Sergeant Crowler again to begin)", completion = "I don't know what's worse, the brutality of this Iron Horde or the tempered menace of our old foes. It doesn't matter. Neither measures against our strength, Commander." }
WordHunterWoW_QuestEN[36656] = { title = "Vignette: Sunclaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[36657] = { title = "Vignette: Roody Roo", description = "", objectives = "" }
WordHunterWoW_QuestEN[36658] = { title = "Treasure: Botani Stockpile", description = "", objectives = "" }
WordHunterWoW_QuestEN[36659] = { title = "TBD", description = "", objectives = "" }
WordHunterWoW_QuestEN[36660] = { title = "Bloodmane Pridelands", description = "", objectives = "" }
WordHunterWoW_QuestEN[36661] = { title = "The Power of the Red", description = "", objectives = "" }
WordHunterWoW_QuestEN[36662] = { title = "Scrappin'", description = "Ever since we built da menagerie, a lot o' \"visitors\" been showin' up.  I know da look, and they be lookin' for a fight.  Brudda, you show 'em you da real master 'round here.", objectives = "Defeat the pets in the battle area.", progress = "Did you show 'em the mojo?", completion = "You showed 'em, boss!" }
WordHunterWoW_QuestEN[36663] = { title = "Garrison Max-level Choice Tracker: ANY CHOICE MADE", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[36664] = { title = "Garrison Max-level Choice Tracker: ANY CHOICE MADE", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[36665] = { title = "Garrison Max-level Choice Tracker: ALL CHOICES DEBUG", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[36666] = { title = "Garrison Max-level Choice Tracker: ALL CHOICES DEBUG", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[36667] = { title = "Assault on Shattrath Harbor", description = "Shattrath City is in the hands of Sargerei forces under the leadership of the once Exarch, Socrethar.\n\nThe Shadow Council forces in the eastern portion of the city are gaining in power through the aid of demons from the Nether, and need to be culled before they become a threat to all of our operations.", objectives = "Assault the Sargerei forces at Shattrath City in Talador.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36669] = { title = "Assault on Stonefury Cliffs", description = "Bloodmaul ogres from Frostfire Ridge have been ambushing trade routes throughout the continent, and are putting captured soldiers to work in their slag mines.\n\nShadow Hunter Rokhan has requested the rescue of friendly troops that have been taken prisoner in the main Bloodmaul compound at Stonefury Cliffs.", objectives = "Assault the Bloodmaul ogres at Stonefury Cliffs in Frostfire Ridge.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36670] = { title = "The Ring of Blood: Skull Chewer!", description = "Welcome to Nagrand's one and only Ring of Blood, where hopefuls become gladiators and gladiators become discarded piles of meat on the arena floor!\n\nTalk to me to start a fight, hop down into the ring, and fight for your life. It's positively brutal - and the crowd loves it!\n\nYou'll face off against an ogron that has a hankering for freshly severed heads. You'll be fine... and I'll be rich!", objectives = "Defeat Skull Chewer in the Ring of Blood.", completion = "Nicely done, pal. Now how's about we kick things up a notch?" }
WordHunterWoW_QuestEN[36671] = { title = "The Ring of Blood: Fracktus!", description = "Have you ever fought a living, breathing mountain that wants to murder your face? Well, today's your lucky day!\n\nFracktus is a... well... living, breathing mountain that wants to murder your face, actually. Got that one right the first time!\n\nJust hop in the ring so we can get started, will ya?", objectives = "Defeat Fracktus in the Ring of Blood.", completion = "Incredible! You've got real moxy, kid." }
WordHunterWoW_QuestEN[36672] = { title = "The Ring of Blood: Venoxis!", description = "Alright, alright, how about this. A living, breathing... wait for it.... tree... that wants to murder your face. Genius, right?\n\nLook, they don't pay me to come up with witty dialogue about these things, give me a break. They're ogres - they pay for blood. Hence the name.", objectives = "Defeat Venoxis in the Ring of Blood.", completion = "You're the best I've ever seen in all my years as a promoter. I really mean that." }
WordHunterWoW_QuestEN[36673] = { title = "The Ring of Blood: Dreshax!", description = "You're going to love this one, champ.\n\nThat's right, it's the largest bone worm this side of Draenor. Dreshax lovingly disposes of all of the suckers... I mean... fallen gladiators for us.\n\nThink you've got what it takes? Hop on in and wait. Dreshax's lair is just below the arena - he'll come to you.", objectives = "Defeat Dreshax in the Ring of Blood.", completion = "What a battle. What a fight! Incredible!" }
WordHunterWoW_QuestEN[36674] = { title = "Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", objectives = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36675] = { title = "Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our outposts in the west. Most seem to originate from Magnarok in Frostfire Ridge.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", objectives = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", progress = "How goes the assault, sir?", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36676] = { title = "Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nBodrick Grey has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the wilds of Gorgrond, giving us more room to maneuver around them.", objectives = "Assault the botani forces in the Everbloom Wilds of Gorgrond.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36677] = { title = "Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", objectives = "Assault the ogron forces at the Broken Precipice in Nagrand.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36678] = { title = "Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", objectives = "Assault the Warsong forces at Mok'gol Watchpost in Nagrand.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36679] = { title = "Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should still have time to get ahead of the problem.", objectives = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36680] = { title = "Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrathar's disciples pose a threat to draenei and our garrison alike. We need to quell them at our soonest convenience.", objectives = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36681] = { title = "Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nBodrick Grey has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", objectives = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36682] = { title = "Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nBodrick Grey is concerned at their proximity to the garrison, and has put out a request that we thin their forces as soon as possible.", objectives = "Assault the Shadowmoon orcs at Pillars of Fate in Shadowmoon Valley.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36683] = { title = "Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", objectives = "Assault the Adherents of Rukhmar at Skettis in Spires of Arak.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36684] = { title = "Battle in Ashran", description = "As we do battle all across Draenor, the cowardly Horde try to seize our territory within Ashran.\n\nOur men would be inspired to see you join the battlefield, striking terror into the hearts of the Horde.", objectives = "Join the battle in Ashran.", completion = "Word of your glory in battle has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36685] = { title = "Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", objectives = "Assault the Sargerei forces deep within Shattrath City in Talador.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36686] = { title = "Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", objectives = "Assault the Blackrock orcs at the Pit in Gorgrond.", completion = "Word of the assault has already made it back, as have some spoils from the fight.\n\nWell done sir, if you don't mind me saying." }
WordHunterWoW_QuestEN[36687] = { title = "Challenge at the Ring of Blood", description = "A challenge has been issued at the Ring of Blood.\n\nBring friends and do battle to prove your right as champion.", objectives = "Do battle at the Ring of Blood.", completion = "I hear you were a sight to see in the ring. I'm proud to serve by your side, commander." }
WordHunterWoW_QuestEN[36688] = { title = "Assault on Skettis", description = "We've been receiving regular reports of birdmen from the south ambushing and burning caravans along the main roads.\n\nGuards from our outposts are requesting that we launch a counter attack against the main presence of Adherents of Rukhmar at Skettis in Spires of Arak.", objectives = "Assault the arakkoa forces at Skettis in Spires of Arak.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36689] = { title = "Assault on Pillars of Fate", description = "Remnants of the Shadowmoon clan continue to operate out of the peaks on the eastern border of Spires of Arak.\n\nRokhan is concerned at their proximity to key choke points leading into Shadowmoon Valley, and has put out a request that we thin their forces as soon as possible.", objectives = "Assault the Shadowmoon forces at Pillars of Fate in Shadowmoon Valley.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36690] = { title = "Assault on Lost Veil Anzu", description = "Some of our best scouts have gone missing in the vicinity of the lost ruins of Veil Anzu.\n\nRokhan has requested any available resources be dispatched to identify the threat and see if any of our men yet remain alive within the ruins.", objectives = "Assault the hostile creatures at Lost Veil Anzu in Spires of Arak.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36691] = { title = "Assault on Socrethar's Rise", description = "Recent reports suggest a notable rise of activity by Sargerei forces at Socrethar's Rise in southern Shadowmoon Valley.\n\nSocrathar's disciples pose a threat all over Draenor. We must not allow them to gain a foothold so far from our reach.", objectives = "Assault the Sargerei forces at Socrethar's Rise in Shadowmoon Valley.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36692] = { title = "Assault on Darktide Roost", description = "There's been a resurgence of rylaks on the battlefield in our skirmishes against the Iron Horde. If we don't stop them at the source, we'll quickly lose control of the roads and be pushed back into our outposts.\n\nThe most likely source of these additional rylaks is in southeastern Shadowmoon Valley, at Darktide Roost. If we move quickly, we should be able to stop their operation cold.", objectives = "Assault the Iron Horde forces at Darktide Roost in Shadowmoon Valley.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36693] = { title = "Assault on Mok'gol Watchpost", description = "Warsong raiders out of Mok'gol Watchpost have been terrorizing anything and everything not behind a tall wall. We've warned travelers not to stray out alone, but many don't listen.\n\nIf we were to launch an assault on Mok'gol Watchpost, we would almost certainly put the Warsong back on the defensive, restricting most of their riders to Nagrand.", objectives = "Assault the Warsong force at Mok'gol Watchpost in Nagrand.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36694] = { title = "Assault on the Broken Precipice", description = "Massive ogron have been battering our frontlines, and no matter how many we down, there seem to be more to replace them.\n\nMost of these ogron appear to be coming from the Broken Precipice, deep in western Nagrand. If we're to stand a chance in the coming battles, we need to find a way to remove these ogron from the battlefield.", objectives = "Assault the ogron forces at the Broken Precipice in Nagrand.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36695] = { title = "Assault on the Everbloom Wilds", description = "Botani and the plant monstrosities they conjure have been slowly encroaching on our outposts in the north. For every plant we kill, new ones seem to rise in its place.\n\nRokhan has put together a plan for striking at the heart of their lands, in Everbloom Wilds. He thinks this will draw them back into the jungles of Gorgrond, giving us more room to maneuver around them.", objectives = "Assault the Botani forces in the Everbloom Wilds in Gorgrond.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36696] = { title = "Assault on the Iron Siegeworks", description = "Iron Horde war machines are being shipped onto battlefields by the dozens, and our forces are struggling to hold their ground. Most of these machines seem to be originating from the Iron Siegeworks in eastern Frostfire Ridge.\n\nA strategic attack to disrupt and dismantle the Iron Horde at the siegeworks could be just what we need to turn the tide of the war.", objectives = "Assault the Iron Horde forces at the Iron Siegeworks in Frostfire Ridge.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36697] = { title = "Assault on Magnarok", description = "Colossal magnaron, gronn, and other stone monstrosities have been threatening our garrison. Most seem to originate from Magnarok, just to the north.\n\nIf we strike at them at their home, we should be able to force them back. It's risky, but it may be our best move. While you're there, see if you can recover any of our supplies.", objectives = "Assault the stone monstrosities at Magnarok in Frostfire Ridge.", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36698] = { title = "Battle in Ashran", description = "As we do battle all across Draenor, the cowardly Alliance try to seize our territory within Ashran.\n\nOur men would be inspired to see you join the battlefield, striking terror into the hearts of the Alliance.", objectives = "Join the battle in Ashran.", completion = "News about da fightin' beat ya back, boss-mon. And some spoils too.\n\nDem Alliance must a been none too happy to see ya on the field." }
WordHunterWoW_QuestEN[36699] = { title = "Assault on the Heart of Shattrath", description = "Sargerei forces from deep in Shattrath have grown stronger and bolder by the day. We can no longer risk ignoring the threat that they pose.\n\nBring allies if you wish to face the Sargerei so deep within the city.", objectives = "Assault the Sargerei force in Shattrath City in Talador.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36700] = { title = "Challenge at the Ring of Blood", description = "A challenge has been issued at the Ring of Blood.\n\nBring friends and do battle to prove your right as champion.", objectives = "Do battle at the Ring of Blood.", completion = "I been hearin' ya were a sight ya see in the ring.\n\nWe made some bets on ya. Easy money." }
WordHunterWoW_QuestEN[36701] = { title = "Assault on the Pit", description = "The Blackrock forces based out of the Pit in Gorgrond make up the bulk of the Iron Horde army. If we crush them on their home soil, the rest of the Iron Horde will have little hope of standing against us.\n\nIf you choose the battle, bring friends. The Blackrock won't be defeated easily.", objectives = "Assault the Blackrock forces at the Pit in Gorgrond.", progress = "Da assault be goin' well I hope?", completion = "News about da assault beat ya back, boss-mon. And some spoils of the fightin'.\n\nYa be a force to be reckonin' with." }
WordHunterWoW_QuestEN[36702] = { title = "Meatball", description = "", objectives = "MEATBALL FEELING BETTER NOW!\n\nMEATBALL FIGHT FOR AKIHIKÓ NOW!\n\nMEATBALL FOLLOW AKIHIKÓ WHEREVER AKIHIKÓ GO!!!" }
WordHunterWoW_QuestEN[36705] = { title = "The Ring of Blood: Mogor!", description = "You've really done it this time, champ. Mogor has challenged you to uphold his title as lord of the ring!\n\nI wish I could give you tips to help you make it out of there in one piece, but I've never seen Mogor fight. Nobody's ever gotten this far!\n\nGood luck.", objectives = "Defeat Mogor in the Ring of Blood.", completion = "You did it. You really did it! You're the new lord of the ring!" }
WordHunterWoW_QuestEN[36706] = { title = "Ashran Appearance", description = "Our base on Ashran is almost complete, commander.\n\nIt would be a huge show of support if you could make a trip out there and put your stamp of approval on their staging area.\n\nI can arrange a flight if you are interested.", objectives = "Speak with Private Stomphoof at Warspear in Ashran.", completion = "Commander! I am humbled to be able to serve you. The Lieutenant requests your presence." }
WordHunterWoW_QuestEN[36707] = { title = "Warspear Welcome", description = "Lieutenant Kragil said you might be showing up.\n\nI've been ordered to take you to the inn.", objectives = "Speak with Lieutenant Kragil.", completion = "Throm-Ka, commander. I am pleased to finally meet you in person." }
WordHunterWoW_QuestEN[36708] = { title = "Inspiring Ashran", description = "I hope you will find our facilities to be up to your high standards.\n\nThis inn is run by Narnin Dawnglow, in my opinion this is the best place to hearth in Draenor.\n\nWe have new recruits coming through the portal daily. In fact one of out latest recruits, Zarjhin, just came through the portal today.\n\nIf you are looking for weapons or armor Beska Redtusk will be happy to help.", objectives = "Speak with Narnin Dawnglow, Beska Redtusk, and Zarjhin.", progress = "How did your walk go?", completion = "Thank you again for taking the time to visit, commander. You have no idea how much it means to us." }
WordHunterWoW_QuestEN[36709] = { title = "Burning Beauty", description = "Before you go, there is someone you should meet.\n\nShe might set some of your stuff on fire, but I believe she's the best mage this side of Draenor.\n\nShe belongs on the front lines with you, commander.", objectives = "Speak with Vivianne.", completion = "So, you are the commander? Sylvanas sent me to find you." }
