WordHunterWoW_QuestEN[36711] = { title = "Abu'gar", description = "You thinkin' you might be able to help me out, mon?", objectives = "You thinkin' you might be able to help me out, mon?", progress = "You thinkin' you might be able to help me out, mon?", completion = "Ya brought my gear! Well it be lookin' like my luck might be turnin' around after all!\n\nAbu'gar will be returnin' the favor, just ya wait and see!\n\nRight after I hook myself a lunker, of course..." }
