WordHunterWoW_QuestEN[36741] = { title = "Vintage Free Action Potion", description = "I hear our heroes in the front line are becoming victim to massive amounts of snares, roots and stuns! Luckily I have just the potion for them. The recipe is a little old, but it'll work. \n\nA key ingredient I need can be found here in Ashran, at the beach near that Ogre Tower.", objectives = "Bring Gimlett Ginfizz 10 Ashmaul Pearls.", progress = "Have you got the pearls, <name>?", completion = "And here's your potion, <name>! If you don't have any use for it, maybe gift it to a friend who does?" }
WordHunterWoW_QuestEN[36742] = { title = "Vintage Free Action Potion", description = "The Alliance have increased their usage of snares, roots and stuns on our melee forces. Luckily I have just the potion for them. The recipe is a little old, but it'll work. \n\nA key ingredient I need can be found here in Ashran, at the beach near that Ogre Tower.", objectives = "Bring Tyra Silverblood 10 Ashmaul Pearls.", progress = "I need those pearls for the potion, did you find them <name>?", completion = "It is made. If you don't have any use for it, give it to one of our melee." }
