WordHunterWoW_QuestEN[36790] = { title = "The Initiate's Revenge", description = "I... I'm finished. My spirit will be with the Raven Mother soon.\n\nI beg of you, stranger... avenge me! Slay these filthy beasts.", objectives = "Kill 18 Bloodmane Saberon.", completion = "The lives of all the flock are precious.\nI'm glad to know that his murderers have been brought to justice.\n\nThank you, <name>, you have done us a great honor." }
WordHunterWoW_QuestEN[36791] = { title = "Phantom Potion", description = "Every turn you take in Ashran you run into danger. But don't fret <name>, I've developed the perfect solution. It's my very own riff on the popular Invisibility Potion. \n\nI'm just missing one of the ingredients: cave mushrooms. \n\nLuckily, a variety grows right here in Ashran.", objectives = "Bring Gimlett Ginfizz 10 Ghost Truffles.", progress = "Are those the truffles?", completion = "Here she is! Careful with her, these potions have a reputation for mysteriously disappearing." }
