WordHunterWoW_QuestEN[36795] = { title = "Return to Karazhan: The Conjuring of Aluneth", description = "The book describes Aluneth: Aegwynn's own weapon.\n\nThe first few paragraphs describe Aluneth not as a weapon, but as an entity with its own will.\n\nThe next few pages, however, have been ripped out of the book...", objectives = "" }
WordHunterWoW_QuestEN[36796] = { title = "The Flock's Revenge", description = "The Bloodmane took several of our initiates when they ambushed our ritual in Ravenskar. They must be taught that the flock will never allow such a deed to go unpunished!\n\nWe will kill one of their tribe for each of the flock that has fallen!\n\nhead into their accursed home of Bloodmane Valley and slaughter as many of them as you can find.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 18 Bloodmane Saberon." }
