WordHunterWoW_QuestEN[36800] = { title = "Fire Ammonite Lunker", description = "", objectives = "Woooo daddy!  Now that's a lunker <name>!  I don't think I will ever get used to fishing in lava but nothing is really normal about this crazy place.", progress = "Woooo daddy!  Now that's a lunker <name>!  I don't think I will ever get used to fishing in lava but nothing is really normal about this crazy place.", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
WordHunterWoW_QuestEN[36801] = { title = "One Step Ahead", description = "Commander, Vindicator Maraad set off with Yrel and Thaelin Darkanvil to track the Iron Horde's movements in the nearby forest.\n\nThey await your arrival on a small rise to the southwest.", objectives = "Speak to Vindicator Maraad at Redemption Rise.", completion = "Ah, Commander <name>. Good to see you. Now our party is complete." }
WordHunterWoW_QuestEN[36802] = { title = "Abyssal Gulper Lunker", description = "", objectives = "I'm surprised you made it back in one piece!  Abyssal Gulpers are a delicacy to local Arakkoa in Spires of Arak.", progress = "I'm surprised you made it back in one piece!  Abyssal Gulpers are a delicacy to local Arakkoa in Spires of Arak.", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
WordHunterWoW_QuestEN[36803] = { title = "Blackwater Whiptail Lunker", description = "", objectives = "Those Draenei bother you over in Talador?  I never fancied them fisherman but word is they are very territorial with local fishing spots.  No matter, it looks like you got the prize this time!", progress = "Those Draenei bother you over in Talador?  I never fancied them fisherman but word is they are very territorial with local fishing spots.  No matter, it looks like you got the prize this time!", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
WordHunterWoW_QuestEN[36804] = { title = "Blind Lake Lunker", description = "", objectives = "That's a fine Blind Lake Lunker you got there <name>.  How long did you fight it?  Fish like these don't come around very often, but when they do, it's a fight!", progress = "That's a fine Blind Lake Lunker you got there <name>.  How long did you fight it?  Fish like these don't come around very often, but when they do, it's a fight!", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
WordHunterWoW_QuestEN[36805] = { title = "Fat Sleeper Lunker", description = "", objectives = "Looks like you caught a Fat Sleeper Lunker there.  Can't beat that river fishing in Nagrand, hoping to get out there soon myself.", progress = "Looks like you caught a Fat Sleeper Lunker there.  Can't beat that river fishing in Nagrand, hoping to get out there soon myself.", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
WordHunterWoW_QuestEN[36806] = { title = "Jawless Skulker Lunker", description = "", objectives = "A Jawless Skulker Lunker?  Must have been fishing in Gorgrond then!  I hear lots of things grow big out there...", progress = "A Jawless Skulker Lunker?  Must have been fishing in Gorgrond then!  I hear lots of things grow big out there...", completion = "I will take any lunkers you like find like this off your hands.  Come back and see me anytime you catch one and I will pay you top dollar!" }
