WordHunterWoW_QuestEN[36830] = { title = "Shadow Council Invasion!", description = "The demons are at our heels, Commander. Cow's milk is sour. A crone gave me an evil look this morning. The sky just doesn't seem... right.", objectives = "Repel the Shadow Council invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", progress = "We must hold the line!", completion = "They're defeated! I'm glad we came here, Commander. To Draenor. Fighting against demons reminds me why we fight for the Alliance." }
WordHunterWoW_QuestEN[36831] = { title = "Shadow Council Invasion!", description = "There's a cold fire in my blood, Commander. Like a warlock has my heart in his claw. Let the Shadow Council show themselves!", objectives = "Repel the Shadow Council invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", progress = "We must hold the line!", completion = "Waugh! We beat back the demons, Commander. My blood's still boiling from it. My eyes aren't turning red, are they?" }
WordHunterWoW_QuestEN[36832] = { title = "Get the Xuk Outta Here!", description = "Magnaron are not very receptive.", objectives = "If my spirits aren't with Xuk, Xuk isn't with them. You though, Xuk likes you." }
