WordHunterWoW_QuestEN[36843] = { title = "They Came From Above", description = "Please, traveler, I need your help.\n\nAruuna, my home, has been destroyed by the arakkoa. They swooped down from their spires and killed anyone who tried to escape. My family... did not make it out.\n\n My brother Barum stayed behind to find his daughter amidst the chaos. I beseech you, please, go to Aruuna and find Barum.\n\nHe is the only family I have left.", objectives = "Find Crystal-Shaper Barum near Aruuna in Talador.", completion = "Akhan is alive? Light bless us - some good news!" }
