WordHunterWoW_QuestEN[36848] = { title = "Ogre Waygates", description = "Six unique gates exist in Draenor, built by ogre magi in ages past.  We've discovered their potency has not diminished over the millennia.\n\nIf you can collect enough ogre waystones to activate one of these ancient waygates, we can build a portal from your garrison to that location.", objectives = "Collect 25 Ogre Waystones and use them to activate an Ogre Waygate in Draenor.", progress = "Did you activate a waygate?", completion = "Your efforts will be well rewarded, <name>.  The ancient waygates now serve you." }
