WordHunterWoW_QuestEN[36861] = { title = "Pinchwhistle Gearworks", description = "Commander, a goblin courier arrived this morning.\n\nHe mentioned that he is from a settlement in the Spires of Arak called the Pinchwhistle Gearworks. They have requested our assistance with some sort of ecological disaster.\n\nIf we can earn their trust it'll be worth the effort. Head down there and see what sort of assistance we can provide.\n\nI've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "Speak to Dungar Longdrink to secure a flight to the Pinchwhistle Gearworks.", completion = "Hey, you're from that Alliance base right?\n\nGlad you made the trip because we really could use your help!" }
WordHunterWoW_QuestEN[36862] = { title = "Pinchwhistle Gearworks", description = "Commander, a courier arrived this morning.\n\nHe said he's from a goblin settlement in Spires of Arak called the Pinchwhistle Gearworks. They've asked for our assistance with some sort of ecological disaster.\n\nWe're spread thin but if we can earn their trust then we might be able to gain a valuable ally.\n\nHead down there and see what sort of assistance we can provide. I've already spoken to the flight master and he's set up a special flight to get you out there.", objectives = "Speak to Bron Skyhorn the Wingman to secure a flight to the Pinchwhistle Gearworks.", completion = "Hey, you're from that Horde base right?\n\nGlad you made the trip because we really could use your help!" }
WordHunterWoW_QuestEN[36863] = { title = "Treasure: Iron Horde Munitions", description = "", objectives = "" }
WordHunterWoW_QuestEN[36864] = { title = "Three Feet Under", description = "", objectives = "I can honestly say I never thought I'd see the premier Horde commander walking through an Alliance garrison.\n\nThen again, I never thought I'd be caught while performing reconnaissance for the Dark Lady and stuffed in a hole in the ground left for dead.\n\nI'm clearly not going anywhere without your help. If you help me out of this hellhole, I'll serve under your banner. My solo run has been decidedly less than pleasant." }
WordHunterWoW_QuestEN[36865] = { title = "UBRS Event Dungeon Reward Quest", description = "", objectives = "" }
