WordHunterWoW_QuestEN[36867] = { title = "Lower Blackrock Spires Bonus Reward Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[36870] = { title = "Luring Nat", description = "Now that you are experienced enough with Draenor fishing, we might have a shot at convincing Nat Pagle to join us out here.\n\nIf we want Nat to actually come all the way out here, we are going to have to show him real proof of the incredible catches on Draenor.  Head out to local waters here in Shadowmoon Valley and see what you can do.  All that time you spend honing your skill here in Draenor should pay off now.", objectives = "Catch an Arcane Trout in Shadowmoon Valley and bring it back to Segumi.", progress = "Find anything worth keeping?", completion = "This will do nicely... A fish like this would be hard for anyone to deny, especially Nat!" }
WordHunterWoW_QuestEN[36872] = { title = "Austin's Folly", description = "", objectives = "" }
WordHunterWoW_QuestEN[36873] = { title = "DEPRECATED", description = "You there... you look the fighting type.  I want some sweet Revenge on the Scourge that killed my family.  Go get me 2 Stone Hunks O' Gargoyle so that I can throw them on the ground and stomp on them violently until they are mashed into itty bitty pebbly bits. \n\nYes. Go. Kill.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain 2 Stone Hunks O' Gargoyle from Carrion Gargoyles in the Eastern Carrion Fields. Return to Lord Bevis when the task is complete." }
WordHunterWoW_QuestEN[36874] = { title = "Warlord of Draenor", description = "Durotan...\n\n<Raza'kul spits.>\n\nHe cowers behind the white flag of peace, relying upon diplomacy to win over our sworn enemies.\n\nEnemies that have taken our homes and driven us from our ancestral lands.\n\nThere is only one way to deal with the draenei and their newfound alliance of cowards - blood for blood.\n\nJoin me in crushing our enemies. Together we will flood this hallowed ground with the bones of the Alliance and earn tributes fit for a warchief!\n\nReturn here when your bloodthirst is sated.", objectives = "Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror's Tribute.", progress = "I will not rest until this bloodied ground overflows with the bones of our enemies.", completion = "We may kill from sky break to sky fall and still our work will never be done. Yet at the end of days when we are measured for our accomplishments, only the bloody wake that we have left behind us will show our true strength. For this reason you must never stop the slaughter of those that would seek to harm us and our loved ones.\n\nPromise me, <name>.\n\nNever. Stop." }
WordHunterWoW_QuestEN[36876] = { title = "Warlord of Draenor", description = "The Exarchs do nothing but squabble amongst themselves over petty issues while our people are slaughtered in their homes by orc filth. If they will not raise a fist of defiance against our enemies, I will.\n\nI wish to join your Alliance and rid this world of Horde. ALL HORDE - \"Iron\" or otherwise.\n\nThis Altar of Bones that I stand upon represents glory in battle against our Horde enemy. Place an offering upon it and earn a conqueror's tribute worthy of your unrelenting bloodthirst.\n\nKill. Them. All.", objectives = "Kill Enemy Players in Player versus Player combat to earn 20 Broken Bones then place an offering at the Altar of Bones to Earn a Conqueror's Tribute.", progress = "I will not rest until this bloodied ground overflows with the bones of our enemies.", completion = "It is a start, to be certain, but there is much work to be done if Draenor is to be saved. Show no mercy, for they will show none to you.\n\nThe only warlords left upon Draenor will be you and I." }
