WordHunterWoW_QuestEN[36910] = { title = "The Incarnation of Aluneth", description = "<As the scrolls are added back into the book, the entirety of the spell becomes clear.>", objectives = "" }
WordHunterWoW_QuestEN[36911] = { title = "Taming a Talbuk", description = "If we're going to start sending out patrols in this wilderness, we'll need swift mounts for our troops. We can capture young beasts and bring them back here for training, eventually turning them into formidable beasts of war.\n\nThe talbuk is one of Draenor's fastest creatures, and that makes them just that much more difficult to capture. Take this talbuk lasso and head out to Shadowmoon Valley. Mount up and rope one of the young talbuk, and follow it until it's tamed. Don't let it get too far from you!", objectives = "Use the Talbuk Lasso on a Young Silverpelt and follow it until it is tamed.", completion = "That talbuk's already settled down for the night. It will need some rest and grooming before it's ready for the next stage in its training." }
WordHunterWoW_QuestEN[36912] = { title = "Capturing a Clefthoof", description = "Greetings, friend. I have been told that you are in need of a master of beasts. I come from the icy slopes of Northrend to finally shake this snow from my fur.\n\nThis savage land holds many creatures that we may tame so that our forces may ride on formidable war mounts. The mighty clefthoof reminds me of the mammoths from my home. Take this lasso and head out to the northern reaches of Frostfire Ridge. Mount up and use it to capture one of the young beasts.", objectives = "Use the Clefthoof Lasso on a Young Icehoof and follow it until it is tamed.", completion = "I have bedded the clefthoof down for the night, it will need rest before it is ready for training." }
WordHunterWoW_QuestEN[36913] = { title = "Besting a Boar", description = "Have you seen the boars they have here? Bigger than I am! Let's get one of them, why not?\n\nYou're going to have to head to Gorgrond for that task. Way out in the desolate regions, you'll find the ones we're lookin' for.", objectives = "Use the Boar Lasso on a Young Rocktusk and follow it until it is tamed.", completion = "That boar has taken to the hay. We'll let it rest up a bit before more training." }
WordHunterWoW_QuestEN[36914] = { title = "Wrangling a Wolf", description = "This next one will test you to your very limits, commander. The wolf is the most savage beast in all of Draenor.\n\nThe wolves of Nagrand, mounts of the fabled Warsong clan, can rend a man to bits in seconds. They're also faster and more agile than anything you've seen yet.\n\nHere's your lasso. Good luck, and don't get yourself killed!", objectives = "Use the Wolf Lasso on a Young Snarler and follow it until it is tamed.", completion = "It almost bit me, but I've got it bedded down and happy. A wolf, in my stables! Who'd have thought?" }
WordHunterWoW_QuestEN[36915] = { title = "Entangling an Elekk", description = "Well, you're pretty good at this whole taming thing. What's next?\n\nWe've done big, and we've done pointy. Let's do big AND pointy. I'm talking Elekks.\n\nWay out on the fertile plains of Nagrand, you'll find the finest specimens of beast this world has to offer. Grab one of the younger elekks, and we'll see if we can't get it trained like the Draenei used to.", objectives = "Use the Elekk Lasso on a Young Meadowstomper and follow it until it is tamed.", completion = "Quite a big one, but it fits! It's resting, we'll talk about training it tomorrow." }
WordHunterWoW_QuestEN[36916] = { title = "Capturing a Clefthoof", description = "Way up north in the frozen peaks of Frostfire Ridge, you'll find the wooly clefthoof.\n\nThey're sturdy, for sure, and fierce when you corner them. Don't expect them to be tamed without a fight.\n\nHere's a lasso, see if you can't manage to tame one before it tugs the rope out of your hands.", objectives = "Use the Clefthoof Lasso on a Young Icehoof and follow it until it is tamed.", completion = "Was it cold up there? This guy seems to appreciate the warmth, he's already snoozin'!" }
WordHunterWoW_QuestEN[36917] = { title = "Taming a Talbuk", description = "The next beast is one of the fastest in Draenor, but will test your skills at infiltrating into enemy territory.\n\nThe young talbuk can be found on the flowery hills of Shadowmoon Valley. Take this talbuk lasso and head out.\n\nWhen you encounter one, mount up and throw this rope, then follow it until it is tamed. Good hunting!", objectives = "Use the Talbuk Lasso on a Young Silverpelt and follow it until it is tamed.", completion = "The talbuk appears to be doing well. Allow it to rest before you continue the beast's training." }
WordHunterWoW_QuestEN[36918] = { title = "Requisition a Riverbeast", description = "I wasn't sure about this next beast, but it turns out that they've got a key strategic purpose. The riverbeast is quite at home in the water!\n\nYou'll find the best ones around in Talador, around about Duskfall Island. Look for the huge, floating lumps out in the water.\n\nTry not to get wet!", objectives = "Use the Riverbeast Lasso on a Young Riverwallow and follow it until it is tamed.", completion = "I've gone and dried it off already. We'll see about training this thing tomorrow." }
WordHunterWoW_QuestEN[36919] = { title = "Talador - Shore Vignette - Murloc Boss", description = "", objectives = "" }
WordHunterWoW_QuestEN[36920] = { title = "From Within", description = "A few of our demon hunters, Kor'vas Bloodthorn and Cyana Nightglaive, took a small force of the Illidari across to Faronaar. Their mission was to weaken the Legion from within.\n\nI haven't heard from them in a while.\n\nIt would be best if you could find and lead them to success. Agreed?", objectives = "Find Kor'vas Bloodthorn on Faronaar at Vanquish Point.", completion = "A friend it would seem.\n\nKayn did not think we could handle this? He might have been right this time." }
WordHunterWoW_QuestEN[36921] = { title = "Nemesis: Manslayer", description = "<Raza'kul hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all humans that stand defiantly against the Horde. Let their deaths serve as a warning to the rest of the Alliance: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of man.\n\nConquer our enemy and be known as manslayer. Fail and be nothing.", objectives = "Kill 500 Human Players in Player versus Player combat across Draenor.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as manslayer." }
WordHunterWoW_QuestEN[36922] = { title = "zzzzTITLE TEST", description = "", objectives = "" }
WordHunterWoW_QuestEN[36923] = { title = "Nemesis: Becoming Death", description = "You have chosen your quarry and surely soon they will feel your merciless wrath, but first you must venture out into the wilds of Draenor and rip out the still-beating heart of a dwarf in mortal combat. Return here with your prize.\n\nThrough the heart of your enemy the spirits will attune your senses, granting you second sight and keenness in hearing - all to stalk your prey and claim dominance.", objectives = "Kill a Dwarf Player in Player versus Player combat while in Draenor and retrieve their Dwarf Heart.", progress = "Have you recovered the heart of a worthy foe?", completion = "With this heart you will see and hear things as only the great spirits can. Your enemy will be unable to hide from your unrelenting assaults." }
