WordHunterWoW_QuestEN[36970] = { title = "Nemesis: Killer of Kezan", description = "<Kuros hands you the bloody heart.>\n\nThe ritual is complete. Your nemesis is marked for death.\n\nNow your work to rid this world of the enemy truly begins. Kill all goblins that stand defiantly against the Alliance. Let their deaths serve as a warning to the rest of the Horde: they will leave Draenor or they will die.\n\nReturn when you have quenched your rage with the blood of goblin.\n\nConquer our enemy and be known as the killer of Kezan. Fail and be nothing.", objectives = "Kill 500 Goblin Players in Player versus Player combat across Draenor.", completion = "The truth of your deeds is in your eyes. Your hunger for the enemy sated with cries for mercy and rivers of blood.\n\nTake now your place as killer of Kezan." }
WordHunterWoW_QuestEN[36971] = { title = "Talbuk Training: Great-Tusk", description = "The first step in training your mount for war will be getting it used to the sights and sounds of combat. If it's not trained properly, it might get spooked and run.\n\nTake this little talbuk out to the plains of Shadowmoon Valley and take on the biggest beast you can find, together. That should raise its confidence!", objectives = "Defeat Great-Tusk while riding your Talbuk-In-Training.", progress = "Did you manage to bring down Great-Tusk?", completion = "That should do it a world of good. We'll let 'er rest for tonight, and take on some bigger targets tomorrow." }
WordHunterWoW_QuestEN[36972] = { title = "Talbuk Training: Rakkiri", description = "Now that your talbuk has got a taste for combat, let's take it out into an environment it may not be familiar with.\n\nThe icy bluffs of Frostfire Ridge should be a good test. Find yourself a big, mean beast out there and take it down with your talbuk.", objectives = "Defeat Rakkiri while riding your Talbuk-In-Training.", completion = "Oi! That talbuk's performin' admirably. Let's let 'er rest." }
WordHunterWoW_QuestEN[36973] = { title = "Talbuk Training: Riplash", description = "Now plenty of mounts have been known to run away at the sight of a fierce predator. Way out in the desolate cliffs of Gorgrond, they've got some of the fiercest.\n\nLet's put your talbuk to the test. See if the two of you can't take down the mighty raptor known as Riplash.", objectives = "Defeat Riplash while riding your Talbuk-In-Training.", completion = "Those were some mighty big claws to tangle with. Your talbuk will need a nap after that one." }
WordHunterWoW_QuestEN[36974] = { title = "Talbuk Training: Gezz'ran", description = "There's plenty more beasts out in the wild that can make a snack of your favorite mount. One of the most cunning on Draenor is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your talbuk can't overcome this natural defense mechanism. You'll find some mean stalkers out in Talador.", objectives = "Defeat Gezz'ran while riding your Talbuk-In-Training.", completion = "Ye did it! I'm sure your talbuk's enjoyin' this sort of one-on-one attention. We'll let it rest up a bit." }
WordHunterWoW_QuestEN[36975] = { title = "Talbuk Training: Bulbapore", description = "Way down south in the Spires of Arak, the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place.\n\nTaking on a strange creature, like the fungal giant Bulbapore, gives us a great chance to expose your talbuk to predators it's unfamiliar with.", objectives = "Defeat Bulbapore while riding your Talbuk-In-Training.", completion = "I'll bet that was quite a fight! Great job, let's let it rest for tonight." }
WordHunterWoW_QuestEN[36976] = { title = "Talbuk Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your talbuk reacts to that.", objectives = "Defeat the Gorian Beast-Lasher while riding your Talbuk-In-Training.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training." }
WordHunterWoW_QuestEN[36977] = { title = "Talbuk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of 'em.\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", objectives = "Defeat the Darkwing Roc while riding your Talbuk-In-Training.", completion = "From now on, I'm sure your mount will always remember to keep one eye on the skies. Great job!" }
WordHunterWoW_QuestEN[36978] = { title = "Talbuk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your talbuk. See if you can't keep it focused and take down that moth.", objectives = "Defeat the Moth of Wrath while riding your Talbuk-In-Training.", completion = "Glad to see you two make it back. It'll need a bit of time to brush that dust off." }
WordHunterWoW_QuestEN[36979] = { title = "Talbuk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your talbuk and face off against Thundercall, and we'll see if it gets spooked.", objectives = "Defeat Thundercall while riding your Talbuk-In-Training.", completion = "Well, it's a bit wet, but seems to be in good spirits. I'll get 'er dried off and into bed." }
WordHunterWoW_QuestEN[36980] = { title = "Talbuk Training: Ironbore", description = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out!\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your talbuk on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore.", objectives = "Defeat Ironbore while riding your Talbuk-In-Training.", completion = "The sand worm's bit the dust? Well done, I'll get this beast bedded down for the night." }
WordHunterWoW_QuestEN[36981] = { title = "Talbuk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your talbuk and bring him down. In the name of the poor wee beasts!", objectives = "Defeat Karak the Great Hunter while riding your Talbuk-In-Training.", completion = "Hunted the hunter, eh? Your beast doesn't seem any worse for wear, either! I'll brush it down." }
WordHunterWoW_QuestEN[36982] = { title = "Talbuk Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.", objectives = "Defeat Maimclaw while riding your Talbuk-In-Training.", completion = "Your talbuk has grown from a wee silverpelt into a fine specimen of war beast, and it's all due to your diligence.\n\nI'm happy to hand over the reins of this fully-trained mount to you, commander. Ride it with pride!" }
WordHunterWoW_QuestEN[36983] = { title = "Clefthoof Training: Great-Tusk", description = "The first step in training your mount for war will be getting it used to the sights and sounds of combat. If it's not trained properly, it might get spooked and run.\n\nTake this little clefthoof out to the plains of Shadowmoon Valley and take on the biggest beast you can find, together. That should raise its confidence!", objectives = "Defeat Great-Tusk while riding your Clefthoof -In-Training.", completion = "That should do it a world of good. We'll let 'er rest for tonight, and take on some bigger targets tomorrow." }
WordHunterWoW_QuestEN[36984] = { title = "Clefthoof Training: Rakkiri", description = "Now that the clefthoof has a taste for combat, let's take it out into a harsher environment.\n\nTake your clefthoof out to the icy hills of Frostfire Ridge, and take on the great predator Rakkiri. We'll really put 'er toughness to the test.", objectives = "Defeat Rakkiri while riding your Clefthoof-In-Training.", completion = "Oi! That clefthoof's performin' admirably. Let's let 'er rest." }
WordHunterWoW_QuestEN[36985] = { title = "Clefthoof Training: Riplash", description = "Now plenty of mounts have been known to run away at the sight of a fierce predator. Way out in the desolate cliffs of Gorgrond, they've got some of the fiercest.\n\nLet's put your talbuk to the test. See if the two of you can't take down the mighty raptor known as Riplash.", objectives = "Defeat Riplash while riding your Clefthoof-In-Training.", completion = "Those were some mighty big claws to tangle with. Your clefthoof will need a nap after that one." }
WordHunterWoW_QuestEN[36986] = { title = "Clefthoof Training: Gezz'ran", description = "There's plenty more beasts out in the wild that can make a snack of your favorite mount. One of the most cunning on Draenor is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your clefthoof can't overcome this natural defense mechanism. You'll find some mean stalkers out in Talador.", objectives = "Defeat Gezz'ran while riding your Clefthoof-In-Training.", completion = "Ye did it! I'm sure your clefthoof's enjoyin' this sort of one-on-one attention. We'll let it rest up a bit." }
