WordHunterWoW_QuestEN[36990] = { title = "Clefthoof Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your clefthoof. See if you can't keep it focused and take down that moth.", objectives = "Defeat the Moth of Wrath while riding your Clefthoof-In-Training.", completion = "Glad to see you two make it back. It'll need a bit of time to brush that dust off." }
WordHunterWoW_QuestEN[36991] = { title = "Clefthoof Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Ever seen a ram in a thunderstorm? They'll hide behind anything larger than themselves. I'm not sure if they think the world is ending or what, but it's not great if you're atop one at the time.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your clefthoof and face off against Thundercall, and we'll see if it gets spooked.", objectives = "Defeat Thundercall while riding your Clefthoof-In-Training.", completion = "Well, it's a bit wet, but seems to be in good spirits. I'll get 'er dried off and into bed." }
WordHunterWoW_QuestEN[36992] = { title = "Clefthoof Training: Ironbore", description = "Alright, we've taken on foes in the sky and on land, and even in the rain. What happens when the beasts are below your feet, though? We're about to find out!\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your clefthoof on out to the sandy shores and see if you can't take down one of the elder rockworms: Ironbore.", objectives = "Defeat Ironbore while riding your Clefthoof-In-Training.", completion = "The sand worm's bit the dust? Well done, I'll get this beast bedded down for the night." }
WordHunterWoW_QuestEN[36993] = { title = "Clefthoof Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the best hunters I've ever had the misfortune of meeting. If anyone can pose a real test for your future mount, it's one of their chief beast-killers.\n\nOut in Nagrand, you'll find an orc by the name of Karak. They call him the Great Hunter, and he's taken down more fierce beasts than any other in the clan. Get astride your clefthoof and bring him down. In the name of the poor wee beasts!", objectives = "Defeat Karak the Great Hunter while riding your Clefthoof-In-Training.", completion = "Hunted the hunter, eh? Your beast doesn't seem any worse for wear, either! I'll brush it down." }
WordHunterWoW_QuestEN[36994] = { title = "Clefthoof Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your clefthoof, mount up, and bring it down. If the two of you survive, your clefthoof will truly be ready.", objectives = "Defeat Maimclaw while riding your Clefthoof-In-Training.", completion = "Your clefthoof is now fully-trained, and it's all thanks to you! I'm going to tear up here if I don't just hand you these reins and send you on your way. Great job, commander!" }
WordHunterWoW_QuestEN[36995] = { title = "Boar Training: Riplash", description = "That boar's seen it's share of combat out in Gorgrond, so it'll be a bit easier to train. We'll start off in it's home, as you've done with yer other beasties.\n\nSee if the two of you can't take down the mighty raptor known as Riplash.", objectives = "Defeat Riplash while riding your Boar-In-Training.", completion = "Those were some mighty big claws to tangle with. Your boar  will need a nap after that one." }
WordHunterWoW_QuestEN[36996] = { title = "Boar Training: Gezz'ran", description = "There's plenty more beasts out in the wild that can make a snack of your favorite mount. One of the most cunning on Draenor is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your boar can't overcome this natural defense mechanism. You'll find some mean stalkers out in Talador.", objectives = "Defeat Gezz'ran while riding your Boar-In-Training.", completion = "Ye did it! I'm sure your boar's enjoyin' this sort of one-on-one attention. We'll let it rest up a bit." }
WordHunterWoW_QuestEN[36997] = { title = "Boar Training: Bulbapore", description = "Way down south in the Spires of Arak, the land's being overtaken by the mushrooms that grow underwater. The result? Strange fungal creatures sprouting up all over the place.\n\nTaking on a strange creature, like the fungal giant Bulbapore, gives us a great chance to expose your boar to predators it's unfamiliar with.", objectives = "Defeat Bulbapore while riding your Boar-In-Training.", completion = "I'll bet that was quite a fight! Great job, let's let it rest for tonight." }
WordHunterWoW_QuestEN[36998] = { title = "Boar Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your boar reacts to that.", objectives = "Defeat the Gorian Beast-Lasher while riding your Boar-In-Training.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training." }
WordHunterWoW_QuestEN[36999] = { title = "Boar Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both of em.'\n\nHead on out to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. That'll be a good test for the both of ye.", objectives = "Defeat the Darkwing Roc while riding your Boar-In-Training.", completion = "From now on, I'm sure your mount will always remember to keep one eye on the skies. Great job!" }
WordHunterWoW_QuestEN[37000] = { title = "Boar Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it'll probably be a pretty good test for your boar. See if you can't keep it focused and take down that moth.", objectives = "Defeat the Moth of Wrath while riding your Boar-In-Training.", completion = "Glad to see you two make it back. It'll need a bit of time to brush that dust off." }
