WordHunterWoW_QuestEN[37004] = { title = "Boar Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your boar, mount up, and bring it down. If the two of you survive, your boar will truly be ready.", objectives = "Defeat Maimclaw while riding your Boar-In-Training.", completion = "Your rocktusk is now ready to see combat, commander. Here's the reins, you'll need 'em ridin' this bucket of muscle!\n\nGreat job with the training!" }
WordHunterWoW_QuestEN[37005] = { title = "Riverbeast Training: Gezz'ran", description = "This beast's spent quite a few years out in the wilds of Talador, I'd say we start the training there. It's fairly docile, as well. I don't think it will take quite as long to train as the others.\n\nAs ye probably know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", objectives = "Defeat Gezz'ran while riding your Riverbeast-In-Training.", completion = "Ye did it! I'm sure your riverbeast's enjoyin' this sort of one-on-one attention. We'll let it rest up a bit." }
