WordHunterWoW_QuestEN[37013] = { title = "Riverbeast Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your riverbeast, mount up, and bring it down. If the two of you survive, your riverbeast will truly be ready.", objectives = "Defeat Maimclaw while riding your Riverbeast-In-Training.", completion = "You know, I didn't really believe you when you decided to start training this thing. But here it is, a trained riverwallow.\n\nI guess if a beast needs training, you're the one to do it! Great work, commander!" }
WordHunterWoW_QuestEN[37014] = { title = "Auctioning for Parts", description = "<The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. \n\nIf you found all of these items, you're confident you could restore it>", objectives = "<The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. \n\nIf you found all of these items, you're confident you could restore it>", progress = "<The power crystal for this unit has been disconnected. Whatever did this also managed to rip out the other support modules. \n\nIf you found all of these items, you're confident you could restore it>", completion = "You can hear the power building inside the unit." }
WordHunterWoW_QuestEN[37015] = { title = "Elekk Training: Cruel Ogres", description = "This beast is surely at home in Nagrand, and I bet ye after all of the years of domestication by Draenei, it's going to be a snap to train.\n\nLet's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher, the one that smells of blood and fear, go on and see how your elekk  reacts to that.", objectives = "Defeat the Gorian Beast-Lasher while riding your Meadowstomper-In-Training.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training." }
