WordHunterWoW_QuestEN[37021] = { title = "Elekk Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", objectives = "Defeat Maimclaw while riding your Meadowstomper-In-Training.", completion = "A fine beast, to be sure, commander. It'll stand up in even the toughest battles.\n\nI'll admit, I'm a bit jealous of ye'! Here's the reins! I'll be sure to take good care of it when ye bring it back." }
WordHunterWoW_QuestEN[37022] = { title = "Wolf Training: Cruel Ogres", description = "The wolves of Draenor are some of the most savage beasts around, but they've also gotten used to the sights and smells of the orcs and ogres that live here. It shouldn't take us much time at all to train this little ball of fur and death.\n\nLet's set it loose against the ogres of the region that yer familiar with. That Gorian Beast-Lasher, the one that smells of blood and fear, go on and see how your wolf reacts to that.", objectives = "Defeat the Gorian Beast-Lasher while riding your Snarler-In-Training.", completion = "Those poor beasts! I'm glad you two put that ogre out of commission. Check back in tomorrow and we can continue the training." }
