WordHunterWoW_QuestEN[37028] = { title = "Wolf Training: The Garn", description = "I've got one last challenge for ye, commander, but if it isn't a doozy.\n\nThey call them the garn. Wolves as black as night, and twice the size of a normal wolf, they can tear a man apart in seconds. Any beast in their right mind would be scared witless at the sight of such a predator.\n\nThere's a lone garn that's made it from their usual home in Frostfire, all the way over to Nagrand. Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.", objectives = "Defeat Maimclaw while riding your Snarler-In-Training.", completion = "I can't believe you've managed to train your wolf already! It feels like it was just yesterday that the little ball of fur and death came into my stables.\n\nI'll hand it to ye, that's a fierce little mount ye got there. Here's the reins, enjoy!" }
WordHunterWoW_QuestEN[37029] = { title = "Sigil of the Black Hand", description = "<Goraluk sighs with... relief? ...or perhaps regret?>\n\nOnce I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers.\n\nThe Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", objectives = "Collect 4 Embers of the Mountain, 4 Hearts of Stone, and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Normal difficulty.", progress = "I will require essences from each of the Foundry's guardians if this is to work.", completion = "You have done it!\n\n<Goraluk takes the items from your hands, and turns his back for a few moments>\n\nNow, I will touch this Sigil to your hand, and the entrance to the Crucible will open at your touch. Good luck." }
WordHunterWoW_QuestEN[37030] = { title = "Sigil of the Black Hand (Heroic)", description = "<Goraluk sighs with... relief? ...or perhaps regret?>\n\nOnce I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers.\n\nThe Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", objectives = "Collect 4 Embers of the Mountain, 4 Hearts of Stone, and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Heroic difficulty.", progress = "I will require essences from each of the Foundry's guardians if this is to work.", completion = "You have done it!\n\n<Goraluk takes the items from your hands, and turns his back for a few moments>\n\nNow, I will touch this Sigil to your hand, and the entrance to the Crucible will open at your touch. Good luck." }
WordHunterWoW_QuestEN[37031] = { title = "Sigil of the Black Hand (Mythic)", description = "<Goraluk sighs with... relief? ...or perhaps regret?>\n\nOnce I walked these halls with pride, holding my head high as an orc of the Blackrock clan. But this is a wrong path. Our hammers were meant to craft axes, swords... not these machines from the stranger's whispers.\n\nThe Warlord will not be swayed, but by force. If you can retrieve essences from the Foundry's most powerful guardians, I can craft for you a sigil that will permit direct access to Blackhand's Crucible.", objectives = "Collect 4 Embers of the Mountain, 4 Hearts of Stone, and 4 Shards of Iron from the final bosses of each wing of the Blackrock Foundry on Mythic difficulty.", progress = "I will require essences from each of the Foundry's guardians if this is to work.", completion = "You have done it!\n\n<Goraluk takes the items from your hands, and turns his back for a few moments>\n\nNow, I will touch this Sigil to your hand, and the entrance to the Crucible will open at your touch. Good luck." }
WordHunterWoW_QuestEN[37032] = { title = "Boar Training: Riplash", description = "This boar is at home in the rocky plains of Gorgrond, so it will be easier to train. As with other beasts, we will begin the training in the place it calls home.\n\nTest your boar against the great predator Riplash, a raptor known to hunt boars.", objectives = "Defeat Riplash while riding your Boar-In-Training.", completion = "A mighty kill. Your beast will need to rest now." }
WordHunterWoW_QuestEN[37033] = { title = "Boar Training: Gezz'ran", description = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning on is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador.", objectives = "Defeat Gezz'ran while riding your Boar-In-Training.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water." }
WordHunterWoW_QuestEN[37034] = { title = "Boar Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", objectives = "Defeat Bulbapore while riding your Boar-In-Training.", completion = "You have returned victorious. I will bed your mount down for the night." }
WordHunterWoW_QuestEN[37035] = { title = "Boar Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your beast reacts to that.", objectives = "Defeat the Gorian Beast-Lasher while riding your Boar-In-Training.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well." }
WordHunterWoW_QuestEN[37036] = { title = "Boar Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", objectives = "Defeat the Darkwing Roc while riding your Boar-In-Training.", completion = "From now on, your mount will always remember to keep one eye on the skies." }
WordHunterWoW_QuestEN[37037] = { title = "Boar Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your boar. See if you can keep it focused and defeat the moth.", objectives = "Defeat the Moth of Wrath while riding your Boar-In-Training.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount." }
WordHunterWoW_QuestEN[37038] = { title = "Boar Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "Defeat Thundercall while riding your Boar-In-Training.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest." }
WordHunterWoW_QuestEN[37039] = { title = "Boar Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", objectives = "Defeat Ironbore while riding your Boar-In-Training.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night." }
WordHunterWoW_QuestEN[37040] = { title = "Boar Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "Defeat Karak the Great Hunter while riding your Boar-In-Training.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight." }
WordHunterWoW_QuestEN[37041] = { title = "Boar Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your boar, mount up, and bring it down. If the two of you survive, your boar will truly be ready.", objectives = "Defeat Maimclaw while riding your Boar-In-Training.", completion = "The garn is defeated, and your boar is now ready to see combat. Here are the reins, may you never part company." }
WordHunterWoW_QuestEN[37043] = { title = "Scraps of Iron", description = "At the armory, we can take scraps of Iron Horde armor that you collect and turn them into new gear. It's not the strongest stuff in the world, but it looks good.\n\nGet some Iron Horde scraps and come back my way. I'll set you up with a nice tabard for your troubles.", objectives = "Collect 5 Iron Horde Scraps from Iron Horde on Draenor.", progress = "Got those scraps?", completion = "Those scraps will do." }
WordHunterWoW_QuestEN[37044] = { title = "Unconventional Inventions", description = "We've got a lot goin' on here at the workshop. We're buildin' new inventions all the time, and you can find 'em behind me on the workbench.\n\nGo ahead and grab today's glorious invention. Use it at your own risk.", objectives = "Acquire an invention from the workbench at your Goblin Workshop.", progress = "A goblin workshop can get dangerous. Watch out for exploding explosives!", completion = "Pretty cool invention you have there." }
WordHunterWoW_QuestEN[37045] = { title = "Salvaging the Situation", description = "Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful.\n\nI have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?", objectives = "Use the Small Sack of Salavaged Goods near the incinerator at your Salvage Yard.", progress = "Have you burned through that bag of salvage yet?", completion = "That's all? Well. don't feel too bad. Some days we find nothing and the next we hit the jackpot!\n\nHere, I have a fresh supply of items from our latest outing. Check them out.\n\nGood luck!" }
WordHunterWoW_QuestEN[37046] = { title = "The Headhunter's Harvest", description = "Hey der mon, I be ya new headhunter. \nThe tavern be a perfect place for adventurers to rest after a long journey. It also be a great place to talk them into joining our cause.\n\nI be havin' a few recruits for ya to look at, if ya find one we can hire then I'll give ya a little somethin' as a finder fee for ya time.", objectives = "Recruit a follower from Akanja in the Frostwall Tavern.", progress = "Ya find a recruit ya like?", completion = "I'm glad ya be findin' a good hire!\n\nMake sure to check back every week and I'll bring ya me latest recruits." }
WordHunterWoW_QuestEN[37047] = { title = "The Light's Gift", description = "", objectives = "The Light has blessed me with newfound power, commander.\n\nNow none can stand against our conviction!You will learn:" }
WordHunterWoW_QuestEN[37048] = { title = "Clefthoof Training: Great-Tusk", description = "The next  step in training your mount for war will be getting it used to the sights and sounds of combat. If it is not trained properly, it might become afraid at a very inopportune time.\n\nThough small, take your clefthoof to the plains of Shadowmoon Valley and find the greatest beast you can. It will grow quickly against such a foe.", objectives = "Defeat Great-Tusk while riding your Clefthoof -In-Training.", completion = "Your clefthoof appears worn, but happy. You have done well, let it rest for a while." }
WordHunterWoW_QuestEN[37049] = { title = "Clefthoof Training: Rakkiri", description = "Your clefthoof is most at home here in Frostfire Ridge, and that is where we will begin the training.\n\nOut on the icy plains, you will find a hunter of blood and death. The winged terror Rakkiri is feared by beasts across this region, and will prove a good first test for your future mount.", objectives = "Defeat Rakkiri while riding your Clefthoof-In-Training.", completion = "The clefthoof is in good shape, you are a fine trainer for the beast. It will require some rest." }
WordHunterWoW_QuestEN[37050] = { title = "Clefthoof Training: Riplash", description = "Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge.\n\nTake your beast to the nest of the great Riplash, and see if you cannot emerge victorious.", objectives = "Defeat Riplash while riding your Clefthoof-In-Training.", completion = "A mighty kill. Your beast will need to rest now." }
WordHunterWoW_QuestEN[37051] = { title = "Clefthoof Training: Gezz'ran", description = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning on is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador.", objectives = "Defeat Gezz'ran while riding your Clefthoof-In-Training.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water." }
