WordHunterWoW_QuestEN[37060] = { title = "Lost in Transition", description = "Sir, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for.\n\nUnfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters.\n\nIf you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", objectives = "Gather 5 Crate of Surplus Materials.", progress = "Hello commander, what can I do for you?", completion = "Thank you, according to the ledger that appears to be everything we're missing.\nThose peons are going to be cleaning the latrines tonight for this!" }
WordHunterWoW_QuestEN[37062] = { title = "Tricks of the Trade", description = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean.\n\nSometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time.\n\nLuckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", objectives = "Find and rouse the missing Trader.", progress = "Trading isn't always the most exciting enterprise. But I do enjoy it.", completion = "You have learned one of my tricks of the trade, <name>." }
WordHunterWoW_QuestEN[37063] = { title = "Elekk Training: Cruel Ogres", description = "This beast is surely at home in Nagrand, and after the years of domestication by Draenei it will be quite easy to train.\n\nWe shall face it against the ogres of the region that you are familiar with. The Gorian Beast-Lasher, the one that smells of blood and fear, see how this elekk reacts to him.", objectives = "Defeat the Gorian Beast-Lasher while riding your Meadowstomper-In-Training.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well." }
WordHunterWoW_QuestEN[37064] = { title = "Elekk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", objectives = "Defeat the Darkwing Roc while riding your Meadowstomper-In-Training.", completion = "From now on, your mount will always remember to keep one eye on the skies." }
WordHunterWoW_QuestEN[37065] = { title = "Elekk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your elekk. See if you can keep it focused and defeat the moth.", objectives = "Defeat the Moth of Wrath while riding your Meadowstomper-In-Training.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount." }
WordHunterWoW_QuestEN[37066] = { title = "Elekk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "Defeat Thundercall while riding your Meadowstomper-In-Training.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest." }
