WordHunterWoW_QuestEN[37068] = { title = "Elekk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "Defeat Karak the Great Hunter while riding your Meadowstomper-In-Training.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight." }
WordHunterWoW_QuestEN[37069] = { title = "Elekk Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your elekk, mount up, and bring it down. If the two of you survive, your elekk will truly be ready.", objectives = "Defeat Maimclaw while riding your Meadowstomper-In-Training.", completion = "A fine beast, sure to be your companion in many battles to come. Here are the reins, be strong but fair in your care of this great beast." }
WordHunterWoW_QuestEN[37070] = { title = "Power of the Nether", description = "", objectives = "Fighting alongside you has strengthened my connection to the nether like never before, commander.\n\nI will use my new power to rain death down upon your enemies. They will learn to fear you.You will learn:" }
WordHunterWoW_QuestEN[37071] = { title = "Riverbeast Training: Gezz'ran", description = "This bulbous beast has spent a number of years in the wilds of Talador. We will begin the training there. It is already docile, as well, so I do not think it will take as long to train as the others.\n\nAs you know, stalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your riverbeast can't overcome this natural defense mechanism.", objectives = "Defeat Gezz'ran while riding your Riverbeast-In-Training.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water." }
WordHunterWoW_QuestEN[37072] = { title = "Riverbeast Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", objectives = "Defeat Bulbapore while riding your Riverbeast-In-Training.", completion = "You have returned victorious. I will bed your mount down for the night." }
