WordHunterWoW_QuestEN[37079] = { title = "Riverbeast Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your riverbeast, mount up, and bring it down. If the two of you survive, your riverbeast will truly be ready.", objectives = "Defeat Maimclaw while riding your Riverbeast-In-Training.", completion = "I had never seen such a beast before coming here, but you have trained it. No small feat, to be certain. Take the reins, you have earned them." }
WordHunterWoW_QuestEN[37080] = { title = "Glorious Slaughter", description = "", objectives = "The blood o' our fallen foes has not yet sated my thirst, commander.\n\nI have a trick up me sleeve that ought ta help change that.You will learn:" }
WordHunterWoW_QuestEN[37081] = { title = "Burning Rage", description = "", objectives = "We have shown far too much mercy to your enemies, commander.\n\nIf you would allow me, I have a spell I've been perfecting that will show them what happens when you stand in our way.You will learn:" }
WordHunterWoW_QuestEN[37082] = { title = "Call of the Gladiator", description = "Your merciless rampage has not gone unnoticed, gladiator. So many of your enemies have fallen before your might. It is because of your unrelenting savagery that Imperator Mar'gok himself has requested your presence at the grand Highmaul Coliseum. It is at Highmaul that a battle of epic proportions awaits.\n\nShould you heed the call of the gladiator, present this sigil to my brother, Kharg. He is the arena master residing outside of the Coliseum in Nagrand.", objectives = "Take the Sigil of Highmaul to Kharg outside the Highmaul Coliseum in Nagrand.\n\nProvided item:", completion = "A bold decision, gladiator. For most, death is the only thing they find at the Coliseum. Surviving here is more than a test of skill, it is a test of wills. Do you have the fortitude to become a champion?" }
WordHunterWoW_QuestEN[37083] = { title = "Fight, Kill, Salute!", description = "The greatest gladiators on Draenor have fought for glory and honor inside the Coliseum. Will you become a legend like Kargath Bladefist or will you be nothing more than bone dust beneath the boots of a more savage gladiator? There is only one way to find out.\n\nYou must enter the competition and fight! The price of victory is 100 lives!\n\nI will admit you without cost once per day, but if you fail and wish to fight again you must pay the price of admission in blood and bone!", objectives = "Kill 100 Gladiators at the Coliseum in Highmaul.\n\nYou may access the Coliseum by talking to Kharg at Highmaul or Boneslag at your Gladiator's Sanctum.", completion = "Remarkable! You have proven yourself a true gladiator. And to a true gladiator goes more than honor and glory!" }
WordHunterWoW_QuestEN[37084] = { title = "The Shadows Call", description = "", objectives = "The shadows... they have taught me how to slip into the minds of our enemies.\n\nYes... turn them against their own. Our victory will be swift. Rawk!You will learn:" }
WordHunterWoW_QuestEN[37085] = { title = "Fury of the Clan", description = "", objectives = "Our clan strong. Strongest.\n\nI feed our lust, make us stronger. We win!You will learn:" }
WordHunterWoW_QuestEN[37086] = { title = "Salvaging the Situation", description = "Here at the Salvage Yard we inspect any extra material your followers bring back from the field, preserving anything that may be useful.\n\nI have an extra pack of material our people brought in that I've yet to go through. Why don't you take it over to the incinerator and see if it contains anything useful?", objectives = "Use the Small Sack of Salavaged Goods near the incinerator at your Salvage Yard.", progress = "Have you burned through that bag of salvage yet?", completion = "That's all? Well. don't feel too bad. Some days we find nothing and the next we hit the jackpot!\n\nHere, I have a fresh supply of items from our latest outing. Check them out.\n\nGood luck!" }
WordHunterWoW_QuestEN[37087] = { title = "Lost in Transition", description = "Sir, the storehouse is fully operational and I've seen to it that your supplies are safely stored away and accounted for.\n\nUnfortunately, during the rest of my audit I found that we are missing a few crates of surplus material - probably misplaced by one of the porters.\n\nIf you happen to come across any of the surplus crates while making your rounds, please bring them to me and I'll update our ledger.", objectives = "Gather 5 Crate of Surplus Materials.", progress = "Hello commander, what can I do for you?", completion = "According to the ledger this appears to be everything we're missing. Those porters will be cleaning the latrines tonight for this!" }
WordHunterWoW_QuestEN[37088] = { title = "Tricks of the Trade", description = "To pass the time, traders have been known to consume beverages of an inspired nature, if you know what I mean.\n\nSometimes, they drink a bit too much. Your trader might have stumbled beyond the gates and passed out under a tree. It's been known to happen from time to time.\n\nLuckily, I have a brew that I use to rouse groggy traders. One splash and I find they're more willing to work.", objectives = "Find and rouse the missing Trader.", completion = "You have learned one of my tricks of the trade, <name>." }
WordHunterWoW_QuestEN[37091] = { title = "Unconventional Inventions", description = "The workshop is bustling with the whir of minds and motors. We're coming up with new inventions all the time.\n\nTry out today's glorious invention on the workbench behind me.", objectives = "Acquire an invention from the workbench at the Gnomish Gearworks.", completion = "Nice invention!" }
WordHunterWoW_QuestEN[37092] = { title = "Scraps of Iron", description = "At the Dwarven Bunker, we can take scraps of Iron Horde armor that you collect and turn them into new gear. It's not the strongest stuff in the world, but it looks good.\n\nGet some Iron Horde scraps and come back my way. I'll set you up with a nice tabard for your troubles.", objectives = "Collect 5 Iron Horde Scraps from Iron Horde on Draenor.", progress = "Got those scraps?", completion = "Those scraps will do." }
WordHunterWoW_QuestEN[37093] = { title = "Talbuk Training: Great-Tusk", description = "The talbuk is ready for more training, and for this, we will return to its home in Shadowmoon Valley.\n\nOne of the great beasts of this land, Great-Tusk, has taken the valley for his own. Pit your beast against him in combat, and if you should survive, it will have greater confidence in its own abilities.", objectives = "Defeat Great-Tusk while riding your Talbuk-In-Training.", completion = "That was a fine battle to test your talbuk against. It will need to rest before we can continue the training." }
WordHunterWoW_QuestEN[37094] = { title = "Talbuk Training: Rakkiri", description = "We shall start training the talbuk here, on the icy plains of Frostfire Ridge. We must train it rigorously, or else it may become afraid at the sight of combat, and run.\n\nFind the great blood-sucker, Rakkiri, out on the frozen plains, and bring him down astride your talbuk. That will give it a taste for combat.", objectives = "Defeat Rakkiri while riding your Talbuk-In-Training.", completion = "Your talbuk is growing quickly, let us let it rest." }
WordHunterWoW_QuestEN[37095] = { title = "Talbuk Training: Riplash", description = "Many beasts will cower in fear at the sight of a mighty predator. In the desolate cliffs of Gorgrond lives one of the most fierce. It will prove your next challenge.\n\nTake your beast to the nest of the great Riplash, and see if you cannot emerge victorious.", objectives = "Defeat Riplash while riding your Talbuk-In-Training.", completion = "A mighty kill. Your beast will need to rest now." }
WordHunterWoW_QuestEN[37096] = { title = "Talbuk Training: Gezz'ran", description = "Many of the creatures of Draenor have grown and thrived in a most hostile environment. One of the most cunning is the stalker.\n\nStalkers can blend into their environments, allowing them to sneak in and steal the eggs of nearby prey. See if you and your beast can overcome this natural defense mechanism. You will find a proper predator in Talador.", objectives = "Defeat Gezz'ran while riding your Talbuk-In-Training.", completion = "A savage beast, but you have triumphed. Fine work, I will get your mount some water." }
WordHunterWoW_QuestEN[37097] = { title = "Talbuk Training: Bulbapore", description = "In the far south, in the Spires of Arak, the land is being swallowed by the mushrooms that grow underwater, and strange fungal creatures grow uninhibited.\n\nTaking on a strange creature, like the fungal giant Bulbapore, will grant you a chance to expose your mount to unfamiliar predators.", objectives = "Defeat Bulbapore while riding your Talbuk-In-Training.", completion = "You have returned victorious. I will bed your mount down for the night." }
WordHunterWoW_QuestEN[37098] = { title = "Talbuk Training: Cruel Ogres", description = "Nagrand is home to the mightiest beasts in Draenor, and the ogres of the region have learned to tame them using brutal techniques.\n\nThere is one ogre in particular, the Gorian Beast-Lasher, that smells of blood and fear. Go on and see how your beast reacts to that.", objectives = "Defeat the Gorian Beast-Lasher while riding your Talbuk-In-Training.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well." }
WordHunterWoW_QuestEN[37099] = { title = "Talbuk Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", objectives = "Defeat the Darkwing Roc while riding your Talbuk-In-Training.", completion = "From now on, your mount will always remember to keep one eye on the skies." }
WordHunterWoW_QuestEN[37100] = { title = "Talbuk Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your talbuk. See if you can keep it focused and defeat the moth.", objectives = "Defeat the Moth of Wrath while riding your Talbuk-In-Training.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount." }
WordHunterWoW_QuestEN[37101] = { title = "Talbuk Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "Defeat Thundercall while riding your Talbuk-In-Training.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest." }
WordHunterWoW_QuestEN[37102] = { title = "Talbuk Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", objectives = "Defeat Ironbore while riding your Talbuk-In-Training.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night." }
WordHunterWoW_QuestEN[37103] = { title = "Talbuk Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "Defeat Karak the Great Hunter while riding your Talbuk-In-Training.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight." }
WordHunterWoW_QuestEN[37104] = { title = "Talbuk Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your talbuk, mount up, and bring it down. If the two of you survive, your talbuk will truly be ready for war.", objectives = "Defeat Maimclaw while riding your Talbuk-In-Training.", completion = "A powerful and swift companion, and now unafraid of the creatures you may run into. You have done well in your training of the beast, and I am pleased to present you with the reins." }
WordHunterWoW_QuestEN[37105] = { title = "Wolf Training: Cruel Ogres", description = "The wolves of this land are the most savage beasts I have seen, and surely do not fear orc nor ogre.\n\nBring him to bear against once of the ogres that you are familiar with. The Gorian Beast-Lasher, the one that smells of blood and fear, see how the wolf reacts to him.", objectives = "Defeat the Gorian Beast-Lasher while riding your Snarler-In-Training.", completion = "Those beasts will recover, in time. Let us rest for tonight, you have done well." }
WordHunterWoW_QuestEN[37106] = { title = "Wolf Training: Darkwing Roc", description = "The windrocs of Nagrand are a smart predator, often swooping down on unwary prey in packs. If your beast doesn't keep an eye on the sky, it's likely to lose both.\n\nTravel to Nagrand and take on the fiercest windroc of the bunch, the Darkwing Roc. It will be a good test for your mount.", objectives = "Defeat the Darkwing Roc while riding your Snarler-In-Training.", completion = "From now on, your mount will always remember to keep one eye on the skies." }
WordHunterWoW_QuestEN[37107] = { title = "Wolf Training: Moth of Wrath", description = "Deep in the forests of Nagrand are some beasts capable of evading almost any predator. The greatest of them all, the Moth of Wrath, is coated with a foul-smelling dust.\n\nIf the moth dust is enough to keep wolves at bay, it will probably be a pretty good test for your wolf. See if you can keep it focused and defeat the moth.", objectives = "Defeat the Moth of Wrath while riding your Snarler-In-Training.", completion = "Glad to see you back. I will need some time to brush that dust off of your mount." }
WordHunterWoW_QuestEN[37108] = { title = "Wolf Training: Thundercall", description = "The elements can sometimes pose a problem for some beasts. Even the mightiest wolf will often cower at the sound of thunder in the distance.\n\nIn Nagrand, off on a windswept cliff high above the shore, is a creature made of pure thunderstorms. Hop atop your beast and face off against Thundercall, and we will see how your mount fares.", objectives = "Defeat Thundercall while riding your Snarler-In-Training.", completion = "Your mount is bit wet, but seems to be in good spirits. I will dry it off and put it to rest." }
WordHunterWoW_QuestEN[37109] = { title = "Wolf Training: Ironbore", description = "You have defeated foes in the sky and on land, and even in the rain. Next, you face beasts beneath your very feet.\n\nThe rockworm is a cunning predator, striking at prey from below the sands. Many beasts of Nagrand have grown wary of the rumbling of the earth. Take your mount on out to the sandy shores test it against the elder worm Ironbore.", objectives = "Defeat Ironbore while riding your Snarler-In-Training.", completion = "You stand strong, though the ground crumbles. Admirable.\n\nAllow your mount to rest for the night." }
WordHunterWoW_QuestEN[37110] = { title = "Wolf Training: Orc Hunters", description = "The Warsong Clan of Nagrand are some of the finest hunters the world of Draenor has ever known. Their beast-killers will aid us in putting this mount to the test.\n\nOut in Nagrand, you will find an orc by the name of Karak, the Great Hunter. He has slain more fierce beasts than any other in the clan. Face him astride your mount, and avenge the slain.", objectives = "Defeat Karak the Great Hunter while riding your Snarler-In-Training.", completion = "Ah, you have hunted the hunter. Many beasts will be pleased tonight." }
WordHunterWoW_QuestEN[37111] = { title = "Wolf Training: The Garn", description = "The last test for your mount will pit it against one of the great terrors of this land.\n\nThe garn. Wolves as black as night, and twice the size of a normal wolf, they can tear an orc apart in mere moments. The beasts here wisely fear them.\n\nThere is a lone garn that calls Nagrand its home. Take your wolf, mount up, and bring it down. If the two of you survive, your wolf will truly be ready.", objectives = "Defeat Maimclaw while riding your Snarler-In-Training.", completion = "A savage beast, yet you have tamed it. I should learn to never underestimate you. It awaits your command patiently, almost like it knows you wait for it. Here are the reins, may your companion be ever at your side." }
WordHunterWoW_QuestEN[37112] = { title = "Rest and Relaxation", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", objectives = "Speak with Innkeeper Farley at the Lion's Pride Inn.", completion = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.\n\nWould you like to try a sampling of some of our fine food and drink?" }
WordHunterWoW_QuestEN[37113] = { title = "Thisalee Crow", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[37114] = { title = "Choluna", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[37119] = { title = "The Headhunter's Harvest", description = "The inn provides a perfect place for adventurers to take a rest between their travels. It's also a great place to talk them into joining our cause over a few rounds of drinks.\n\nGo through my selection and let's see if we can obtain a new recruit. I'll give you a little something as a finder's fee for your efforts.", objectives = "Recruit a follower from Lysa Serion in the Lunarfall Inn.", progress = "Find a recruit that you like?", completion = "Ahh, I'm glad you were able to find a good hire!\n\nI'll get back to looking for more candidates for you. Check back in every week to see my latest selections." }
WordHunterWoW_QuestEN[37120] = { title = "Sunspring POI Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37121] = { title = "The Black Claw", description = "Behind me, as ye can probably see, is a giant black claw. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", objectives = "Ask Fanny Firebeard about the Black Claw of Sethe.", completion = "Like I said, the claw has a strange effect on the mounts we've got here. If ye have it with ye when training a mount-in-training, your mount will be MUCH more vulnerable.\n\nShould ye find the training not rough enough, ye might want to challenge yourself.\n\nI'd have a pretty hefty prize for anyone that could manage that!" }
WordHunterWoW_QuestEN[37122] = { title = "Teeth of a Predator", description = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything!", objectives = "Ask Fanny Firebeard about the Garn-Tooth Necklace.", completion = "I've not seen the beasts go so wild in all of my years, as the day we brought this thing back to the stables.\n\nShould ye find the training still not hard enough, take it along with ye. Your mounts-in-training will be even MORE vulnerable.\n\nBe careful! I'd give a prize to anyone that could best every beast with such an artifact, but I don't want to see you wind up dead!" }
WordHunterWoW_QuestEN[37123] = { title = "The Black Claw", description = "You've probably seen this enormous, black claw in our pile of supplies. We found it while we were out hunting new beasts to tame. The animals seem to be quite afraid of it, perhaps the beast it belonged to used to hunt them.", objectives = "Ask Sage Paluna about the Black Claw of Sethe.", progress = "Yes?", completion = "This claw has a strange effect on the mounts we have. If you have it with you when training a mount-in-training, your mount will be MUCH more vulnerable.\n\nShould you find the training not rough enough, you might want to challenge yourself further by carrying it with you.\n\nI think besting the beasts of Draenor with it would certainly be worthy of a reward." }
WordHunterWoW_QuestEN[37124] = { title = "Teeth of a Predator", description = "This necklace dropped off of one of the orc hunters we found while out taming beasts. I've never seen the animals react so strongly to anything.", objectives = "Ask Sage Paluna about the Garn-Tooth Necklace.", completion = "I have not seen the beasts go so mad in all of my years as a sage, as the day we brought this necklace  back to the stables.\n\nShould you find the training still not hard enough, take it along with you. Your mounts-in-training will be even MORE vulnerable.\n\nBe careful! I would gladly reward anyone that could best every beast with such an artifact, but I do not want to see you wind up dead!" }
WordHunterWoW_QuestEN[37125] = { title = "A Rare Find", description = "", objectives = "Every once in a while an archaeologist experiences a rare find... an artifact that time has delicately preserved through the ages, as if it had simply fallen out of a time machine.\n\nEven thinking about the thrill of such a find makes me get all emotional... relics like that are worth a freakin' fortune!", progress = "Every once in a while an archaeologist experiences a rare find... an artifact that time has delicately preserved through the ages, as if it had simply fallen out of a time machine.\n\nEven thinking about the thrill of such a find makes me get all emotional... relics like that are worth a freakin' fortune!", completion = "Nice find! This relic is going to be a welcome addition to someone's private collection!" }
WordHunterWoW_QuestEN[37126] = { title = "An Ogre Without His Sword...", description = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\"\n\nI want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse.\n\nIt would mean a great deal to me. An ogre without his sword isn't an ogre at all.", objectives = "Retrieve Tormmok's Favorite Sword from Vizier Dar'gud at Broken Precipice in Nagrand.", progress = "I want my sword more than I can tell you, commander.", completion = "Yes... this is it.\n\nCommander, I will cleave your foes like never before now that I have my sword." }
WordHunterWoW_QuestEN[37127] = { title = "The Light of Exodus", description = "My grandfather always told me stories of a powerful crystal made of the Light that would grant power to those who intended to use it for good. He called it the Light of Exodus.\n\nI never believed him... until now.\n\nYour scouts have found a crystal that sounds just like it. It has been taken by a terrible demon and is being corrupted at the Beacon of Sha'tar in Shattrath.\n\nWe have to hurry!", objectives = "Retrieve the Light of Exodus from Ambassador Hellmaw at Beacon of Sha'tar in Shattrath City in Talador.", progress = "If the Light of Exodus is half as powerful as my grandfather told me, we cannot let it fall into the Legion's hands.", completion = "It's so beautiful...\n\nOh, commander, thank you. A million times thank you!" }
WordHunterWoW_QuestEN[37128] = { title = "Settling Grievances", description = "Our scouts have found a powerful draenei crystal being corrupted by Ambassador Hellmaw at the Beacon of Sha'tar in Shattrath. The draenei call it the Light of Exodus.\n\nCommander, I'd like to accompany you on this mission. Hellmaw slew my brother in Outland... this is personal.", objectives = "Retrieve the Light of Exodus from Ambassador Hellmaw at Beacon of Sha'tar in Shattrath City in Talador.", progress = "We cannot allow the Legion to gain any advantage.", completion = "It is done. The Legion have suffered a mighty blow." }
WordHunterWoW_QuestEN[37129] = { title = "Unwelcome Memories", description = "The botani in the Everbloom Wilds are doin' some sorta foul magic to create these plant... well... zombies, basically.\n\nI've seen what happens with armies o' mindless slaves. The Lich King...\n\n<Delvar's eyes close.>\n\nNo matter. We cannae let this escalate any further. I heard o' a particularly nasty one they've just made... let's kill it and see what makes it tick.", objectives = "Retrieve Infested Orc Remains from Acanthus at Everbloom Wilds in Gorgrond.", progress = "No zombies, plant o' otherwise, are goin' ta walk this world if ol' Delvar has anythin' to say about it.", completion = "I'll be takin' a close look at this... thing. We can't have a repeat o' Northrend." }
WordHunterWoW_QuestEN[37130] = { title = "Sunspring POI Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37131] = { title = "The Dark Lady's Concern", description = "The botani in the Everbloom Wilds kill anything foolish enough to wander too close to their blooms and are raising their corpses as mindless soldiers.\n\nThis is all too reminiscent of the Scourge... and the Dark Lady has taken notice. She has a special mission for us, commander.\n\nThere is a particularly large infested creature that was recently raised. We are to destroy it and retrieve its remains.", objectives = "Retrieve Infested Orc Remains from Acanthus at Everbloom Wilds in Gorgrond.", progress = "I assure you, commander, the Dark Lady has the Horde's best interests at heart. We must stop these botani immediately.", completion = "Thank you, commander. The Dark Lady will appreciate this greatly." }
WordHunterWoW_QuestEN[37132] = { title = "Sunspring POI Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37133] = { title = "Sunspring POI Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37134] = { title = "Sunspring POI Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37135] = { title = "Sunspring POI Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37136] = { title = "Sunspring POI Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[37137] = { title = "Scrying Hard or Hardly Scrying", description = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs.\n\nThey have begun to master their craft... they call to the shadows beyond this realm...\n\nI desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", objectives = "Retrieve Urna's Fathomstaff from Urna Darkfathom at Shadowmoon Enclave in Shadowmoon Valley.", progress = "Taking out our enemies and gaining great power in one motion... my people have a saying for this: Killing two orcs with one stone.", completion = "Yes... yes... this will do nicely. We can use this to do great things.\n\nThank you, commander." }
WordHunterWoW_QuestEN[37140] = { title = "Leorajh's Prayer Beads", description = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements.\n\nOne day bird-men attacked and took prayer beads. Took them to Skettis.\n\nMaster, you help Leorajh get prayer beads back?", objectives = "Retrieve Leorajh's Prayer Beads from Kirox the Wind Dancer in Skettis.", progress = "Elements don't speak to Leorajh like they used to.", completion = "Thank you, master! Elements speak to Leorajh again." }
WordHunterWoW_QuestEN[37141] = { title = "Talonpriest Ishaal", description = "", objectives = "My purpose as a Talonpriest has been fulfilled, though Iskar and Zellek must think me a fool for altering the sacred rites.\n\nI care not for their approval, and I am done hiding in the shadows.\n\nLet me fight for you. I should like to improve this world before I fade away from it." }
WordHunterWoW_QuestEN[37142] = { title = "Ogre Ancestry", description = "Lunk no like fight, want to learn. You help Lunk learn?\n\nFind Lunk ancestors. Lunk have many question. Where Lunk come from? Why Lunk Lunk?\n\nLunk stay here. Small ogres mean, big ogres meaner.", objectives = "Collect an Ogre Family Tree from the Bloodmaul Slag Mines.", progress = "How can LunkLunk if Lunk not know what Lunk is?", completion = "Lunk know you kill many ogre for this, and Lunk very upset about this, but Lunk also still grateful.\n\nWait, dis not Lunk family club..." }
WordHunterWoW_QuestEN[37144] = { title = "Talon Guard Kurekk", description = "", objectives = "You have done much for us. What can I offer, but my blade?\n\nTalon King, let me fight for you." }
WordHunterWoW_QuestEN[37145] = { title = "Budd's Gambit", description = "Listen, I don't know how I got here, but I have it on good authority that there is an entire island made of shiny things and it's just off of the coast a ways.\n\nAll we have to do is hop in the water and swim out there, then we can load up our pockets and swim back! I'm just going to rest up and do some stretching before heading out.\n\nDon't try and stop me!", objectives = "Collect a Very Shiny Thing from the Iron Docks.", progress = "What?", completion = "Oh... this is... well that's very shiny isn't it? I think... I'll just sit here for a while.\n\n<Budd smiles contentedly.>" }
WordHunterWoW_QuestEN[37146] = { title = "Go Fetch", description = "Now THIS is a savage land worthy of my level of heroism!\n\nOh, hello, I did not see you standing there, staring at me. Perhaps you have noticed that every piece of my armor is an ancient relic, forgotten by time.\n\nAs you have properly surmised, an adventurer of my stature does not have time to complete the menial requests I am given daily. I must remain here, yelling aloud to the trade district so that others may witness my heroicness and be inspired.\n\nToday I require a Nightmare Bell, do find one.", objectives = "Collect a Nightmare Bell from Auchindoun.", progress = "What do you want?", completion = "I see you have completed this menial task admirably, almost as if you were intended to experience such a thing. Ah fate, what do you have in store for me next?" }
WordHunterWoW_QuestEN[37147] = { title = "Sky Dancers", description = "Greetings, {name}, and I thank you for your hospitality.\n\nThe Shado-pan have sent several warriors to aid against the Iron Horde, however we can. We are few, though, and they are many.\n\nThe arakkoa in the south are both beautiful and deadly. They appear lighter than air, their attacks a deadly dance that flits from opponent to opponent.\n\nThe winds are on their side, as the four winds lighten the steps of my own allies. Bring me a sample of their winds, if you are able. It will surely aid us.", objectives = "Collect a Bottled Windstorm from Skyreach.", progress = "Did you find the fifth wind?", completion = "I will take this to the Shado-pan right away. Fortune be with you, we will have need of your help again when the winds run quiet." }
WordHunterWoW_QuestEN[37148] = { title = "Oralius' Adventure", description = "Me n' Winky, off on adventures again! This is the life, I tell ye. No burning air to breathe, an' plenty of ogres to kill!\n\n<Oralius rubs his belly.>\n\nWe did leave a bit of a mess back there in the Blackrock Spire, though. A whole mess of these iron-plated orcs and some proto-dragons marched right on up from the south and took it over.\n\nOl' Winky, he couldn't take the guilt. Went on back by himself he did, to stop them!\n\nOr... to JOIN them! Winky, ye two-timing son of an orc. Ye've got to stop him!", objectives = "Collect a Spire Flamefly in Upper Blackrock Spire.", progress = "Did ye stop him?", completion = "Good thinkin'. Winky always loved these flameflies. If we gather enough of them, maybe we can convince hiim to come back!\n\nMaybe, er, you should hold onto this for a while, eh?" }
WordHunterWoW_QuestEN[37149] = { title = "The Void-Gate", description = "My 'master' is an idiot, but you look like you've got some smarts in that oddly-shaped head.\n\nListen up, the Twisting Nether is a chaotic abyss, and things work differently there. I've felt some disturbances, and they don't bode well for any of us.\n\nYes, there are things happening here, in Draenor, that are causing ripples in the nether. No, don't try to wrap your head around how that works, you'll only hurt yourself.\n\nIt's simple: bring me a Void-Gate Key, and maybe I can stop the bad things.", objectives = "Find a Void-Gate Key in the Shadowmoon Burial Grounds.", progress = "You do know that any time you waste talking to me brings us closer to doom, right?", completion = "Perfect, here's a prize for your efforts.\n\nI've got to head out and save everyone now. Again." }
WordHunterWoW_QuestEN[37150] = { title = "For the Birds", description = "Hi! Have you ever held a peachick hatchling?\n\n<Without warning, Mylune grabs both of your hands and then stuffs a tiny chirping bird in them.>\n\nIsn't it so small and light and downy? Like you're holding a beaky peepy lil' CLOUD! It's so adorable you can't help but hug it and cuddle it and stuff regurgitated food in its teeny-tiny mouth.\n\n{name}, the plantfolk in the Everbloom are turning peachicks into monsters before they can grow into beautiful swans. Or whatever they grow into. Please help them!", objectives = "Find a Tiny Peachick Hatchling in The Everbloom.", progress = "Have you rescued a peachick? We're all they have, and those awful plant creatures are doing terrible things to them!\n\n<Mylune's voice suddenly drops two octaves and sends a chill up your spine.>\n\nTerrible. Things.", completion = "<Mylune gently lifts the tiny little bird to her face, nuzzling it. It crawls onto her shoulder and disappears into her nest of green hair. A moment later, a beautiful fan of brightly-colored tailfeathers emerges from the top of her head.>\n\n<Mylune's bright blue eyes grow moist with tears and her mouth goes slack with adoration. You've made the dryad VERY happy.>" }
WordHunterWoW_QuestEN[37151] = { title = "Cold Steel", description = "Do you know what I want? What everyone who came through that portal wants. Every soldier running from a world that didn't understand us, didn't need us. I want that world to love us as much as we love it.\n\nBut we don't really belong there, not anymore. War is part of us, and we can't go back. To everyone back there, we're expendable.\n\nThe only thing that makes me feel better now is the feel of a cold iron cannon in my hands, pointed at the enemy.\n\n<Keeshan stares into his mug of ale.>", objectives = "Find an Iron Autocannon in Grimrail Depot.", progress = "Leave me alone.", completion = "Yeah, this will do nicely. I'm going to run out of ammo, but at least I've got something to live for, for a while.\n\nHere, kid, you're gonna need this more than I am." }
WordHunterWoW_QuestEN[37152] = { title = "Cro's Revenge", description = "HA! The fruit vendor was so cunning, but I, Cro Threadstrong, am even MORE cunning. I have come back into the past to defeat the ogre army before that fruit vendor can turn them against me!\n\nBring me the head of a big, strong ogre from the old slag mines, and I will have crushed the fruit vendor before a single apple has even grown!\n\nCAN YOU HEAR ME, FRUIT VENDOR? I WILL HAVE MY VICTORY!", objectives = "Collect a Giant Ogre Head from the Bloodmaul Slag Mines.", progress = "THE FRUIT VENDOR STANDS NO CHANCE!", completion = "Revenge has the sweetest taste. Like an apple.\n\nTake this, friend. May all of your fruit be CRUSHED INTO PULP LIKE YOUR ENEMIES." }
WordHunterWoW_QuestEN[37153] = { title = "Time-Lost Vikings", description = "Oi, barely made it out of that place!\n\nWe came through the portal to help, and the next thing you know, we're prisoners in the Bloodmaul Slag Mine. It was brutal! We were shackled for days, and covered in filth.\n\nAnd they took my SHIELD!", objectives = "Collect Olaf's Shield from the Bloodmaul Slag Mines.", progress = "<Olaf sobs.>", completion = "Oi, it's a fair sight dirtier, but that's her! Here, this is for you. You have my thanks." }
WordHunterWoW_QuestEN[37154] = { title = "The Cure For Death", description = "Greetings, and my thanks for the warmth of this inn and your hospitality.\n\nAs you can see, this malady of death continues to plague me. My studies on Azeroth and in Northrend met with little luck, and all of my leads ran dry.\n\nI have come to Draenor in the hope of finding something, anything, to go on. My first pilgrimage will be to Auchindoun, a house where souls are put at ease.\n\nIf you should head there yourself, do let me know if you should happen upon anything of interest.", objectives = "Collect a Soulweave Vessel from Auchindoun.", progress = "Did you find anything?", completion = "This... may help me. I will need to return to Light's Hope shortly, you have my thanks.\n\nI will not need these supplies any longer, they are yours." }
WordHunterWoW_QuestEN[37155] = { title = "The Brass Compass", description = "Greetings, commander. I have come on a mission directly from the captain.\n\nAboard any vessel on Azeroth that's manned by at least one orc, you'll hear sea shanties sung about a device capable of navigating the broad, rough ocean of Draenor. The orcs used it to keep their heading true in the choppiest of storms.\n\nPerhaps it's just an old sea tale, but this one chance to find that kind of prize has the captain willing to part with some fine treasure.", objectives = "Find the Brass Compass at the Iron Docks.", progress = "Did you find the compass?", completion = "This might just be what we were looking for. Here's your booty." }
WordHunterWoW_QuestEN[37156] = { title = "The Soulcutter", description = "Don't look at me! Who do you think you are?\n\nYou and I are on the same side, you know. The necromancers here, we have to kill them. All of them.\n\nDon't you agree?\n\nOf course you do, and you can help me accomplish this goal. Find a Soulsever Blade in that hovel where the necromancers have holed up like rats. It has... special properties... that will aid us against the undead.", objectives = "Collect a Soulsever Blade from Auchindoun.", progress = "Did you find the blade?", completion = "Excellent, most excellent.\n\nI will wear it down quickly, and it cannot be repaired due to its unique nature. Expect to hear from me again." }
WordHunterWoW_QuestEN[37157] = { title = "Feeling A Bit Morose", description = "So many years of waking up as a spirit, reanimated by some unseen force time and again, has left one with certain desires - the comforting, velvet blackness of death being chief amongst them.\n\nOne will, however, settle for the lesser prize of a solution capable of removing the scuff marks that the commander's wonderful compatriots left behind in the dining hall in their woefully short stay in Karazhan, whereupon they barely had enough time to irreparably damage the priceless furniture.", objectives = "Collect a barrel of Horribly Acidic Solution from the Iron Docks.", progress = "Was the commander successful?", completion = "One is eternally in your debt for what is, one is certain, an entirely selfless act on the part of the commander.\n\nThough more barrels were likely available, one will staunchly make do with the single barrel provided, comforted in the knowledge that the commander must deal with the great pressing issues of this land, and does not have time to clean up the mud that that so dutifully follows the commander's heroic allies." }
WordHunterWoW_QuestEN[37158] = { title = "Gloriously Incandescent", description = "I did not come here to fight, I have seen too many die already. I have killed so many with my own hands.\n\nI have come to seek the light, and redemption.\n\nThe arakkoa of this land worship the sun as I do. But they are a violent, isolationist, and decadent race, who seem to derive a different message than my own people. This troubles me.\n\nBring me one of their Sun Crystals. I wish to see this light.", objectives = "Collect a Sun Crystal in Skyreach.", progress = "Did you find the crystal?", completion = "The sun, I can see it. It is so bright.\n\nI... wish to be alone. Take this, and my thanks." }
WordHunterWoW_QuestEN[37159] = { title = "Aviana's Request", description = "The arakkoa are creatures of the sky, and are thus within the domain of the great Aviana.\n\nI have been sent to procure a feather, that we may parley with them through the language of the winds. We will extend an invitation of peace, and a place on the Great Bough.\n\nWould you aid us in this quest? The feather must come from an arakkoan of nobility. You will find them in the place known as Skyreach.", objectives = "Collect some Pristine Plumage in Skyreach.", progress = "Did you bring a feather?", completion = "My thanks, <name>. Aviana will be pleased, and we may yet be able to aid you.\n\nAviana has sought fit to bless you with this, use it well." }
WordHunterWoW_QuestEN[37160] = { title = "Cleaving Time", description = "I, Gamon, have come through the dark portal to cleave many orc skulls. Yet my weapon has not kept pace with my rage, and is nicked and dull.\n\nFind me a new weapon - one that is good for removing Hellscream limbs.", objectives = "Find an Iron Limbcleaver in Grimrail Depot.", progress = "What?", completion = "I like this blade. It will see me through much removing of limbs. Here, for you, something to remember me by." }
WordHunterWoW_QuestEN[37161] = { title = "Family Traditions", description = "He ran off with it! Oh what am I going to do, what am I going to DO?\n\nMy son, and my knife, they ran off to Blackrock Spire! Well, the knife didn't run, I suppose. That doesn't matter!\n\nYou've got to get it back! Yes, the knife! You've got to get me back my knife!\n\nGo! Now! Stop talking!", objectives = "Find Pip's Improved Skinner in Blackrock Spire.", progress = "Where's my knife?", completion = "You found it! It's safe! I was so worried! Take this, take it!" }
WordHunterWoW_QuestEN[37162] = { title = "Damsels and Dragons", description = "What ho, squire {name}! Forgive my lips, as they bear gravest news. Dragons have taken up stinking residence within the hallowed halls of Blackrock Spire!\n\nThese great wyrms hold a distressed damsel in their scaly graspers. Her name is Zaela, they say. Such a beautiful name!\n\nAs my squire, it is your Light-given duty to adventure yourself into this spire and procure evidence of these dragons, lest I waste my heroism on a dragonless quest.", objectives = "Collect a Shed Proto-Dragon Claw.", progress = "Did you find evidence of dragons?", completion = "This is dire evidence indeed! I shall head there presently, to slay no less than twenty of the great beasts.\n\nFor Doloria!" }
WordHunterWoW_QuestEN[37163] = { title = "Shadowy Secrets", description = "Though the Lich King has been defeated, we are no closer to unlocking the secrets of the Frozen Throne than we were when jousting pointlessly at the Argent Tournament. Bolvar remains resigned to his fate.\n\nPerhaps there is something here, though, that can aid us. Ner'zhul was not always the Lich King, you know. Once, he was a mere orc dabbling in dark powers beyond his comprehension.\n\nFind whatever you can of his early studies, and we may have our answers.", objectives = "Collect a Dark Parchment from the Shadowmoon Burial Grounds.", progress = "Did you find any of Ner'zhul's notes?", completion = "You have my thanks. I will bring this back to the Ebon Hold immediately.\n\nTake this, I... acquired it... from one of the Shadowmoon." }
WordHunterWoW_QuestEN[37164] = { title = "The Huntresses", description = "I do not wish to come out of the shadows, but I mean you no harm. My purpose here is my own secret to keep, I simply needed a warm place to bed down for the night.\n\nI can see that you are not the type to be easily swayed into leaving. Very well, perhaps you can aid me in my search.\n\nI am looking for someone, it is not important who. All you need to know is that I will reward you for any sign of high elven weaponry that you should come across.", objectives = "Collect a Silver-Lined Arrow from the Shadowmoon Burial Ground.", progress = "Did you find anything?", completion = "This is... it can't be.\n\nI must be off, here is your reward. I do not part with it lightly..." }
WordHunterWoW_QuestEN[37165] = { title = "Cenarion Concerns", description = "Ey mon!\n\nDe Cenarion Circle sent Zen'kiki out here ta check out dem primals. I woulda been here sooner, but I had a little bit o' trouble gettin' my flight form ta work, mon.\n\nDe plants in dis place... I can hear dem talk. Dey be yellin' all the time. Angry an' violent yellin'.\n\nWould ya bring Zen'kiki back a leaf from dis Everbloom place dey be talkin' about? Maybe I can figure out what dey want.", objectives = "Collect a Strangely-Glowing Frond from Everbloom.", progress = "Did ya have much luck, mon?", completion = "Dis... is no good. Dey want to consume da whole planet. How did dey get so angry? What happened to dem? I'm gonna bring dis back to da Circle, we probably gonna need your help again soon.\n\nOne of dem fronds be a bit magical, you hold onto it for a bit." }
WordHunterWoW_QuestEN[37166] = { title = "Titanic Evolution", description = "Ah, hello! Do not look so surprised! Did I not also brave the dangers of the Mogu'shan Vaults? I am more sturdy than I look!\n\nI have learned many things of this wonderful place in history already. Did you know that, just like on our world, the titans once came to this place?\n\nAt least, that is what I believe! Surely there are signs of the titans' presence here, even now. Should you find one, I would very much like to see it!", objectives = "Collect an Overgrown Artifact from The Everbloom.", progress = "Have you found any signs of the titans here?", completion = "This is precisely what I was hoping for! I shall begin to study it immediately.\n\nWhile you were away, I collected these pretty flowers for you!" }
WordHunterWoW_QuestEN[37167] = { title = "And No Maces!", description = "There are far too many bright-eyed young rogues being sent through this portal and off to war. If I'm going to start up my academy again, some of them have got to survive this little excursion.\n\nWhile I'm here, I figured I might as well use the opportunity to gather some supplies for my grand opening. You can't start a business without plenty of daggers, after all.\n\nGrab me a crate of weaponry from the Grimrail Depot, there should be plenty lying around. I'll have something nice for you.", objectives = "Collect a Huge Crate of Weapons in Grimrail Depot.", progress = "Did you find me some weapons?", completion = "Yes, these will do nicely. My thanks, and here is your reward.\n\nTry not to die, I may need you again." }
WordHunterWoW_QuestEN[37168] = { title = "Leorajh, the Enlightened", description = "", objectives = "<The strangely gentle saberon brings a massive paw to his chest.>\n\nMe Leorajh. Not like others. Was small... weak. Banished from clan. Not Bloodmane anymore...\n\nLeorajh find cave. Find stone of sunlight. Learn much from stone. Want learn more. Want new clan.\n\nYou strong. Have clan?\n\nLeorajh join?" }
WordHunterWoW_QuestEN[37169] = { title = "Apexis Guardian Ziri'ak", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[37175] = { title = "Craig's Test Quest Again!", description = "An honorable person gives me clothYou will receive:", objectives = "Get Omar some cloth" }
WordHunterWoW_QuestEN[37177] = { title = "Call of the Talon King", description = "{name}, you have done much for my people. I wish to thank you on their behalf.\n\nPlease visit Veil Terokk when you can.", objectives = "Speak with the Shade of Terokk in Veil Terokk.", completion = "Thank you for coming." }
WordHunterWoW_QuestEN[37179] = { title = "For The Children!", description = "Wait, wait! Don't attack me! I've changed!\n\nReally, I've turned over a new leaf, I promise. I haven't said \"DOOOOOOM!\" in months! All I care about now is saving the poor little orphans of Azeroth, whose parents have been taken by this tragic war.\n\nThat's why I'm here! Why, with just a single Miniature Iron Star, I could provide clean water and power for all of the orphans of Azeroth! And no one could stop me!\n\nSo, what do you think, sweetcheeks? Want to help ol' Milhouse save the orphans?", objectives = "Collect a Miniature Iron Star from Upper Blackrock Spire.", progress = "Did you find the Iron Star?", completion = "You know, you're quite handy, and awfully powerful. Why don't I just follow you for a while?\n\nLook out Draenor, DOOOOOOOOM is coming!" }
WordHunterWoW_QuestEN[37180] = { title = "An Ogre Without His Sword...", description = "Before I was shipped off to Gorgrond, I was stationed at the Broken Precipice in Nagrand, maintaining order over the unruly dredges. Vizier Dar'gud refused to let me take my favorite sword; he told me \"I wouldn't need it where I was going.\"\n\nI want it back, commander, and we are powerful enough together to take it from Dar'gud's bloody corpse.\n\nIt would mean a great deal to me. An ogre without his sword isn't an ogre at all.", objectives = "Retrieve Tormmok's Favorite Sword from Vizier Dar'gud at Broken Precipice in Nagrand.", progress = "I want my sword more than I can tell you, commander.", completion = "Yes... this is it.\n\nCommander, I will cleave your foes like never before now that I have my sword." }
WordHunterWoW_QuestEN[37181] = { title = "Leorajh's Prayer Beads", description = "When Leorajh became shaman, pridelord gave prayer beads. Beads help Leorajh hear elements.\n\nOne day bird-men attacked and took prayer beads. Took them to Skettis.\n\nMaster, you help Leorajh get prayer beads back?", objectives = "Retrieve Leorajh's Prayer Beads from Kirox the Wind Dancer in Skettis.", progress = "Elements don't speak to Leorajh like they used to.", completion = "Thank you, master! Elements speak to Leorajh again." }
WordHunterWoW_QuestEN[37182] = { title = "Scrying Hard or Hardly Scrying", description = "There are others that harness the shadows to do their bidding. You know of them, commander... the Shadowmoon orcs.\n\nThey have begun to master their craft... they call to the shadows beyond this realm...\n\nI desire their power. They have one who possesses a staff of particular interest... we should claim it as our own.", objectives = "Retrieve Urna's Fathomstaff from Urna Darkfathom at Shadowmoon Enclave in Shadowmoon Valley.", progress = "Taking out our enemies and gaining great power in one motion... my people have a saying for this: Killing two orcs with one stone.", completion = "Yes... yes... this will do nicely. We can use this to do great things.\n\nThank you, commander." }
WordHunterWoW_QuestEN[37183] = { title = "The Critical Path", description = "The auburn forests of Talador sit at a critical crossroads of this continent, commander. The Iron Horde's fleet is already en route from Gorgrond to Shattrath on the west coast.\n\nTalador will fall if we don't reinforce them. I took the liberty of dispatching Foreman Eksos, who has already begun construction on an outpost for your forces not far from the Iron Horde landing point. He awaits your orders sir.", objectives = "Speak to Dungar Longdrink to secure a flight to Talador.", completion = "I won't waste any of your time, sir. Let us discuss strategy." }
WordHunterWoW_QuestEN[37184] = { title = "Taking the Fight to Nagrand", description = "Commander, good to see you. With the fall of the rangari base at Telaar, Vindicator Yrel, recommended that we establish a new foothold in Nagrand.\n\nI've taken the liberty of dispatching some of our men and supplies. Rangari D'kaan's already reporting that the outpost is nearly complete. He asked me to let you know they are ready for you.\n\nA gryphon is waiting to catch you up with the latest caravan shipment whenever you're ready, sir.", objectives = "Speak with Lieutenant Balfor at the caravan in Nagrand.", completion = "They came at us... from... nowhere.\n\n<The lieutenant nearly passes out.>" }
WordHunterWoW_QuestEN[37185] = { title = "A Personal Summons", description = "", objectives = "" }
WordHunterWoW_QuestEN[37186] = { title = "The Art of War", description = "", objectives = "" }
WordHunterWoW_QuestEN[37187] = { title = "The Dark Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[37188] = { title = "A Flash of Bronze...", description = "", objectives = "" }
WordHunterWoW_QuestEN[37189] = { title = "A Personal Summons", description = "", objectives = "" }
WordHunterWoW_QuestEN[37190] = { title = "Iron Horde Invasion", description = "", objectives = "" }
WordHunterWoW_QuestEN[37191] = { title = "Sanketsu, The Burning Blade", description = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.\n\nPerhaps someone at your garrison would be interested in seeing this weapon.", objectives = "Bring Sanketsu, the Burning Blade, to Lieutenant Thorn at your garrison.", completion = "<Lieutenant Thorn handles the weapon, her keen eyes taking note of every line, edge, and scratch. After several moments, she speaks.>\n\nMagnificent.\n\nThis blade was honed by a master craftsman, and imbued with ancient magic.\n\nJust imagine if such a powerful weapon were placed in the hands of a skilled warrior..." }
WordHunterWoW_QuestEN[37192] = { title = "Sanketsu, The Burning Blade", description = "The blade is searing hot to the touch. The jewel on its hilt stares at you, as if daring you to claim it.\n\nPerhaps someone at your garrison would be interested in seeing this weapon.", objectives = "Bring Sanketsu, the Burning Blade, to Warmaster Zog at your garrison.", completion = "<Warmaster Zog lifts the blade into the air, admiring its balance and heft.>\n\nNever have I seen a weapon such as this. It was clearly made by a master, imbued with ancient magic, and tested in many a battle.\n\nCommander, I will leave the choice to you, but it would be an honor to see this blade placed in service of this garrison." }
WordHunterWoW_QuestEN[37193] = { title = "The King's Command", description = "", objectives = "" }
WordHunterWoW_QuestEN[37194] = { title = "A Flash of Bronze...", description = "", objectives = "" }
WordHunterWoW_QuestEN[37195] = { title = "The Dark Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[37196] = { title = "Iron Horde Invasion", description = "", objectives = "" }
WordHunterWoW_QuestEN[37197] = { title = "See Rexxar Quest Giver 002", description = "", objectives = "" }
WordHunterWoW_QuestEN[37198] = { title = "Garrison Visitor: Sappy", description = "", objectives = "" }
WordHunterWoW_QuestEN[37199] = { title = "Garrison Visitor: Sappy", description = "", objectives = "" }
WordHunterWoW_QuestEN[37201] = { title = "Cymre Brightblade", description = "I found some interesting artifacts on a recent dig, and I'd love to put them through their paces to see how they would have performed in their native cultures.  Don't suppose you have anything small and furry that can put up a fight?", objectives = "Defeat Cymre Brightblade in a pet battle.", progress = "Did you want to pet battle or just talk...", completion = "Thanks for helping me test out these artifacts." }
WordHunterWoW_QuestEN[37202] = { title = "Hemet Nesingwary Visitor Tracking Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[37203] = { title = "Ashlei", description = "I don't really like when my pets fight, but I love making them feel better when they're done.", objectives = "Defeat Ashlei in a pet battle.", progress = "Hi.", completion = "That was fun." }
WordHunterWoW_QuestEN[37204] = { title = "Rekindling an Old Flame", description = "I am dying, {race}. My flame, it smolders... soon my light will flicker and fade into nothing.\n\nYou mustn't allow this. Retrieve for me the Essence of Flame. Allow me to live another day and I will burn every breaker to ash, I swear it.\n\nI will take vengeance for my brothers and sisters.", objectives = "Deliver the Essence of Flame to Firaga in Magnarok.", progress = "Do you have it, <name>? Will you kindle my flame?", completion = "The flames, they burn within me!" }
WordHunterWoW_QuestEN[37205] = { title = "Gargra", description = "Do you wish to offer challenge?  My wolves must train to become strong.", objectives = "Defeat Gargra in a pet battle.", progress = "My wolves grow restless.", completion = "You have helped my pups train, and for that I give thanks." }
WordHunterWoW_QuestEN[37206] = { title = "Tarr the Terrible", description = "Tarr is the true warlord!  Bring your army to fight and I show you.", objectives = "Defeat Tarr the Terrible in a pet battle.", progress = "Tarr destroy your face!", completion = "You lucky this time." }
WordHunterWoW_QuestEN[37207] = { title = "Vesharr", description = "I had a vision with one who had mastered pets came to challenge me.  Has the vision finally come to pass?", objectives = "Defeat Vesharr in a pet battle.", progress = "Can you defeat me?", completion = "The feathers have fallen and shown us much." }
WordHunterWoW_QuestEN[37208] = { title = "Taralune", description = "I strive to teach through non-lethal pet battle.  Are you willing to learn?", objectives = "Defeat Taralune in a pet battle.", progress = "You have not yet learned enough.", completion = "We have learned from each other.  Thank you." }
WordHunterWoW_QuestEN[37209] = { title = "Cold Steel Part II", description = "Hey, you.\n\nI wanted to thank you for what you did for me. The feel of that cannon in my hands is all the therapy I'll ever need. But now...\n\n<Keeshan stares off into the distance and grimaces.>...I'm all out of bullets.\n\nGuess I'll just sit here and wait to die.", objectives = "Find an Iron Autocannon in Grimrail Depot.", progress = "Leave me alone.", completion = "Ah, that's the stuff. I'm going to run out of ammo, but at least I've got something to live for, for a while." }
WordHunterWoW_QuestEN[37210] = { title = "Aogexon's Fang", description = "", objectives = "Aogexon is one of the most feared beasts in Nagrand, and one of the largest and most dangerous forest stalkers ever seen!\n\nI've already been approached by a number of a collectors interested in obtaining one of Aogexon's deadly fangs. If you are up for the challenge, Aogexon can sometimes be found lurking in the swamp not far from here.\n\nGood luck!", progress = "Aogexon is one of the most feared beasts in Nagrand, and one of the largest and most dangerous forest stalkers ever seen!\n\nI've already been approached by a number of a collectors interested in obtaining one of Aogexon's deadly fangs. If you are up for the challenge, Aogexon can sometimes be found lurking in the swamp not far from here.\n\nGood luck!", completion = "Great work, <name>! You've made the swamp a safer place for archaeology and earned us a profit at the same time!" }
WordHunterWoW_QuestEN[37211] = { title = "Bergruu's Horn", description = "", objectives = "An anonymous collector of valuable fossils and antiques has offered the preservation society a huge cash reward for Bergruu's horn.\n\nA huge reward, <name>... HUGE!", progress = "An anonymous collector of valuable fossils and antiques has offered the preservation society a huge cash reward for Bergruu's horn.\n\nA huge reward, <name>... HUGE!", completion = "Wow! I knew Begruu's horn would be big, but I never imagined it would be this massive!\n\nWe're going to have to charge the buyer extra for delivery!" }
